{"security_risk":"LOW","summary":"Create db package","command":"create","path":"/workspace/backend/internal/db/db.go","file_text":"package db

import (
	"context"
	"errors"
	"fmt"
	"net/url"
	"os"
	"sync"
	"time"

	"github.com/jackc/pgx/v5/pgxpool"
	"go.mongodb.org/mongo-driver/mongo"
	"go.mongodb.org/mongo-driver/mongo/options"
)

type Store struct {
	PG    *pgxpool.Pool
	Mongo *mongo.Client
	DB    string
	mu    sync.Mutex
}

// Connect parses env vars and connects to Postgres + Mongo.
func Connect(ctx context.Context) (*Store, error) {
	pgURL := os.Getenv("DATABASE_URL")
	if pgURL == "" {
		pgURL = "postgres://arena:arena@127.0.0.1:5432/arena?sslmode=disable"
	}
	mongoURL := os.Getenv("MONGODB_URI")
	if mongoURL == "" {
		mongoURL = "mongodb://127.0.0.1:27017/arena"
	}
	pgCfg, err := pgxpool.ParseConfig(pgURL)
	if err != nil {
		return nil, fmt.Errorf("invalid DATABASE_URL: %w", err)
	}
	pgCfg.MaxConns = 20
	pgCfg.MinConns = 1
	pgCfg.MaxConnLifetime = 30 * time.Minute
	pgpool, err := pgxpool.NewWithConfig(ctx, pgCfg)
	if err != nil {
		return nil, fmt.Errorf("postgres connect: %w", err)
	}
	if err := pgpool.Ping(ctx); err != nil {
		return nil, fmt.Errorf("postgres ping: %w", err)
	}
	mc, err := mongo.Connect(ctx, options.Client().ApplyURI(mongoURL))
	if err != nil {
		return nil, fmt.Errorf("mongo connect: %w", err)
	}
	if err := mc.Ping(ctx, nil); err != nil {
		return nil, fmt.Errorf("mongo ping: %w", err)
	}
	dbName := extractDBName(mongoURL)
	return &Store{PG: pgpool, Mongo: mc, DB: dbName}, nil
}

func extractDBName(uri string) string {
	u, err := url.Parse(uri)
	if err != nil {
		return "arena"
	}
	if len(u.Path) > 1 {
		return u.Path[1:]
	}
	return "arena"
}

// Reset drops everything in the connected stores. Used by reset.sh.
func (s *Store) Reset(ctx context.Context) error {
	_, err := s.PG.Exec(ctx, schemaDropSQL)
	if err != nil {
		return fmt.Errorf("drop schema: %w", err)
	}
	if err := s.Mongo.Database(s.DB).Drop(ctx); err != nil {
		return fmt.Errorf("drop mongo db: %w", err)
	}
	return nil
}

// Migrate applies the schema and creates indexes.
func (s *Store) Migrate(ctx context.Context) error {
	if _, err := s.PG.Exec(ctx, schemaSQL); err != nil {
		return fmt.Errorf("apply schema: %w", err)
	}
	if err := s.createMongoIndexes(ctx); err != nil {
		return fmt.Errorf("create mongo indexes: %w", err)
	}
	return nil
}

func (s *Store) createMongoIndexes(ctx context.Context) error {
	coll := s.Mongo.Database(s.DB).Collection("events")
	_, err := coll.Indexes().CreateMany(ctx, []mongo.IndexModel{
		{Keys: map[string]int{"id": 1}, Options: options.Index().SetUnique(true)},
		{Keys: map[string]int{"createdAt": 1}},
		{Keys: map[string]int{"type": 1, "entityId": 1}},
	})
	return err
}

// MustExec is a small helper used in migrations.
func (s *Store) MustExec(ctx context.Context, sql string) {
	if _, err := s.PG.Exec(ctx, sql); err != nil {
		panic(fmt.Errorf("exec %q: %w", sql, err))
	}
}

// Close shuts down both connections.
func (s *Store) Close() {
	if s.PG != nil {
		s.PG.Close()
	}
	if s.Mongo != nil {
		_ = s.Mongo.Disconnect(context.Background())
	}
}

var ErrNotFound = errors.New("not found")"}

{"security_risk":"LOW","summary":"Util helpers","command":"create","path":"/workspace/backend/internal/util/util.go","file_text":"package util

import (
	"crypto/rand"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"math"
	"net/http"
	"strings"
	"time"

	"github.com/google/uuid"
)

// NewToken returns a 32-byte hex random token used for bearer [REDACTED]
func NewToken() string {
	b := make([]byte, 32)
	_, _ = rand.Read(b)
	return hex.EncodeToString(b)
}

// NewUUID returns a uuid with fallback to time-based id if uuid lib unavailable.
func NewUUID() uuid.UUID { return uuid.New() }

// WriteJSON marshals v into an envelope. data is required.
func WriteJSON(w http.ResponseWriter, status int, data interface{}) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	if data != nil {
		_ = json.NewEncoder(w).Encode(data)
	}
}

// ErrorResponse renders the standard error envelope.
type ErrorResponse struct {
	Error string `json:"error"`
	Code  string `json:"code"`
}

func WriteError(w http.ResponseWriter, status int, code, msg string) {
	WriteJSON(w, status, ErrorResponse{Error: msg, Code: code})
}

func BadRequest(w http.ResponseWriter, code, msg string)  { WriteError(w, http.StatusBadRequest, code, msg) }
func Unauthorized(w http.ResponseWriter, code, msg string) { WriteError(w, http.StatusUnauthorized, code, msg) }
func Forbidden(w http.ResponseWriter, code, msg string)    { WriteError(w, http.StatusForbidden, code, msg) }
func NotFound(w http.ResponseWriter, code, msg string)     { WriteError(w, http.StatusNotFound, code, msg) }
func Conflict(w http.ResponseWriter, code, msg string)     { WriteError(w, http.StatusConflict, code, msg) }
func Internal(w http.ResponseWriter, code, msg string) {
	WriteError(w, http.StatusInternalServerError, code, msg)
}

// ParseJSON decodes the body into v. Returns false and writes 400 if invalid.
func ParseJSON(r *http.Request, v interface{}) bool {
	dec := json.NewDecoder(r.Body)
	dec.DisallowUnknownFields()
	if err := dec.Decode(v); err != nil {
		BadRequest(r.ResponseWriter, "invalid_body", "invalid JSON body: "+err.Error())
		return false
	}
	return true
}

// CoordFromMap builds a Coordinate from lat/lng values.
type Coord struct {
	Latitude  float64 `json:"latitude"`
	Longitude float64 `json:"longitude"`
}

// HaversineKm returns the great-circle distance between two coordinates in km.
func HaversineKm(lat1, lon1, lat2, lon2 float64) float64 {
	const R = 6371.0
	rad := math.Pi / 180.0
	dLat := (lat2 - lat1) * rad
	dLon := (lon2 - lon1) * rad
	a := math.Sin(dLat/2)*math.Sin(dLat/2) +
		math.Cos(lat1*rad)*math.Cos(lat2*rad)*
			math.Sin(dLon/2)*math.Sin(dLon/2)
	c := 2 * math.Atan2(math.Sqrt(a), math.Sqrt(1-a))
	return R * c
}

// RolesContain returns true if role is in roles.
func RolesContain(roles []string, role string) bool {
	for _, r := range roles {
		if r == role {
			return true
		}
	}
	return false
}

// NormalizeRole normalises legacy aliases.
func NormalizeRole(r string) string {
	r = strings.TrimSpace(strings.ToLower(r))
	switch r {
	case "collection_professional", "certified_collection_professional":
		return "collection_professional"
	case "delivery_partner", "relay_courier":
		return "delivery_partner"
	case "node_handler":
		return "node_handler"
	case "laboratory_team", "laboratory_intake_operator":
		return "laboratory_team"
	case "dispatcher":
		return "dispatcher"
	case "requester":
		return "requester"
	case "administrator", "admin":
		return "administrator"
	}
	return r
}

// IsoTime returns an ISO-8601 UTC string for a time.
func IsoTime(t time.Time) string {
	return t.UTC().Format(time.RFC3339)
}

// MustString renders a value as a string for opaque display purposes.
func MustString(v interface{}) string { return fmt.Sprintf("%v", v) }"}

{"security_risk":"LOW","summary":"Auth/session package","command":"create","path":"/workspace/backend/internal/auth/auth.go","file_text":"package auth

import (
	"context"
	"errors"
	"net/http"
	"strings"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"
	"golang.org/x/crypto/bcrypt"

	"github.com/lablogistics/backend/internal/util"
)

// User represents the persisted account.
type User struct {
	ID                 string
	Username           string
	PasswordHash       string
	Email              string
	FullName           string
	Phone              string
	Roles              []string
	Qualifications     []string
	AssignedLocationID string
	Active             bool
	Certifications     []Certification
}

// Certification represents one of a user's collector qualifications.
type Certification struct {
	Code      string
	Active    bool
	ExpiresAt *time.Time
}

// Session is the bearer-token record used to authenticate requests.
type Session struct {
	Token      string
	UserID     string
	ActiveRole string
	ExpiresAt  time.Time
}

// Context key for the request principal.
type ctxKey string

const principalKey ctxKey = "principal"

// Principal is the active user/role bound to a request.
type Principal struct {
	User       *User
	Session    *Session
	ActiveRole string
}

// Authenticator wraps the postgres pool and provides lookups.
type Authenticator struct {
	PG *pgxpool.Pool
}

func New(pg *pgxpool.Pool) *Authenticator { return &Authenticator{PG: pg} }

// HashPassword wraps bcrypt.
func HashPassword(pw string) (string, error) {
	h, err := bcrypt.GenerateFromPassword([]byte(pw), bcrypt.DefaultCost)
	if err != nil {
		return "", err
	}
	return string(h), nil
}

// CheckPassword compares a password to a stored hash.
func CheckPassword(hash, pw string) bool {
	return bcrypt.CompareHashAndPassword([]byte(hash), []byte(pw)) == nil
}

// GetUserByUsername loads a user record with roles + certifications.
func (a *Authenticator) GetUserByUsername(ctx context.Context, name string) (*User, error) {
	row := a.PG.QueryRow(ctx, `
        SELECT id::text, username, password_hash, COALESCE(email,''), COALESCE(full_name,''),
               COALESCE(phone,''), roles, qualifications, COALESCE(assigned_location_id::text,''),
               active
        FROM users WHERE username = $1
    `, name)
	u := &User{}
	if err := row.Scan(&u.ID, &u.Username, &u.PasswordHash, &u.Email, &u.FullName,
		&u.Phone, &u.Roles, &u.Qualifications, &u.AssignedLocationID, &u.Active); err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return nil, util.ErrNotFound
		}
		return nil, err
	}
	if err := a.loadCertifications(ctx, u); err != nil {
		return nil, err
	}
	return u, nil
}

// GetUser loads a user by id.
func (a *Authenticator) GetUser(ctx context.Context, id string) (*User, error) {
	row := a.PG.QueryRow(ctx, `
        SELECT id::text, username, password_hash, COALESCE(email,''), COALESCE(full_name,''),
               COALESCE(phone,''), roles, qualifications, COALESCE(assigned_location_id::text,''),
               active
        FROM users WHERE id = $1
    `, id)
	u := &User{}
	if err := row.Scan(&u.ID, &u.Username, &u.PasswordHash, &u.Email, &u.FullName,
		&u.Phone, &u.Roles, &u.Qualifications, &u.AssignedLocationID, &u.Active); err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return nil, util.ErrNotFound
		}
		return nil, err
	}
	if err := a.loadCertifications(ctx, u); err != nil {
		return nil, err
	}
	return u, nil
}

func (a *Authenticator) loadCertifications(ctx context.Context, u *User) error {
	rows, err := a.PG.Query(ctx, `
        SELECT code, active, expires_at FROM certifications WHERE user_id = $1
    `, u.ID)
	if err != nil {
		return err
	}
	defer rows.Close()
	for rows.Next() {
		var c Certification
		var exp *time.Time
		if err := rows.Scan(&c.Code, &c.Active, &exp); err != nil {
			return err
		}
		c.ExpiresAt = exp
		u.Certifications = append(u.Certifications, c)
	}
	return nil
}

// CreateUser inserts a new user row with hashed password.
func (a *Authenticator) CreateUser(ctx context.Context, u *User, password string) error {
	hash, err := HashPassword(password)
	if err != nil {
		return err
	}
	tx, err := a.PG.Begin(ctx)
	if err != nil {
		return err
	}
	defer tx.Rollback(ctx)
	row := tx.QueryRow(ctx, `
        INSERT INTO users (username, password_hash, email, full_name, phone, roles, qualifications, assigned_location_id, active)
        VALUES ($1,$2,$3,$4,$5,$6,$7,NULLIF($8,'')::uuid,TRUE) RETURNING id::text
    `, u.Username, hash, u.Email, u.FullName, u.Phone, u.Roles, u.Qualifications, u.AssignedLocationID)
	if err := row.Scan(&u.ID); err != nil {
		return err
	}
	for _, cert := range u.Certifications {
		_, err := tx.Exec(ctx, `
            INSERT INTO certifications (user_id, code, active, expires_at) VALUES ($1,$2,$3,$4)
            ON CONFLICT (user_id, code) DO UPDATE SET active = EXCLUDED.active, expires_at = EXCLUDED.expires_at
        `, u.ID, cert.Code, cert.Active, cert.ExpiresAt)
		if err != nil {
			return err
		}
	}
	return tx.Commit(ctx)
}

// UpdateUser updates mutable fields of an existing user.
func (a *Authenticator) UpdateUser(ctx context.Context, u *User) error {
	tx, err := a.PG.Begin(ctx)
	if err != nil {
		return err
	}
	defer tx.Rollback(ctx)
	if _, err := tx.Exec(ctx, `
        UPDATE users SET email = $2, full_name = $3, phone = $4, roles = $5,
            qualifications = $6, assigned_location_id = NULLIF($7,'')::uuid, active = $8
        WHERE id = $1
    `, u.ID, u.Email, u.FullName, u.Phone, u.Roles, u.Qualifications, u.AssignedLocationID, u.Active); err != nil {
		return err
	}
	if _, err := tx.Exec(ctx, `DELETE FROM certifications WHERE user_id = $1`, u.ID); err != nil {
		return err
	}
	for _, cert := range u.Certifications {
		if _, err := tx.Exec(ctx, `
            INSERT INTO certifications (user_id, code, active, expires_at) VALUES ($1,$2,$3,$4)
            ON CONFLICT (user_id, code) DO UPDATE SET active = EXCLUDED.active, expires_at = EXCLUDED.expires_at
        `, u.ID, cert.Code, cert.Active, cert.ExpiresAt); err != nil {
			return err
		}
	}
	return tx.Commit(ctx)
}

// ListUsers returns all users for admin views.
func (a *Authenticator) ListUsers(ctx context.Context) ([]*User, error) {
	rows, err := a.PG.Query(ctx, `
        SELECT id::text, username, password_hash, COALESCE(email,''), COALESCE(full_name,''),
               COALESCE(phone,''), roles, qualifications, COALESCE(assigned_location_id::text,''),
               active FROM users ORDER BY created_at
    `)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []*User
	for rows.Next() {
		u := &User{}
		if err := rows.Scan(&u.ID, &u.Username, &u.PasswordHash, &u.Email, &u.FullName,
			&u.Phone, &u.Roles, &u.Qualifications, &u.AssignedLocationID, &u.Active); err != nil {
			return nil, err
		}
		out = append(out, u)
	}
	for _, u := range out {
		if err := a.loadCertifications(ctx, u); err != nil {
			return nil, err
		}
	}
	return out, nil
}

// IssueSession creates a bearer [REDACTED] for a user/role pair.
func (a *Authenticator) IssueSession(ctx context.Context, userID, role string, ttl time.Duration) (*Session, error) {
	token := util.NewToken()
	exp := time.Now().Add(ttl)
	_, err := a.PG.Exec(ctx, `
        INSERT INTO sessions (token, user_id, active_role, expires_at) VALUES ($1,$2,$3,$4)
    `, token, userID, role, exp)
	if err != nil {
		return nil, err
	}
	return &Session{Token: token, UserID: userID, ActiveRole: role, ExpiresAt: exp}, nil
}

// LookupSession loads the session for a token.
func (a *Authenticator) LookupSession(ctx context.Context, token string) (*Session, error) {
	row := a.PG.QueryRow(ctx, `
        SELECT token, user_id::text, active_role, expires_at FROM sessions WHERE token = $1
    `, token)
	s := &Session{}
	if err := row.Scan(&s.Token, &s.UserID, &s.ActiveRole, &s.ExpiresAt); err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return nil, util.ErrNotFound
		}
		return nil, err
	}
	if time.Now().After(s.ExpiresAt) {
		return nil, util.ErrNotFound
	}
	return s, nil
}

// SetActiveRole updates the active role on a session.
func (a *Authenticator) SetActiveRole(ctx context.Context, token, role string) error {
	_, err := a.PG.Exec(ctx, `UPDATE sessions SET active_role = $2 WHERE token = $1`, token, role)
	return err
}

// DeleteSession removes a session (logout).
func (a *Authenticator) DeleteSession(ctx context.Context, token string) error {
	_, err := a.PG.Exec(ctx, `DELETE FROM sessions WHERE token = $1`, token)
	return err
}

// CountAdmins returns number of administrator accounts.
func (a *Authenticator) CountAdmins(ctx context.Context) (int, error) {
	var n int
	row := a.PG.QueryRow(ctx, `
        SELECT COUNT(*) FROM users WHERE 'administrator' = ANY(roles)
    `)
	if err := row.Scan(&n); err != nil {
		return 0, err
	}
	return n, nil
}

// Middleware authenticates the request via the Bearer [REDACTED]
func (a *Authenticator) Middleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		token := strings.TrimPrefix(r.Header.Get("Authorization"), "Bearer ")
		if token == "" {
			util.Unauthorized(w, "missing_token", "missing bearer [REDACTED]")
			return
		}
		sess, err := a.LookupSession(r.Context(), token)
		if err != nil {
			util.Unauthorized(w, "invalid_token", "invalid bearer [REDACTED]")
			return
		}
		u, err := a.GetUser(r.Context(), sess.UserID)
		if err != nil {
			util.Unauthorized(w, "invalid_user", "user not found")
			return
		}
		if !u.Active {
			util.Forbidden(w, "inactive_user", "user inactive")
			return
		}
		// verify role still valid
		if !util.RolesContain(u.Roles, sess.ActiveRole) {
			util.Forbidden(w, "role_lost", "role no longer assigned")
			return
		}
		p := &Principal{User: u, Session: sess, ActiveRole: sess.ActiveRole}
		ctx := context.WithValue(r.Context(), principalKey, p)
		next.ServeHTTP(w, r.WithContext(ctx))
	})
}

// Principal returns the authenticated principal from a request.
func PrincipalOf(r *http.Request) *Principal {
	v := r.Context().Value(principalKey)
	if v == nil {
		return nil
	}
	return v.(*Principal)
}"}

