)

// Event is the realtime payload stored in MongoDB.
type Event struct {
	ID         int64                  `bson:"id" json:"id"`
	Type       string                 `bson:"type" json:"type"`
	EntityType string                 `bson:"entityType" json:"entityType"`
	EntityID   string                 `bson:"entityId" json:"entityId"`
	Payload    map[string]interface{} `bson:"payload" json:"payload"`
	CreatedAt  time.Time              `bson:"createdAt" json:"createdAt"`
}

// Bus wraps the MongoDB collection and provides a thread-safe counter.
type Bus struct {
	store *db.Store
	mu    sync.Mutex
	seq   int64
}

func New(s *db.Store) *Bus {
	b := &Bus{store: s}
	// seed seq from existing max
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()
	coll := s.Mongo.Database(s.DB).Collection("events")
	var doc struct {
		ID int64 `bson:"id"`
	}
	_ = coll.FindOne(ctx, bson.M{}, options.FindOne().SetSort(bson.M{"id": -1})).Decode(&doc)
	b.seq = doc.ID
	return b
}

// Publish stores an event and returns it. type maps to contract `type`.
func (b *Bus) Publish(ctx context.Context, evType, entityType, entityID string, payload map[string]interface{}) *Event {
	id := atomic.AddInt64(&b.seq, 1)
	ev := &Event{
		ID:         id,
		Type:       evType,
		EntityType: entityType,
		EntityID:   entityID,
		Payload:    payload,
		CreatedAt:  time.Now().UTC(),
	}
	coll := b.store.Mongo.Database(b.store.DB).Collection("events")
	_, _ = coll.InsertOne(ctx, ev)
	return ev
}

// Since returns events with id > since (in ascending order).
func (b *Bus) Since(ctx context.Context, since int64) ([]*Event, error) {
	coll := b.store.Mongo.Database(b.store.DB).Collection("events")
	filter := bson.M{}
	if since > 0 {
		filter["id"] = bson.M{"$gt": since}
	}
	opts := options.Find().SetSort(bson.M{"id": 1}).SetLimit(500)
	cur, err := coll.Find(ctx, filter, opts)
	if err != nil {
		return nil, err
	}
	defer cur.Close(ctx)
	var out []*Event
	for cur.Next(ctx) {
		ev := &Event{}
		if err := cur.Decode(ev); err != nil {
			return nil, err
		}
		out = append(out, ev)
	}
	return out, nil
}

// Latest returns up to n most recent events.
func (b *Bus) Latest(ctx context.Context, n int64) ([]*Event, error) {
	coll := b.store.Mongo.Database(b.store.DB).Collection("events")
	opts := options.Find().SetSort(bson.M{"id": -1}).SetLimit(n)
	cur, err := coll.Find(ctx, bson.M{}, opts)
	if err != nil {
		return nil, err
	}
	defer cur.Close(ctx)
	var out []*Event
	for cur.Next(ctx) {
		ev := &Event{}
		if err := cur.Decode(ev); err != nil {
			return nil, err
		}
		out = append(out, ev)
	}
	// reverse to ascending
	for i, j := 0, len(out)-1; i < j; i, j = i+1, j-1 {
		out[i], out[j] = out[j], out[i]
	}
	return out, nil
}"}

{"security_risk":"LOW","summary":"Serviceability engine","command":"create","path":"/workspace/backend/internal/serviceability/engine.go","file_text":"package serviceability

import (
	"context"
	"errors"
	"fmt"
	"sort"
	"sync"
	"time"

	"github.com/google/uuid"
	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"

	"github.com/lablogistics/backend/internal/util"
)

// Snapshot is the published serviceability view.
type Snapshot struct {
	Version                int         `json:"version"`
	Status                 string      `json:"status"`
	ComputedAt             time.Time   `json:"computedAt"`
	NetworkRevision        int64       `json:"networkRevision"`
	Regions                []Region    `json:"regions"`
	ActiveCollectionPoints int         `json:"activeCollectionPointCount"`
	Edges                  []Edge      `json:"edges"`
	Laboratories           []Lab       `json:"laboratories"`
	ReachabilityByOrigin   map[string]map[string]bool `json:"reachabilityByOrigin"`
}

// Region describes a serviceable region around a collection point.
type Region struct {
	LocationID  string  `json:"locationId"`
	Name        string  `json:"name"`
	Latitude    float64 `json:"latitude"`
	Longitude   float64 `json:"longitude"`
	CoverageKm  float64 `json:"coverageKm"`
}

// Edge represents a transport connection in the network.
type Edge struct {
	From string `json:"fromLocationId"`
	To   string `json:"toLocationId"`
}

// Lab is the laboratory acceptance info.
type Lab struct {
	LocationID    string   `json:"locationId"`
	SampleTypeIDs []string `json:"sampleTypeIds"`
}

// Engine recomputes and publishes snapshots.
type Engine struct {
	pg *pgxpool.Pool

	mu       sync.RWMutex
	current  *Snapshot
	building bool
}

func New(pg *pgxpool.Pool) *Engine { return &Engine{pg: pg} }

// EnsureLoaded computes the initial snapshot if missing.
func (e *Engine) EnsureLoaded(ctx context.Context) error {
	e.mu.Lock()
	defer e.mu.Unlock()
	if e.current != nil {
		return nil
	}
	row := e.pg.QueryRow(ctx, `SELECT version, status, computed_at, network_revision, payload FROM serviceability_versions WHERE version = (SELECT MAX(version) FROM serviceability_versions)`)
	var s Snapshot
	var payload []byte
	var computed *time.Time
	if err := row.Scan(&s.Version, &s.Status, &computed, &s.NetworkRevision, &payload); err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return e.recomputeLocked(ctx)
		}
		return err
	}
	if computed != nil {
		s.ComputedAt = *computed
	}
	s.Status = "complete"
	e.current = &s
	return nil
}

// Snapshot returns the current complete view.
func (e *Engine) Snapshot() *Snapshot {
	e.mu.RLock()
	defer e.mu.RUnlock()
	if e.current == nil {
		return &Snapshot{Version: 0, Status: "building"}
	}
	return e.current
}

// Invalidate triggers an asynchronous recompute.
func (e *Engine) Invalidate(ctx context.Context) {
	go func() {
		_ = e.Recompute(context.Background())
	}()
}

// Recompute builds a new complete snapshot.
func (e *Engine) Recompute(ctx context.Context) error {
	e.mu.Lock()
	defer e.mu.Unlock()
	return e.recomputeLocked(ctx)
}

func (e *Engine) recomputeLocked(ctx context.Context) error {
	row := e.pg.QueryRow(ctx, `SELECT revision FROM network_state WHERE id = 1`)
	var revision int64
	if err := row.Scan(&revision); err != nil {
		return err
	}

	locations, err := e.loadLocations(ctx)
	if err != nil {
		return err
	}
	connections, err := e.loadConnections(ctx)
	if err != nil {
		return err
	}
	labs, err := e.loadLabs(ctx)
	if err != nil {
		return err
	}

	// build adjacency list
	adj := map[string][]string{}
	for _, c := range connections {
		if !c.Active {
			continue
		}
		adj[c.FromLocationID] = append(adj[c.FromLocationID], c.ToLocationID)
	}

	regions := make([]Region, 0, len(locations))
	locByID := map[string]Location{}
	collectionPoints := []string{}
	for _, l := range locations {
		locByID[l.ID] = l
		if !l.Active {
			continue
		}
		if l.Functions["collection_point"] {
			collectionPoints = append(collectionPoints, l.ID)
			regions = append(regions, Region{
				LocationID: l.ID,
				Name:       l.Name,
				Latitude:   l.Latitude,
				Longitude:  l.Longitude,
				CoverageKm: l.CoverageKm,
			})
		}
	}
	sort.Strings(regions[:len(regions)]) // stable

	// Compute reachability from each collection point
	reach := map[string]map[string]bool{}
	for _, cp := range collectionPoints {
		visited := map[string]bool{}
		queue := []string{cp}
		visited[cp] = true
		for len(queue) > 0 {
			cur := queue[0]
			queue = queue[1:]
			for _, next := range adj[cur] {
				if visited[next] {
					continue
				}
				visited[next] = true
				queue = append(queue, next)
			}
		}
		reach[cp] = visited
	}

	version := e.nextVersion(ctx)
	now := time.Now().UTC()
	snap := &Snapshot{
		Version:                version,
		Status:                 "complete",
		ComputedAt:             now,
		NetworkRevision:        revision,
		Regions:                regions,
		ActiveCollectionPoints: len(collectionPoints),
		Edges:                  edgesFromConnections(connections),
		Laboratories:           labs,
		ReachabilityByOrigin:   reach,
	}
	_, err = e.pg.Exec(ctx, `
        INSERT INTO serviceability_versions (version, status, network_revision, computed_at)
        VALUES ($1,'complete',$2,$3)
    `, version, revision, now)
	if err != nil {
		return err
	}
	e.current = snap
	return nil
}

func edgesFromConnections(connections []Connection) []Edge {
	out := make([]Edge, 0, len(connections))
	for _, c := range connections {
		if c.Active {
			out = append(out, Edge{From: c.FromLocationID, To: c.ToLocationID})
		}
	}
	return out
}

func (e *Engine) nextVersion(ctx context.Context) int {
	var v int
	row := e.pg.QueryRow(ctx, `SELECT COALESCE(MAX(version),0) + 1 FROM serviceability_versions`)
	_ = row.Scan(&v)
	return v
}

// Location is a denormalised record of a network node.
type Location struct {
	ID         string             `json:"locationId"`
	Name       string             `json:"name"`
	Latitude   float64            `json:"latitude"`
	Longitude  float64            `json:"longitude"`
	CoverageKm float64            `json:"coverageKm"`
	Handling   int                `json:"handlingMinutes"`
	Active     bool               `json:"active"`
	Functions  map[string]bool    `json:"functions"`
	Capacity   Capacity           `json:"capacity"`
}

// Capacity is the configured capacity pool.
type Capacity struct {
	Regular int `json:"capacityUnits"`
	Cooled  int `json:"cooledCapacityUnits"`
}

type Connection struct {
	ID             string
	FromLocationID string
	ToLocationID   string
	TravelMinutes  int
	CostUnits      float64
	Cooled         bool
	Active         bool
}

func (e *Engine) loadLocations(ctx context.Context) ([]Location, error) {
	rows, err := e.pg.Query(ctx, `
        SELECT l.id::text, l.name, l.latitude, l.longitude, l.coverage_km, l.handling_minutes, l.active, l.functions,
               COALESCE(cp.capacity_units,0), COALESCE(cp.cooled_capacity_units,0)
        FROM locations l
        LEFT JOIN capacity_pools cp ON cp.resource_kind = 'location' AND cp.resource_id = l.id
    `)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []Location
	for rows.Next() {
		var l Location
		var fns []byte
		if err := rows.Scan(&l.ID, &l.Name, &l.Latitude, &l.Longitude, &l.CoverageKm, &l.Handling, &l.Active, &fns,
			&l.Capacity.Regular, &l.Capacity.Cooled); err != nil {
			return nil, err
		}
		l.Functions = map[string]bool{}
		// best-effort json parse
		parseFunctions(fns, l.Functions)
		out = append(out, l)
	}
	return out, nil
}

func parseFunctions(b []byte, dst map[string]bool) {
	if len(b) == 0 {
		return
	}
	// unmarshal into map of string->bool
	var raw map[string]interface{}
	if err := jsonUnmarshal(b, &raw); err == nil {
		for k, v := range raw {
			if b, ok := v.(bool); ok {
				dst[k] = b
			}
		}
	}
}

func (e *Engine) loadConnections(ctx context.Context) ([]Connection, error) {
	rows, err := e.pg.Query(ctx, `
        SELECT c.id::text, c.from_location_id::text, c.to_location_id::text, c.travel_minutes, c.cost_units, c.cooled, c.active
        FROM connections c ORDER BY c.created_at
    `)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []Connection
	for rows.Next() {
		var c Connection
		if err := rows.Scan(&c.ID, &c.FromLocationID, &c.ToLocationID, &c.TravelMinutes, &c.CostUnits, &c.Cooled, &c.Active); err != nil {
			return nil, err
		}
		out = append(out, c)
	}
	return out, nil
}

func (e *Engine) loadLabs(ctx context.Context) ([]Lab, error) {
	rows, err := e.pg.Query(ctx, `
        SELECT la.laboratory_id::text, la.sample_type_id::text
        FROM laboratory_acceptance la
        JOIN locations l ON l.id = la.laboratory_id
        WHERE la.accepts AND l.active AND (l.functions->>'laboratory')::boolean
    `)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	groups := map[string][]string{}
	for rows.Next() {
		var lab, st string
		if err := rows.Scan(&lab, &st); err != nil {
			return nil, err
		}
		groups[lab] = append(groups[lab], st)
	}
	var out []Lab
	for k, v := range groups {
		out = append(out, Lab{LocationID: k, SampleTypeIDs: v})
	}
	sort.Slice(out, func(i, j int) bool { return out[i].LocationID < out[j].LocationID })
	return out, nil
}

// BumpNetwork marks the network dirty so the next recompute uses a fresh revision.
func (e *Engine) BumpNetwork(ctx context.Context) error {
	_, err := e.pg.Exec(ctx, `UPDATE network_state SET revision = revision + 1 WHERE id = 1`)
	if err != nil {
		return err
	}
	return nil
}

// HasCollectionCoverage returns true if (lat,lng) is within coverage of any active collection point.
func (s *Snapshot) HasCollectionCoverage(lat, lng float64) (*Region, bool) {
	for _, r := range s.Regions {
		d := util.HaversineKm(lat, lng, r.Latitude, r.Longitude)
		if d <= r.CoverageKm {
			return &r, true
		}
	}
	return nil, false
}

// HasAcceptingLab returns a laboratory that accepts the given sample type.
func (s *Snapshot) HasAcceptingLab(sampleTypeID string) (*Lab, bool) {
	for _, lab := range s.Laboratories {
		for _, st := range lab.SampleTypeIDs {
			if st == sampleTypeID {
				return &lab, true
			}
		}
	}
	return nil, false
}

// CanReachLab returns true if fromLocation can reach lab via active edges.
func (s *Snapshot) CanReachLab(fromLocation, labLocation string) bool {
	visited := map[string]bool{}
	queue := []string{fromLocation}
	for len(queue) > 0 {
		cur := queue[0]
		queue = queue[1:]
		if visited[cur] {
			continue
		}
		visited[cur] = true
		if cur == labLocation {
			return true
		}
		for _, e := range s.Edges {
			if e.From == cur {
				queue = append(queue, e.To)
			}
		}
	}
	return false
}

// MarshalJSONForVersion returns JSON bytes for persistence.
func MarshalSnapshot(s *Snapshot) ([]byte, error) {
	return jsonMarshal(s)
}

// helper wrappers to avoid extra import collision
func jsonUnmarshal(b []byte, v interface{}) error {
	return jsonImpl.Unmarshal(b, v)
}

// Reason describes why serviceability failed.
type Reason struct {
	Code    string
	Message string
}

// String returns the formatted reason.
func (r Reason) String() string { return fmt.Sprintf("%s: %s", r.Code, r.Message) }

// uuid.New is wrapped for testing.
var _ = uuid.New"}

