// Sample is the canonical sample record.
type Sample struct {
	ID                        string
	RequestID                 string
	RequesterID               string
	Status                    string
	CurrentHolderID           string
	OriginLat                 float64
	OriginLng                 float64
	OriginType                string
	OriginNodeID              string
	RequestedAt               time.Time
	DeliveryDeadline          time.Time
	EarliestCollectionAt      time.Time
	LatestCollectionAt        time.Time
	SampleTypeID              string
	ContainerType             string
	TempMinC                  float64
	TempMaxC                  float64
	IncompatibleSampleTypeIDs []string
	TargetLaboratoryID        string
	ActiveJourneyID           string
	Sealed                    bool
	Exception                 map[string]interface{}
	LatestLat                 *float64
	LatestLng                 *float64
	LocationRecordedAt        *time.Time
	ReceivedLaboratoryID      string
	ReceivedAt                *time.Time
}

func LoadSampleByID(ctx context.Context, pg *pgxpool.Pool, id string) (*Sample, error) {
	row := pg.QueryRow(ctx, `
        SELECT id::text, request_id::text, requester_id::text, status, COALESCE(current_holder_id::text,''),
            origin_latitude, origin_longitude, origin_type, COALESCE(origin_node_id::text,''),
            requested_at, delivery_deadline, earliest_collection_at, latest_collection_at,
            sample_type_id::text, container_type, temperature_min_c, temperature_max_c,
            incompatible_sample_type_ids, COALESCE(target_laboratory_id::text,''),
            COALESCE(active_journey_id::text,''), sealed, exception,
            latest_lat, latest_lng, location_recorded_at,
            COALESCE(received_laboratory_id::text,''), received_at
        FROM samples WHERE id = $1
    `, id)
	return scanSample(row)
}

func scanSample(row pgx.Row) (*Sample, error) {
	s := &Sample{}
	var ex []byte
	if err := row.Scan(&s.ID, &s.RequestID, &s.RequesterID, &s.Status, &s.CurrentHolderID,
		&s.OriginLat, &s.OriginLng, &s.OriginType, &s.OriginNodeID,
		&s.RequestedAt, &s.DeliveryDeadline, &s.EarliestCollectionAt, &s.LatestCollectionAt,
		&s.SampleTypeID, &s.ContainerType, &s.TempMinC, &s.TempMaxC,
		&s.IncompatibleSampleTypeIDs, &s.TargetLaboratoryID,
