// ComputeTravelMinutes estimates travel time from start location to end location
// based on direct haversine + a fixed factor for realistic speeds.
func ComputeTravelMinutes(fromLat, fromLng, toLat, toLng float64) int {
	d := util.HaversineKm(fromLat, fromLng, toLat, toLng)
	// 30 km/h average in dense urban area
	mins := int(math.Round((d / 30.0) * 60.0))
	if mins < 1 {
		mins = 1
	}
	return mins
}

// ComputeRoute returns a sequence of (fromLocation, toLocation, transportMinutes)
// legs that connect the origin location to the target laboratory, or an error.
// The simple greedy BFS picks the shortest path from originNode to lab.
func ComputeRoute(snap *serviceability.Snapshot, origin string, lab string) ([]RouteLeg, error) {
	if origin == "" || lab == "" {
		return nil, errors.New("missing origin or lab")
	}
	// BFS
	parents := map[string]string{}
	visited := map[string]bool{origin: true}
	queue := []string{origin}
	for len(queue) > 0 {
		cur := queue[0]
		queue = queue[1:]
		if cur == lab {
			break
		}
		for _, e := range snap.Edges {
			if e.From == cur && !visited[e.To] {
				visited[e.To] = true
				parents[e.To] = cur
				queue = append(queue, e.To)
			}
		}
	}
	if !visited[lab] {
		return nil, errors.New("no route")
	}
	// rebuild
	path := []string{lab}
	for cur := lab; cur != origin; cur = parents[cur] {
		path = append(path, parents[cur])
	}
	for i, j := 0, len(path)-1; i < j; i, j = i+1, j-1 {
		path[i], path[j] = path[j], path[i]
	}
	return pathToLegs(path), nil
}

// RouteLeg is a single transport segment in the planned route.
type RouteLeg struct {
	From string
	To   string
}

func pathToLegs(path []string) []RouteLeg {
	out := make([]RouteLeg, 0, len(path)-1)
	for i := 0; i+1 < len(path); i++ {
		out = append(out, RouteLeg{From: path[i], To: path[i+1]})
	}
	return out
}

// CapacityResult is returned by capacity operations.
type CapacityResult struct {
	CapacityUnits         int `json:"capacityUnits"`
	ReservedUnits         int `json:"reservedUnits"`
	AvailableUnits        int `json:"availableUnits"`
	CooledCapacityUnits   int `json:"cooledCapacityUnits"`
	CooledReservedUnits   int `json:"cooledReservedUnits"`
	CooledAvailableUnits  int `json:"cooledAvailableUnits"`
}

// LoadCapacity returns capacity for a resource (location or connection).
func LoadCapacity(ctx context.Context, pg *pgxpool.Pool, kind, id string) (*CapacityResult, error) {
	row := pg.QueryRow(ctx, `
        SELECT capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units
        FROM capacity_pools WHERE resource_kind = $1 AND resource_id = $2
    `, kind, id)
	r := &CapacityResult{}
	var cool int
	if err := row.Scan(&r.CapacityUnits, &r.ReservedUnits, &r.CooledCapacityUnits, &cool); err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return &CapacityResult{}, nil
		}
		return nil, err
	}
	r.CooledReservedUnits = cool
	r.AvailableUnits = r.CapacityUnits - r.ReservedUnits
	r.CooledAvailableUnits = r.CooledCapacityUnits - r.CooledReservedUnits
	return r, nil
}

// ReserveCapacity increases reserved units on a pool.
func ReserveCapacity(ctx context.Context, pg *pgxpool.Pool, kind, id string, regular, cooled int) error {
	tx, err := pg.Begin(ctx)
	if err != nil {
		return err
	}
	defer tx.Rollback(ctx)
	var capReg, resReg, capCool, resCool int
	row := tx.QueryRow(ctx, `
        SELECT capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units
        FROM capacity_pools WHERE resource_kind = $1 AND resource_id = $2 FOR UPDATE
    `, kind, id)
	err = row.Scan(&capReg, &resReg, &capCool, &resCool)
	if errors.Is(err, pgx.ErrNoRows) {
		_, err = tx.Exec(ctx, `
            INSERT INTO capacity_pools (resource_kind, resource_id, capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units)
            VALUES ($1, $2, 0, 0, 0, 0)
        `, kind, id)
		if err != nil {
			return err
		}
		capReg, resReg, capCool, resCool = 0, 0, 0, 0
	} else if err != nil {
		return err
	}
	if regular < 0 {
		if -regular > resReg {
			return errors.New("regular over-release")
		}
		resReg += regular
	} else {
		if capReg-resReg < regular {
			return fmt.Errorf("regular overbook: avail=%d, requested=%d", capReg-resReg, regular)
		}
		resReg += regular
	}
	if cooled < 0 {
		if -cooled > resCool {
			return errors.New("cooled over-release")
		}
		resCool += cooled
	} else {
		if capCool-resCool < cooled {
			return fmt.Errorf("cooled overbook: avail=%d, requested=%d", capCool-resCool, cooled)
		}
		resCool += cooled
	}
	if _, err := tx.Exec(ctx, `
        UPDATE capacity_pools SET reserved_units = $3, cooled_reserved_units = $4
        WHERE resource_kind = $1 AND resource_id = $2
    `, kind, id, resReg, resCool); err != nil {
		return err
	}
	return tx.Commit(ctx)
}

// ReleaseCapacity reduces reserved units on a pool (negative delta).
func ReleaseCapacity(ctx context.Context, pg *pgxpool.Pool, kind, id string, regular, cooled int) error {
	return ReserveCapacity(ctx, pg, kind, id, -regular, -cooled)
}

// AuditAction records a row in the audit log.
func AuditAction(ctx context.Context, pg *pgxpool.Pool, actor *auth.Principal, action, entityType, entityID string, success bool, details map[string]interface{}) {
	if details == nil {
		details = map[string]interface{}{}
	}
	var actorID *string
	var role *string
	if actor != nil {
		actorID = &actor.User.ID
		role = &actor.ActiveRole
	}
	_, _ = pg.Exec(ctx, `
        INSERT INTO audit_log (actor_id, role, action, entity_type, entity_id, success, details)
        VALUES ($1,$2,$3,$4,$5,$6,$7)
    `, actorID, role, action, entityType, entityID, success, details)
}

// AuditEntries returns audit entries filtered by search criteria.
type AuditFilter struct {
	EntityType string
	EntityID   string
	Action     string
	ActorID    string
	Role       string
	Success    *bool
	Query      string
	Order      string // "newest_first" | "oldest_first"
	Limit      int
	Offset     int
}

func SearchAudit(ctx context.Context, pg *pgxpool.Pool, f AuditFilter) (entries []map[string]interface{}, total int, err error) {
	where := []string{"TRUE"}
	args := []interface{}{}
	idx := 1
	if f.EntityType != "" {
		where = append(where, fmt.Sprintf("entity_type = $%d", idx))
		args = append(args, f.EntityType)
		idx++
	}
	if f.EntityID != "" {
		where = append(where, fmt.Sprintf("entity_id = $%d", idx))
		args = append(args, f.EntityID)
		idx++
	}
	if f.Action != "" {
		where = append(where, fmt.Sprintf("action = $%d", idx))
		args = append(args, f.Action)
		idx++
	}
	if f.ActorID != "" {
		where = append(where, fmt.Sprintf("actor_id::text = $%d", idx))
		args = append(args, f.ActorID)
		idx++
	}
	if f.Role != "" {
		where = append(where, fmt.Sprintf("role = $%d", idx))
		args = append(args, f.Role)
		idx++
	}
	if f.Success != nil {
		where = append(where, fmt.Sprintf("success = $%d", idx))
		args = append(args, *f.Success)
		idx++
	}
	if f.Query != "" {
		where = append(where, fmt.Sprintf("(action ILIKE $%d OR entity_id ILIKE $%d OR details::text ILIKE $%d)", idx, idx, idx))
		args = append(args, "%"+f.Query+"%")
		idx++
	}
	if f.Limit <= 0 {
		f.Limit = 50
	}
	order := "occurred_at DESC, id DESC"
	if f.Order == "oldest_first" {
		order = "occurred_at ASC, id ASC"
	}
	rows, err := pg.Query(ctx, fmt.Sprintf(`
        SELECT id, COALESCE(actor_id::text,''), COALESCE(role,''), action, entity_type, COALESCE(entity_id,''), success, occurred_at, details
        FROM audit_log WHERE %s ORDER BY %s OFFSET %d LIMIT %d
    `, strings.Join(where, " AND "), order, f.Offset, f.Limit), args...)
	if err != nil {
		return nil, 0, err
	}
	defer rows.Close()
	for rows.Next() {
		var id int64
		var actorID, role, eid string
		var action, etype string
		var success bool
		var occurredAt time.Time
		var details []byte
		if err := rows.Scan(&id, &actorID, &role, &action, &etype, &eid, &success, &occurredAt, &details); err != nil {
			return nil, 0, err
		}
		d := map[string]interface{}{}
		_ = json.Unmarshal(details, &d)
		entries = append(entries, map[string]interface{}{
			"auditId":    fmt.Sprintf("audit-%d", id),
			"actorId":    actorID,
			"role":       role,
			"actorRole":  role,
			"action":     action,
			"entityType": etype,
			"entityId":   eid,
			"success":    success,
			"occurredAt": occurredAt.UTC().Format(time.RFC3339),
			"details":    d,
		})
	}
	if err := pg.QueryRow(ctx, fmt.Sprintf(`SELECT COUNT(*) FROM audit_log WHERE %s`, strings.Join(where, " AND ")), args...).Scan(&total); err != nil {
		return nil, 0, err
	}
	return entries, total, nil
}

