// FindSampleOriginLocation returns the location id that should serve as the journey origin.
// For home/clinic origins, this is the nearest active collection point within coverage.
func FindSampleOriginLocation(ctx context.Context, pg *pgxpool.Pool, sample *Sample) (string, *Location, error) {
	if sample.OriginType == "node" && sample.OriginNodeID != "" {
		l, err := LoadLocationByID(ctx, pg, sample.OriginNodeID)
		return sample.OriginNodeID, l, err
	}
	// nearest active collection point
	locs, err := LoadAllLocations(ctx, pg)
	if err != nil {
		return "", nil, err
	}
	best := (*Location)(nil)
	bestD := math.MaxFloat64
	for _, l := range locs {
		if !l.Active || !l.Functions["collection_point"] {
			continue
		}
		d := util.HaversineKm(sample.OriginLat, sample.OriginLng, l.Latitude, l.Longitude)
		if d <= l.CoverageKm && d < bestD {
			best = l
			bestD = d
		}
	}
	if best == nil {
		return "", nil, errors.New("no collection point within coverage")
	}
	return best.ID, best, nil
}

// SequenceNodeIDs returns the ordered set of node IDs that the journey will touch.
// This includes pickup origin, intermediate transfer points, and destination laboratory.
func SequenceNodeIDs(route []RouteLeg, origin string, lab string) []string {
	out := []string{origin}
	for _, l := range route {
		out = append(out, l.To)
	}
	if len(out) == 0 || out[len(out)-1] != lab {
		out = append(out, lab)
	}
	return out
}

// UUID returns a new random UUID string.
func UUID() string { return uuid.NewString() }

// Now is a wrapper around time.Now used by tests.
func Now() time.Time { return time.Now().UTC() }

// MinTime returns the earlier of t1 and t2.
func MinTime(a, b time.Time) time.Time {
	if a.Before(b) {
		return a
	}
	return b
}

// MaxTime returns the later of t1 and t2.
func MaxTime(a, b time.Time) time.Time {
	if a.After(b) {
		return a
	}
	return b
}

// DistinctStrings returns deduped values.
func DistinctStrings(in []string) []string {
	seen := map[string]bool{}
	out := []string{}
	for _, v := range in {
		if seen[v] {
			continue
		}
		seen[v] = true
		out = append(out, v)
	}
	sort.Strings(out)
	return out
}"}

