// PlanAndCreateJourney assigns collection and transport work for a sample, creates
// journey + assignments, reserves capacity, and returns the journey id. The caller
// is expected to commit the wrapping transaction.
func (d *Domain) PlanAndCreateJourney(ctx context.Context, tx pgx.Tx, sample *Sample, originID, labID string) (string, error) {
	snap := d.Svc.Snapshot()
	route, err := ComputeRoute(snap, originID, labID)
	if err != nil {
		return "", fmt.Errorf("no route: %w", err)
	}
	st, err := LoadSampleTypeByID(ctx, d.PG, sample.SampleTypeID)
	if err != nil {
		return "", err
	}
	originLoc, err := LoadLocationByID(ctx, d.PG, originID)
	if err != nil {
		return "", err
	}
	labLoc, err := LoadLocationByID(ctx, d.PG, labID)
	if err != nil {
		return "", err
	}

	// estimate delivery at by summing travel + handling windows
	now := time.Now().UTC()
	earliest := sample.EarliestCollectionAt
	if earliest.Before(now) {
		earliest = now
	}
	cursor := earliest
	cursor = cursor.Add(time.Duration(originLoc.Handling) * time.Minute)
	for i, leg := range route {
		fromLoc, _ := LoadLocationByID(ctx, d.PG, leg.From)
		toLoc, _ := LoadLocationByID(ctx, d.PG, leg.To)
		travel := ComputeTravelMinutes(fromLoc.Latitude, fromLoc.Longitude, toLoc.Latitude, toLoc.Longitude)
		cursor = cursor.Add(time.Duration(travel) * time.Minute)
		// dwell at transfer point
		cursor = cursor.Add(time.Duration(toLoc.Handling) * time.Minute)
		_ = i
	}
	if cursor.After(sample.DeliveryDeadline) {
		return "", errors.New("deadline infeasible for current network")
	}

	// create journey
	journeyID := UUID()
	mode := "direct"
	if len(route) > 1 {
		mode = "multi_stop"
	}
	if _, err := tx.Exec(ctx, `
        INSERT INTO journeys (id, plan_version, route_mode, status, estimated_delivery_at, total_cost_units, active)
        VALUES ($1, 1, $2, 'planned', $3, $4, TRUE)
    `, journeyID, mode, cursor, float64(len(route))); err != nil {
		return "", err
	}
	if _, err := tx.Exec(ctx, `INSERT INTO journey_samples (journey_id, sample_id) VALUES ($1,$2)`, journeyID, sample.ID); err != nil {
		return "", err
	}

	// build ordered stops
	sequence := 0
	// pickup stop at origin
	stopID := UUID()
	if _, err := tx.Exec(ctx, `
        INSERT INTO journey_stops (id, journey_id, location_id, stop_type, sequence, estimated_at, dwell_minutes, latitude, longitude)
        VALUES ($1,$2,$3,'pickup',$4,$5,$6,$7,$8)
    `, stopID, journeyID, originID, sequence, earliest, originLoc.Handling, originLoc.Latitude, originLoc.Longitude); err != nil {
		return "", err
	}
	sequence++
	// transfer/delivery stops
	stopsCursor := earliest.Add(time.Duration(originLoc.Handling) * time.Minute)
	for _, leg := range route {
		fromLoc, _ := LoadLocationByID(ctx, d.PG, leg.From)
		toLoc, _ := LoadLocationByID(ctx, d.PG, leg.To)
		travel := ComputeTravelMinutes(fromLoc.Latitude, fromLoc.Longitude, toLoc.Latitude, toLoc.Longitude)
		stopsCursor = stopsCursor.Add(time.Duration(travel) * time.Minute)
		stopType := "handoff"
		if leg.To == labID {
			stopType = "delivery"
		}
		sid := UUID()
		if _, err := tx.Exec(ctx, `
            INSERT INTO journey_stops (id, journey_id, location_id, stop_type, sequence, estimated_at, dwell_minutes, latitude, longitude)
            VALUES ($1,$2,$3,$4,$5,$6,$7,$8,$9)
        `, sid, journeyID, leg.To, stopType, sequence, stopsCursor, toLoc.Handling, toLoc.Latitude, toLoc.Longitude); err != nil {
			return "", err
		}
		sequence++
		stopsCursor = stopsCursor.Add(time.Duration(toLoc.Handling) * time.Minute)
	}

	// collection assignment (home/clinic origin): from origin lat/lng → originID
	collector, err := FindQualifiedCollector(ctx, d.PG, st)
	if err != nil {
		return "", err
	}
	collectionAssID := UUID()
	if _, err := tx.Exec(ctx, `
        INSERT INTO assignments (id, journey_id, sample_id, worker_id, kind, status, from_location_id, to_location_id, sequence, offered_to, offered_at, offer_expires_at)
        VALUES ($1,$2,$3,NULLIF($4,''),'collection','offered',NULLIF($5,'')::uuid,NULLIF($6,'')::uuid,$7,NULLIF($4,'')::uuid,NOW(),NOW() + INTERVAL '10 minutes')
    `, collectionAssID, journeyID, sample.ID, collector, originID, originID, 0); err != nil {
		return "", err
	}

	// transport assignments: origin → ... → lab
	for i, leg := range route {
		worker, err := FindTransportWorker(ctx, d.PG, leg.From, leg.To, st.RequiresCooledRoute)
		if err != nil {
			return "", err
		}
		assID := UUID()
		if _, err := tx.Exec(ctx, `
            INSERT INTO assignments (id, journey_id, sample_id, worker_id, kind, status, from_location_id, to_location_id, sequence, offered_to, offered_at, offer_expires_at)
            VALUES ($1,$2,$3,NULLIF($4,''),'transport','offered',$5,$6,$7,NULLIF($4,'')::uuid,NOW(),NOW() + INTERVAL '10 minutes')
        `, assID, journeyID, sample.ID, worker, leg.From, leg.To, i+1); err != nil {
			return "", err
		}
	}

	// node/lab intake assignments
	for _, leg := range route {
		if leg.To == labID {
			continue
		}
		toLoc, _ := LoadLocationByID(ctx, d.PG, leg.To)
		if !toLoc.Functions["hub"] && !toLoc.Functions["transfer_point"] {
			continue
		}
		nodeAssID := UUID()
		if _, err := tx.Exec(ctx, `
            INSERT INTO assignments (id, journey_id, sample_id, node_id, kind, status, from_location_id, to_location_id, sequence)
            VALUES ($1,$2,$3,$4,'node','pending',$5,$6,$7)
        `, nodeAssID, journeyID, sample.ID, leg.To, leg.From, leg.To, sequence); err != nil {
			return "", err
		}
		sequence++
	}
	if labLoc.Functions["laboratory"] {
		labAssID := UUID()
		if _, err := tx.Exec(ctx, `
            INSERT INTO assignments (id, journey_id, sample_id, laboratory_id, kind, status, from_location_id, to_location_id, sequence)
            VALUES ($1,$2,$3,$4,'laboratory','pending',$5,$6,$7)
        `, labAssID, journeyID, sample.ID, labID, route[len(route)-1].From, labID, sequence); err != nil {
			return "", err
		}
	}

	// reserve capacity on each leg's destination location
	for _, leg := range route {
		toLoc, _ := LoadLocationByID(ctx, d.PG, leg.To)
		if err := ReserveCapacity(ctx, tx, "location", leg.To, 1, boolToInt(st.RequiresCooledRoute)); err != nil {
			return "", fmt.Errorf("reserve location: %w", err)
		}
		if err := ReserveCapacity(ctx, tx, "connection", connectionID(ctx, tx, leg.From, leg.To), 1, boolToInt(st.RequiresCooledRoute)); err != nil {
			return "", err
		}
		_ = toLoc
	}

	return journeyID, nil
}

func connectionID(ctx context.Context, tx pgx.Tx, from, to string) string {
	var id string
	row := tx.QueryRow(ctx, `SELECT id::text FROM connections WHERE from_location_id = $1 AND to_location_id = $2 LIMIT 1`, from, to)
	if err := row.Scan(&id); err == nil {
		return id
	}
	return ""
}

func boolToInt(b bool) int {
	if b {
		return 1
	}
	return 0
}

// OfferAssignmentTo chooses a worker for an assignment that is currently pending and records the offer.
func (d *Domain) OfferAssignmentTo(ctx context.Context, principal *auth.Principal, assignmentID, workerID string) error {
	a, err := LoadAssignmentByID(ctx, d.PG, assignmentID)
	if err != nil {
		return err
	}
	if a.Status != AssignmentStatusPending && a.Status != AssignmentStatusDeclined && a.Status != AssignmentStatusOffered {
		return fmt.Errorf("assignment cannot be re-offered from %s", a.Status)
	}
	now := time.Now().UTC()
	_, err = d.PG.Exec(ctx, `
        UPDATE assignments SET offered_to = $2, offered_at = $3, offer_expires_at = $4,
            status = 'offered', declined_at = NULL, accepted_at = NULL
        WHERE id = $1
    `, assignmentID, workerID, now, now.Add(10*time.Minute))
	if err != nil {
		return err
	}
	AuditAction(ctx, d.PG, principal, "offer_assignment", "assignment", assignmentID, true, map[string]interface{}{
		"offeredTo": workerID,
	})
	d.Bus.Publish(ctx, "assignment.offered", "assignment", assignmentID, map[string]interface{}{
		"assignmentId": assignmentID,
		"offeredTo":    workerID,
	})
	return nil
}

// AcceptAssignment transitions an offered assignment to accepted for the worker.
func (d *Domain) AcceptAssignment(ctx context.Context, principal *auth.Principal, assignmentID string) error {
	a, err := LoadAssignmentByID(ctx, d.PG, assignmentID)
	if err != nil {
		return err
	}
	if a.OfferedTo == nil || *a.OfferedTo != principal.User.ID {
		return util.Forbidden("wrong_worker", "assignment not offered to you")
	}
	if a.Status != AssignmentStatusOffered {
		return fmt.Errorf("assignment not in offered state")
	}
	now := time.Now().UTC()
	_, err = d.PG.Exec(ctx, `
        UPDATE assignments SET status = 'accepted', accepted_at = $2 WHERE id = $1
    `, assignmentID, now)
	if err != nil {
		return err
	}
	// Update sample holder
	if a.SampleID != "" && a.Kind == AssignmentKindCollection {
		_, _ = d.PG.Exec(ctx, `UPDATE samples SET current_holder_id = $2, status = 'collected' WHERE id = $1`, a.SampleID, principal.User.ID)
	}
	if a.SampleID != "" && (a.Kind == AssignmentKindTransport || a.Kind == AssignmentKindNode) {
		_, _ = d.PG.Exec(ctx, `UPDATE samples SET current_holder_id = $2 WHERE id = $1`, a.SampleID, principal.User.ID)
	}
	AuditAction(ctx, d.PG, principal, "accept_assignment", "assignment", assignmentID, true, nil)
	d.Bus.Publish(ctx, "assignment.accepted", "assignment", assignmentID, map[string]interface{}{
		"workerId":     principal.User.ID,
		"assignmentId": assignmentID,
	})
	return nil
}

// DeclineAssignment marks an offer declined and tries to re-offer.
func (d *Domain) DeclineAssignment(ctx context.Context, principal *auth.Principal, assignmentID string) (string, error) {
	a, err := LoadAssignmentByID(ctx, d.PG, assignmentID)
	if err != nil {
		return "", err
	}
	if a.OfferedTo == nil || *a.OfferedTo != principal.User.ID {
		return "", util.Forbidden("wrong_worker", "assignment not offered to you")
	}
	now := time.Now().UTC()
	_, err = d.PG.Exec(ctx, `
        UPDATE assignments SET status = 'declined', declined_at = $2, decline_count = decline_count + 1, offered_to = NULL
        WHERE id = $1
    `, assignmentID, now)
	if err != nil {
		return "", err
	}
	AuditAction(ctx, d.PG, principal, "decline_assignment", "assignment", assignmentID, true, nil)
	d.Bus.Publish(ctx, "assignment.declined", "assignment", assignmentID, map[string]interface{}{
		"workerId": principal.User.ID,
	})

	// try to re-offer
	next, err := d.reOffer(ctx, a)
	if err != nil {
		return "", err
	}
	return next, nil
}

func (d *Domain) reOffer(ctx context.Context, a *Assignment) (string, error) {
	var candidate string
	switch a.Kind {
	case AssignmentKindCollection:
		st, err := LoadSampleTypeByID(ctx, d.PG, lookupSampleType(ctx, d.PG, a.SampleID))
		if err != nil {
			return "", err
		}
		candidate, err = FindQualifiedCollector(ctx, d.PG, st)
		if err != nil {
			return "", err
		}
	case AssignmentKindTransport:
		candidate, err = FindTransportWorker(ctx, d.PG, a.FromLocationID, a.ToLocationID, false)
		if err != nil {
			return "", err
		}
	}
	if candidate == "" {
		// mark sample exception
		_, _ = d.PG.Exec(ctx, `UPDATE samples SET status = 'exception', exception = jsonb_set(COALESCE(exception,'{}'::jsonb),'{reason}', '"no_worker_available"') WHERE id = $1`, a.SampleID)
		AuditAction(ctx, d.PG, nil, "no_worker_available", "sample", a.SampleID, false, map[string]interface{}{"assignmentId": a.ID})
		return "", nil
	}
	now := time.Now().UTC()
	if _, err := d.PG.Exec(ctx, `
        UPDATE assignments SET offered_to = $2, offered_at = $3, offer_expires_at = $4, status = 'offered'
        WHERE id = $1
    `, a.ID, candidate, now, now.Add(10*time.Minute)); err != nil {
		return "", err
	}
	return candidate, nil
}

func lookupSampleType(ctx context.Context, pg interface {
	QueryRow(context.Context, string, ...interface{}) pgx.Row
}, sampleID string) string {
	row := pg.QueryRow(ctx, `SELECT sample_type_id::text FROM samples WHERE id = $1`, sampleID)
	var out string
	_ = row.Scan(&out)
	return out
}

// InitiateHandoff creates a pending handoff record that needs both sides to confirm.
func (d *Domain) InitiateHandoff(ctx context.Context, principal *auth.Principal, sampleID, fromAssID, toAssID string) (string, error) {
	tx, err := d.PG.Begin(ctx)
	if err != nil {
		return "", err
	}
	defer tx.Rollback(ctx)
	fromA, err := LoadAssignmentByID(ctx, d.PG, fromAssID)
	if err != nil {
		return "", err
	}
	toA, err := LoadAssignmentByID(ctx, d.PG, toAssID)
	if err != nil {
		return "", err
	}
	if fromA.SampleID != sampleID || toA.SampleID != sampleID {
		return "", errors.New("assignments don't match sample")
	}
	if fromA.WorkerID == nil || principal.User.ID != *fromA.WorkerID {
		return "", util.Forbidden("not_holder", "you are not the current holder")
	}
	handoffID := UUID()
	if _, err := tx.Exec(ctx, `
        INSERT INTO handoffs (id, sample_id, from_assignment_id, to_assignment_id, sender_id, receiver_id, status, initiated_at)
        VALUES ($1,$2,$3,$4,$5,$6,'pending',NOW())
    `, handoffID, sampleID, fromAssID, toAssID, *fromA.WorkerID, emptyUUID(toA.WorkerID)); err != nil {
		return "", err
	}
	if err := tx.Commit(ctx); err != nil {
		return "", err
	}
	AuditAction(ctx, d.PG, principal, "initiate_handoff", "handoff", handoffID, true, map[string]interface{}{"sampleId": sampleID})
	d.Bus.Publish(ctx, "handoff.initiated", "handoff", handoffID, map[string]interface{}{"sampleId": sampleID})
	return handoffID, nil
}

func emptyUUID(s *string) string {
	if s == nil {
		return ""
	}
	return *s
}

// ConfirmHandoff marks the appropriate confirmation flag and transitions the sample holder if both sides confirmed.
func (d *Domain) ConfirmHandoff(ctx context.Context, principal *auth.Principal, handoffID, side string) (string, error) {
	row := d.PG.QueryRow(ctx, `
        SELECT id::text, sample_id::text, sender_id::text, COALESCE(receiver_id::text,''), sender_confirmed, receiver_confirmed, status
        FROM handoffs WHERE id = $1
    `, handoffID)
	var sampleID, senderID, receiverID, status string
	var senderC, receiverC bool
	if err := row.Scan(&handoffID, &sampleID, &senderID, &receiverID, &senderC, &receiverC, &status); err != nil {
		return "", util.NotFound("handoff", "handoff not found")
	}
	if status == "completed" {
		return "completed", nil
	}
	now := time.Now().UTC()
	if side == "sender" {
		if principal.User.ID != senderID {
			return "", util.Forbidden("not_sender", "you are not the sender")
		}
		senderC = true
		if _, err := d.PG.Exec(ctx, `UPDATE handoffs SET sender_confirmed = TRUE, sender_confirmed_at = $2 WHERE id = $1`, handoffID, now); err != nil {
			return "", err
		}
	} else if side == "receiver" {
		if principal.User.ID != receiverID {
			return "", util.Forbidden("not_receiver", "you are not the receiver")
		}
		receiverC = true
		if _, err := d.PG.Exec(ctx, `UPDATE handoffs SET receiver_confirmed = TRUE, receiver_confirmed_at = $2 WHERE id = $1`, handoffID, now); err != nil {
			return "", err
		}
	} else {
		return "", errors.New("invalid side")
	}
	if senderC && receiverC {
		if _, err := d.PG.Exec(ctx, `UPDATE handoffs SET status = 'completed', completed_at = NOW() WHERE id = $1`, handoffID); err != nil {
			return "", err
		}
		// transfer custody
		if _, err := d.PG.Exec(ctx, `UPDATE samples SET current_holder_id = NULLIF($2,'')::uuid WHERE id = $1`, sampleID, receiverID); err != nil {
			return "", err
		}
		AuditAction(ctx, d.PG, principal, "handoff_completed", "handoff", handoffID, true, map[string]interface{}{"sampleId": sampleID})
		d.Bus.Publish(ctx, "handoff.completed", "handoff", handoffID, map[string]interface{}{"sampleId": sampleID, "newHolderId": receiverID})
		return "completed", nil
	}
	AuditAction(ctx, d.PG, principal, "handoff_confirm", "handoff", handoffID, true, map[string]interface{}{"side": side})
	return "pending", nil
}

// CollectAndSealSample marks a sample as collected by a certified collector.
func (d *Domain) CollectAndSealSample(ctx context.Context, principal *auth.Principal, sampleID string) error {
	s, err := LoadSampleByID(ctx, d.PG, sampleID)
	if err != nil {
		return err
	}
	now := time.Now().UTC()
	if now.Before(s.EarliestCollectionAt) || now.After(s.LatestCollectionAt) {
		return errors.New("outside collection window")
	}
	if _, err := d.PG.Exec(ctx, `
        UPDATE samples SET sealed = TRUE, status = 'collected', current_holder_id = $2
        WHERE id = $1
    `, sampleID, principal.User.ID); err != nil {
		return err
	}
	AuditAction(ctx, d.PG, principal, "collect_and_seal", "sample", sampleID, true, nil)
	d.Bus.Publish(ctx, "sample.collected", "sample", sampleID, map[string]interface{}{"collectorId": principal.User.ID})
	return nil
}

// ConfirmLaboratoryReceipt marks a sample received at its target laboratory.
func (d *Domain) ConfirmLaboratoryReceipt(ctx context.Context, principal *auth.Principal, sampleID, laboratoryID string) error {
	now := time.Now().UTC()
	if _, err := d.PG.Exec(ctx, `
        UPDATE samples SET status = 'received', received_laboratory_id = $2, received_at = $3, current_holder_id = NULL
        WHERE id = $1
