	}
	AuditAction(ctx, d.PG, principal, "confirm_receipt", "sample", sampleID, true, map[string]interface{}{"laboratoryId": laboratoryID})
	d.Bus.Publish(ctx, "sample.received", "sample", sampleID, map[string]interface{}{"laboratoryId": laboratoryID})
	return nil
}

