// RecordHandlingCheckpoint stores an observation and flags the sample if out-of-range.
func (d *Domain) RecordHandlingCheckpoint(ctx context.Context, principal *auth.Principal, sampleID, containerType string, tempC float64, assignmentID, locationID string) (bool, error) {
	s, err := LoadSampleByID(ctx, d.PG, sampleID)
	if err != nil {
		return false, err
	}
	compliant := tempC >= s.TempMinC && tempC <= s.TempMaxC
	cpID := UUID()
	if _, err := d.PG.Exec(ctx, `
        INSERT INTO handling_checkpoints (id, sample_id, assignment_id, location_id, container_type, observed_temperature_c, recorded_at, compliant, actor_id, role)
        VALUES ($1,$2,$3,NULLIF($4,'')::uuid,$5,$6,NOW(),$7,$8,$9)
    `, cpID, sampleID, assignmentID, locationID, containerType, tempC, compliant, principal.User.ID, principal.ActiveRole); err != nil {
		return false, err
	}
	if !compliant {
		ex := map[string]interface{}{
			"reason":         "handling_out_of_range",
			"observedTempC":  tempC,
			"requiredMinC":   s.TempMinC,
			"requiredMaxC":   s.TempMaxC,
			"observedContainer": containerType,
			"requiredContainer": s.ContainerType,
		}
		b, _ := jsonMarshal(ex)
		if _, err := d.PG.Exec(ctx, `UPDATE samples SET status = 'exception', exception = $2 WHERE id = $1`, sampleID, b); err != nil {
			return false, err
		}
	}
	AuditAction(ctx, d.PG, principal, "handling_checkpoint", "sample", sampleID, true, map[string]interface{}{
		"compliant": compliant,
		"temperature": tempC,
		"containerType": containerType,
	})
	d.Bus.Publish(ctx, "sample.handling_checkpoint", "sample", sampleID, map[string]interface{}{
		"compliant": compliant,
	})
	return compliant, nil
}

