// ok writes {data: ...} envelope with given status code.
func ok(w http.ResponseWriter, status int, data interface{}) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(map[string]interface{}{"data": data})
}

// parseInt parses an int query parameter with default value.
func parseInt(q string, def int) int {
	if q == "" {
		return def
	}
	v, err := strconv.Atoi(q)
	if err != nil {
		return def
	}
	return v
}

// parseInt64 parses an int64 query parameter.
func parseInt64(q string, def int64) int64 {
	if q == "" {
		return def
	}
	v, err := strconv.ParseInt(q, 10, 64)
	if err != nil {
		return def
	}
	return v
}

// ptrString returns a string pointer.
func ptrString(s string) *string { return &s }

// writeErr writes the standard error envelope.
func writeErr(w http.ResponseWriter, status int, code, msg string) {
	util.WriteError(w, status, code, msg)
}"}

