	"time"

	"github.com/lablogistics/backend/internal/auth"
	"github.com/lablogistics/backend/internal/db"
	"github.com/lablogistics/backend/internal/domain"
	"github.com/lablogistics/backend/internal/util"
)

type AuthHandler struct {
	D  *domain.Domain
	S  *db.Store
	Au *auth.Authenticator
}

func NewAuthHandler(d *domain.Domain, s *db.Store, au *auth.Authenticator) *AuthHandler {
	return &AuthHandler{D: d, S: s, Au: au}
}

// AuthenticateUser handles POST /api/authenticate-user.
func (h *AuthHandler) AuthenticateUser(w http.ResponseWriter, r *http.Request) {
	var body struct {
		Username string `json:"username"`
		Password string `json:"password"`
	}
	if !util.ParseJSON(r, &body) {
		return
	}
	if body.Username == "" || body.Password == "" {
		writeErr(w, http.StatusBadRequest, "missing_credentials", "username and password required")
		return
	}
	u, err := h.Au.GetUserByUsername(r.Context(), body.Username)
	if err != nil || !auth.CheckPassword(u.PasswordHash, body.Password) {
		writeErr(w, http.StatusUnauthorized, "invalid_credentials", "invalid credentials")
		domain.AuditAction(r.Context(), h.D.PG, nil, "sign_in", "user", body.Username, false, map[string]interface{}{"reason": "invalid_credentials"})
		return
	}
	if !u.Active {
		writeErr(w, http.StatusForbidden, "inactive_user", "user inactive")
		return
	}
	role := "requester"
	if len(u.Roles) > 0 {
		role = u.Roles[0]
	}
	sess, err := h.Au.IssueSession(r.Context(), u.ID, role, 7*24*time.Hour)
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "session_error", err.Error())
		return
	}
	domain.AuditAction(r.Context(), h.D.PG, &auth.Principal{User: u, ActiveRole: role}, "sign_in", "user", u.ID, true, map[string]interface{}{"sessionToken": sess.Token})
	ok(w, http.StatusOK, map[string]interface{}{
		"token":         sess.Token,
		"userId":        u.ID,
		"username":      u.Username,
		"fullName":      u.FullName,
		"email":         u.Email,
		"roles":         u.Roles,
		"qualifications": u.Qualifications,
		"activeRole":    role,
		"expiresAt":     sess.ExpiresAt.UTC().Format(time.RFC3339),
		"roleSelectionRequired": len(u.Roles) > 1,
	})
}

// SignOut deletes the caller's session.
func (h *AuthHandler) SignOut(w http.ResponseWriter, r *http.Request) {
	p := auth.PrincipalOf(r)
	if p != nil && p.Session != nil {
		_ = h.Au.DeleteSession(r.Context(), p.Session.Token)
	}
	w.WriteHeader(http.StatusNoContent)
}

// EnsureAdminFromEnv creates the first administrator if no users exist.
func (h *AuthHandler) EnsureAdminFromEnv() error {
	n, err := h.Au.CountAdmins(h.D.Store.PG != nil && h.D.PG != nil, h.D.PG)
	_ = n
	_ = err
	ctx := rBackground()
	users, err := h.Au.ListUsers(ctx)
	if err != nil {
		return err
	}
	if len(users) > 0 {
		return nil
	}
	user := os.Getenv("ADMIN_USERNAME")
	pw := os.Getenv("ADMIN_PASSWORD")
	if user == "" {
		user = "admin"
		pw = "admin"
	}
	u := &auth.User{
		Username:       user,
		Email:          "admin@example.com",
		FullName:       "Initial Administrator",
		Roles:          []string{"administrator", "dispatcher"},
		Qualifications: []string{"Amber", "Indigo", "Frost", "Pulse"},
		Active:         true,
	}
	if err := h.Au.CreateUser(ctx, u, pw); err != nil {
		return err
	}
	return nil
}

// dependency stubs to satisfy reference
var _ = rBackground

// use dummy to avoid unused imports
func rBackground() (ctx context.Context) { return context.Background() }"}

