// ReadServiceabilitySnapshot returns the currently published snapshot (one complete version).
func (h *CoreHandler) ReadServiceabilitySnapshot(w http.ResponseWriter, r *http.Request) {
	if !util.ReadJSON(r, &map[string]interface{}{}) {
		return
	}
	_ = h.D.EnsureServiceability(r.Context())
	snap := h.D.Svc.Snapshot()
	if snap == nil {
		snap = &serviceability.Snapshot{Status: "building"}
	}
	ok(w, http.StatusOK, snap)
}

// CheckServiceability is the dry-run serviceability check for a single sample origin.
func (h *CoreHandler) CheckServiceability(w http.ResponseWriter, r *http.Request) {
	var body struct {
		Origin                *util.Coordinate `json:"origin"`
		OriginType            string           `json:"originType"`
		OriginNodeID          string           `json:"originNodeId"`
		SampleTypeID          string           `json:"sampleTypeId"`
		RequestedAt           time.Time        `json:"requestedAt"`
		DeliveryDeadline      time.Time        `json:"deliveryDeadline"`
		EarliestCollectionAt  time.Time        `json:"earliestCollectionAt"`
		LatestCollectionAt    time.Time        `json:"latestCollectionAt"`
	}
	if !util.ReadJSON(r, &body) {
		return
	}
	if body.Origin == nil {
		writeErr(w, http.StatusBadRequest, "missing_origin", "origin required")
		return
	}
	if err := h.D.EnsureServiceability(r.Context()); err != nil {
		writeErr(w, http.StatusInternalServerError, "serviceability_error", err.Error())
		return
	}
	snap := h.D.Svc.Snapshot()
	if snap == nil {
		writeErr(w, http.StatusServiceUnavailable, "no_snapshot", "snapshot not yet available")
		return
	}
	st, err := domain.LoadSampleTypeByID(r.Context(), h.D.PG, body.SampleTypeID)
	if err != nil {
		writeErr(w, http.StatusBadRequest, "invalid_sample_type", "unknown sample type")
		return
	}
	out := util.ServiceabilityResult{
		Serviceable:    true,
		SnapshotVersion: snap.Version,
		Reasons:        []string{},
	}

	// Pick origin node
	var originNodeID string
	var originNode *domain.Location
	if body.OriginType == "node" && body.OriginNodeID != "" {
		l, err := domain.LoadLocationByID(r.Context(), h.D.PG, body.OriginNodeID)
		if err != nil || !l.Active {
			out.Serviceable = false
			out.Reasons = append(out.Reasons, "invalid_origin_node")
		} else {
			originNode = l
			originNodeID = body.OriginNodeID
		}
	} else {
		region, ok := snap.HasCollectionCoverage(body.Origin.Latitude, body.Origin.Longitude)
		if !ok {
			out.Serviceable = false
			out.Reasons = append(out.Reasons, "outside_collection_coverage")
		} else {
			originNodeID = region.LocationID
			originNode, _ = domain.LoadLocationByID(r.Context(), h.D.PG, originNodeID)
		}
	}

	lab, ok := snap.HasAcceptingLab(body.SampleTypeID)
	if !ok {
		out.Serviceable = false
		out.Reasons = append(out.Reasons, "no_accepting_laboratory")
	}
	if lab != nil && originNodeID != "" && !snap.CanReachLab(originNodeID, lab.LocationID) {
		out.Serviceable = false
		out.Reasons = append(out.Reasons, "no_route")
	}

	// capacity check: query capacity_pools at destination nodes
	legs := []domain.RouteLeg{}
	if originNodeID != "" && lab != nil {
		legs, _ = serviceability.ComputeRoute(snap, originNodeID, lab.LocationID)
	}
	for _, leg := range legs {
		var regCap, regRes, coolCap, coolRes int
		err := h.D.PG.QueryRow(r.Context(), `
            SELECT capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units
            FROM capacity_pools WHERE resource_kind = 'location' AND resource_id = $1
        `, leg.To).Scan(&regCap, &regRes, &coolCap, &coolRes)
		if err == nil {
			if regCap-regRes < 1 {
				out.Serviceable = false
				out.Reasons = append(out.Reasons, "capacity_unavailable:"+leg.To)
			}
			if st.RequiresCooledRoute && coolCap-coolRes < 1 {
				out.Serviceable = false
				out.Reasons = append(out.Reasons, "cooled_capacity_unavailable:"+leg.To)
			}
		}
	}

	// delivery feasibility
	if originNode != nil && lab != nil && len(legs) > 0 {
		now := time.Now().UTC()
		earliest := body.EarliestCollectionAt
		if earliest.Before(now) {
			earliest = now
		}
		cursor := earliest.Add(time.Duration(originNode.Handling) * time.Minute)
		for _, leg := range legs {
			fromL, _ := domain.LoadLocationByID(r.Context(), h.D.PG, leg.From)
			toL, _ := domain.LoadLocationByID(r.Context(), h.D.PG, leg.To)
			cursor = cursor.Add(time.Duration(domain.ComputeTravelMinutes(fromL.Latitude, fromL.Longitude, toL.Latitude, toL.Longitude)) * time.Minute)
			cursor = cursor.Add(time.Duration(toL.Handling) * time.Minute)
		}
		if cursor.After(body.DeliveryDeadline) {
			out.Serviceable = false
			out.Reasons = append(out.Reasons, "deadline_infeasible")
		}
	}
	if out.Serviceable && lab != nil {
		out.TargetLaboratoryID = lab.LocationID
	}
	if !out.Serviceable && out.TargetLaboratoryID == "" && len(out.Reasons) == 0 {
		out.Reasons = append(out.Reasons, "unconfigured")
	}
	ok(w, http.StatusOK, out)
}

// ReadSampleState returns the live sample view.
func (h *CoreHandler) ReadSampleState(w http.ResponseWriter, r *http.Request) {
	p := auth.PrincipalOf(r)
	sampleID := r.PathValue("sampleId")
	s, err := domain.LoadSampleByID(r.Context(), h.D.PG, sampleID)
	if err != nil {
		writeErr(w, http.StatusNotFound, "not_found", "sample not found")
		return
	}
	if !h.canSeeSample(p, s) {
		writeErr(w, http.StatusForbidden, "forbidden", "you do not have access to this sample")
		return
	}
	util.WriteJSON(w, http.StatusOK, map[string]interface{}{
		"sample":           util.SampleToState(s),
		"currentCustodian": h.lookupUserMini(s.CurrentHolderID),
		"targetLaboratory": h.lookupLocationMini(s.TargetLaboratoryID),
	})
}

func (h *CoreHandler) canSeeSample(p *auth.Principal, s *domain.Sample) bool {
	if p == nil {
		return false
	}
	switch p.ActiveRole {
	case "administrator", "dispatcher":
		return true
	case "requester":
		return s.RequesterID == p.User.ID
	case "collection_professional", "delivery_partner", "node_handler", "laboratory_operator":
		// current or recent holder (anyone on its journey can see)
		var cnt int
		_ = h.D.PG.QueryRow(h.requestCtx(), `
            SELECT COUNT(*) FROM assignments a
            JOIN journey_samples js ON js.journey_id = a.journey_id
            WHERE js.sample_id = $1 AND a.worker_id = $2
        `, s.ID, p.User.ID).Scan(&cnt)
		return cnt > 0 || s.CurrentHolderID == p.User.ID
	}
	return false
}

func (h *CoreHandler) requestCtx() context.Context { return context.Background() }

// ReadSampleLifecycle returns ordered history for a sample.
func (h *CoreHandler) ReadSampleLifecycle(w http.ResponseWriter, r *http.Request) {
	p := auth.PrincipalOf(r)
	var body struct {
		SampleID string `json:"sampleId"`
	}
	if !util.ReadJSON(r, &body) {
		return
	}
	s, err := domain.LoadSampleByID(r.Context(), h.D.PG, body.SampleID)
	if err != nil {
		writeErr(w, http.StatusNotFound, "not_found", "sample not found")
		return
	}
	if !h.canSeeSample(p, s) {
		writeErr(w, http.StatusForbidden, "forbidden", "you do not have access to this sample")
		return
	}
	out := h.lifecycleFor(s, p)
	ok(w, http.StatusOK, out)
}

func (h *CoreHandler) lifecycleFor(s *domain.Sample, p *auth.Principal) map[string]interface{} {
	rows, _ := h.D.PG.Query(h.requestCtx(), `
        SELECT id, COALESCE(actor_id::text,''), COALESCE(role,''), action, occurred_at, success, details
        FROM audit_log WHERE entity_id = $1 AND entity_type IN ('sample','handoff','journey','assignment') ORDER BY id ASC
    `, s.ID)
	defer rows.Close()
	type ev struct {
		ID        int64
		Actor     string
		Role      string
		Action    string
		Occurred  time.Time
		Success   bool
		Details   []byte
	}
	var events []ev
	for rows.Next() {
		var e ev
		if err := rows.Scan(&e.ID, &e.Actor, &e.Role, &e.Action, &e.Occurred, &e.Success, &e.Details); err == nil {
			events = append(events, e)
		}
	}
	out := []map[string]interface{}{}
	for _, e := range events {
		var det map[string]interface{}
		_ = json.Unmarshal(e.Details, &det)
		out = append(out, map[string]interface{}{
			"eventId":    e.ID,
			"entityType": "sample",
			"entityId":   s.ID,
			"action":     e.Action,
			"actorId":    e.Actor,
			"role":       e.Role,
			"occurredAt": e.Occurred.UTC().Format(time.RFC3339Nano),
			"success":    e.Success,
			"details":    det,
		})
	}
	// also include status changes derived from samples table
	statusEvents := []map[string]interface{}{}
	statusEvents = append(statusEvents, map[string]interface{}{
		"eventId":   -1,
		"entityType": "sample",
		"entityId":   s.ID,
		"action":     "requested",
		"actorId":    s.RequesterID,
		"role":       "requester",
		"occurredAt": s.RequestedAt.UTC().Format(time.RFC3339Nano),
		"success":    true,
		"details": map[string]interface{}{
			"status": "requested",
		},
	})
	if s.Sealed {
		statusEvents = append(statusEvents, map[string]interface{}{
			"eventId":   -2,
			"entityType": "sample",
			"entityId":   s.ID,
			"action":     "sealed",
			"actorId":    s.CurrentHolderID,
			"role":       "collection_professional",
			"occurredAt": s.RequestedAt.UTC().Add(time.Minute).Format(time.RFC3339Nano),
			"success":    true,
			"details": map[string]interface{}{
				"status": "collected",
			},
		})
	}
	if s.ReceivedAt != nil {
		statusEvents = append(statusEvents, map[string]interface{}{
			"eventId":   -3,
			"entityType": "sample",
			"entityId":   s.ID,
			"action":     "received",
			"actorId":    "",
			"role":       "laboratory_operator",
			"occurredAt": s.ReceivedAt.UTC().Format(time.RFC3339Nano),
			"success":    true,
			"details": map[string]interface{}{
				"status":        "received",
				"laboratoryId":  s.ReceivedLaboratoryID,
			},
		})
	}
	if s.Exception != nil {
		statusEvents = append(statusEvents, map[string]interface{}{
			"eventId":   -4,
			"entityType": "sample",
			"entityId":   s.ID,
			"action":     "exception",
			"actorId":    "",
			"role":       "system",
			"occurredAt": s.RequestedAt.UTC().Add(time.Hour).Format(time.RFC3339Nano),
			"success":    false,
			"details":    s.Exception,
		})
	}
	out = append(statusEvents, out...)
	return map[string]interface{}{
		"sample":      util.SampleToState(s),
		"timeline":    out,
		"destination": h.lookupLocationMini(s.TargetLaboratoryID),
	}
}

// ReadJourneyPlan returns the planned journey with legs and stops.
func (h *CoreHandler) ReadJourneyPlan(w http.ResponseWriter, r *http.Request) {
	var body struct {
		JourneyID string `json:"journeyId"`
	}
	if !util.ReadJSON(r, &body) {
		return
	}
	p := auth.PrincipalOf(r)
	row := h.D.PG.QueryRow(r.Context(), `SELECT plan_version, route_mode, status, estimated_delivery_at, total_cost_units, replan_status FROM journeys WHERE id = $1`, body.JourneyID)
	var plan struct {
		PlanVersion          int
		RouteMode            string
		Status               string
		EstimatedDeliveryAt  *time.Time
		TotalCostUnits       float64
		ReplanStatus         string
	}
	if err := row.Scan(&plan.PlanVersion, &plan.RouteMode, &plan.Status, &plan.EstimatedDeliveryAt, &plan.TotalCostUnits, &plan.ReplanStatus); err != nil {
		writeErr(w, http.StatusNotFound, "not_found", "journey not found")
		return
	}
	// legs
	rows, _ := h.D.PG.Query(r.Context(), `
        SELECT id::text, kind, status, COALESCE(from_location_id::text,''), COALESCE(to_location_id::text,''), sequence, COALESCE(worker_id::text,''), COALESCE(offered_to::text,''), COALESCE(progress_message,''), COALESCE(leg_status,'')
        FROM assignments WHERE journey_id = $1 ORDER BY sequence ASC, kind ASC
    `, body.JourneyID)
	defer rows.Close()
	legs := []map[string]interface{}{}
	for rows.Next() {
		var id, kind, status, from, to, worker, offered, progress, legStatus string
		var seq int
		if err := rows.Scan(&id, &kind, &status, &from, &to, &seq, &worker, &offered, &progress, &legStatus); err != nil {
			continue
		}
		legs = append(legs, map[string]interface{}{
			"assignmentId":      id,
			"kind":              kind,
			"status":            status,
			"fromLocationId":    from,
			"toLocationId":      to,
			"sequence":          seq,
			"workerId":          worker,
			"offeredTo":         offered,
			"progressMessage":   progress,
			"legStatus":         legStatus,
			"fromLocation":      h.lookupLocationMini(from),
			"toLocation":        h.lookupLocationMini(to),
		})
	}
	// stops
	rows2, _ := h.D.PG.Query(r.Context(), `
        SELECT id::text, COALESCE(location_id::text,''), stop_type, sequence, estimated_at, dwell_minutes, latitude, longitude, status
        FROM journey_stops WHERE journey_id = $1 ORDER BY sequence ASC
    `, body.JourneyID)
	defer rows2.Close()
	stops := []map[string]interface{}{}
	for rows2.Next() {
		var id, loc, stopType, status string
		var seq, dwell int
		var eta *time.Time
		var lat, lng float64
		if err := rows2.Scan(&id, &loc, &stopType, &seq, &eta, &dwell, &lat, &lng, &status); err != nil {
			continue
		}
		stops = append(stops, map[string]interface{}{
			"stopId":      id,
			"locationId":  loc,
			"location":    h.lookupLocationMini(loc),
			"stopType":    stopType,
			"sequence":    seq,
			"estimatedAt": eta,
			"dwellMinutes": dwell,
			"coordinate":  util.Coordinate{Latitude: lat, Longitude: lng}.ToMap(),
			"status":      status,
		})
	}
	// samples
	rows3, _ := h.D.PG.Query(r.Context(), `SELECT sample_id::text FROM journey_samples WHERE journey_id = $1`, body.JourneyID)
	defer rows3.Close()
	var sampleIDs []string
	for rows3.Next() {
		var id string
		if err := rows3.Scan(&id); err == nil {
			sampleIDs = append(sampleIDs, id)
		}
	}
	out := map[string]interface{}{
		"journeyId":            body.JourneyID,
		"planVersion":          plan.PlanVersion,
		"routeMode":            plan.RouteMode,
		"status":               plan.Status,
		"replanStatus":         plan.ReplanStatus,
		"estimatedDeliveryAt":  plan.EstimatedDeliveryAt,
		"totalCostUnits":       plan.TotalCostUnits,
		"legs":                 legs,
		"stops":                stops,
		"sampleIds":            sampleIDs,
		"expectedPlanVersion":  plan.PlanVersion,
	}
	// access check: if role is requester, ensure samples belong to them
	if p != nil && p.ActiveRole == "requester" {
		allMine := true
		for _, sid := range sampleIDs {
			s, err := domain.LoadSampleByID(r.Context(), h.D.PG, sid)
			if err != nil || s.RequesterID != p.User.ID {
				allMine = false
				break
			}
		}
		if !allMine {
			writeErr(w, http.StatusForbidden, "forbidden", "you do not own this journey")
			return
		}
	}
	ok(w, http.StatusOK, out)
}

// ListRoleWork returns current and past assignments visible to the caller for their active role.
func (h *CoreHandler) ListRoleWork(w http.ResponseWriter, r *http.Request) {
	p := auth.PrincipalOf(r)
	var body struct {
		Role   string `json:"role"`
		Status string `json:"status"`
	}
	if !util.ReadJSON(r, &body) {
		return
	}
	if body.Role == "" {
		body.Role = p.ActiveRole
	}
	if body.Role != p.ActiveRole && !p.HasRole("administrator") {
		writeErr(w, http.StatusForbidden, "forbidden", "role mismatch")
		return
	}
	role := body.Role
	var rows pgx.Rows
	switch role {
	case "collection_professional", "delivery_partner":
		rows, _ = h.D.PG.Query(r.Context(), `
            SELECT id::text, kind, status, COALESCE(from_location_id::text,''), COALESCE(to_location_id::text,''), sequence, journey_id::text, COALESCE(sample_id::text,''), progress_message, offered_at, completed_at
            FROM assignments
            WHERE (worker_id = $1 OR offered_to = $1)
              AND ($2 = '' OR status = $2)
            ORDER BY sequence ASC
        `, p.User.ID, body.Status)
	case "node_handler":
		rows, _ = h.D.PG.Query(r.Context(), `
            SELECT a.id::text, a.kind, a.status, COALESCE(a.from_location_id::text,''), COALESCE(a.to_location_id::text,''), a.sequence, a.journey_id::text, COALESCE(a.sample_id::text,''), a.progress_message, a.offered_at, a.completed_at
            FROM assignments a
            JOIN users u ON u.assigned_location_id = a.node_id
            WHERE u.id = $1
              AND ($2 = '' OR a.status = $2)
            ORDER BY a.sequence ASC
        `, p.User.ID, body.Status)
	case "laboratory_operator":
		rows, _ = h.D.PG.Query(r.Context(), `
            SELECT a.id::text, a.kind, a.status, COALESCE(a.from_location_id::text,''), COALESCE(a.to_location_id::text,''), a.sequence, a.journey_id::text, COALESCE(a.sample_id::text,''), a.progress_message, a.offered_at, a.completed_at
            FROM assignments a
            JOIN users u ON u.assigned_location_id = a.laboratory_id
            WHERE u.id = $1
              AND ($2 = '' OR a.status = $2)
            ORDER BY a.sequence ASC
        `, p.User.ID, body.Status)
	case "requester":
		rows, _ = h.D.PG.Query(r.Context(), `
            SELECT a.id::text, a.kind, a.status, COALESCE(a.from_location_id::text,''), COALESCE(a.to_location_id::text,''), a.sequence, a.journey_id::text, COALESCE(a.sample_id::text,''), a.progress_message, a.offered_at, a.completed_at
            FROM assignments a
            JOIN journey_samples js ON js.journey_id = a.journey_id
            JOIN samples s ON s.id = js.sample_id
            WHERE s.requester_id = $1
              AND ($2 = '' OR a.status = $2)
            ORDER BY a.sequence ASC
        `, p.User.ID, body.Status)
	case "dispatcher", "administrator":
		rows, _ = h.D.PG.Query(r.Context(), `
            SELECT id::text, kind, status, COALESCE(from_location_id::text,''), COALESCE(to_location_id::text,''), sequence, journey_id::text, COALESCE(sample_id::text,''), progress_message, offered_at, completed_at
            FROM assignments
            WHERE ($1 = '' OR status = $1)
            ORDER BY sequence ASC LIMIT 200
        `, body.Status)
	default:
		writeErr(w, http.StatusForbidden, "forbidden", "unknown role")
		return
	}
	defer rows.Close()
	current := []map[string]interface{}{}
	completed := []map[string]interface{}{}
	for rows.Next() {
		var id, kind, status, from, to, journey, sample, progress string
		var seq int
		var offered, completedAt *time.Time
		if err := rows.Scan(&id, &kind, &status, &from, &to, &seq, &journey, &sample, &progress, &offered, &completedAt); err != nil {
			continue
		}
		item := map[string]interface{}{
			"assignmentId":    id,
			"kind":            kind,
			"status":          status,
			"fromLocationId":  from,
			"toLocationId":    to,
			"sequence":        seq,
			"journeyId":       journey,
			"sampleId":        sample,
			"progressMessage": progress,
			"offeredAt":       offered,
			"completedAt":     completedAt,
			"fromLocation":    h.lookupLocationMini(from),
			"toLocation":      h.lookupLocationMini(to),
		}
		switch status {
		case "completed", "cancelled", "declined":
			completed = append(completed, item)
		default:
			current = append(current, item)
		}
	}
	ok(w, http.StatusOK, map[string]interface{}{
		"role":      role,
		"current":   current,
		"completed": completed,
	})
}

// SearchAudit returns matching audit log entries.
func (h *CoreHandler) SearchAudit(w http.ResponseWriter, r *http.Request) {
	var body struct {
		Query      string    `json:"query"`
		ActorID    string    `json:"actorId"`
		EntityType string    `json:"entityType"`
		EntityID   string    `json:"entityId"`
		Action     string    `json:"action"`
		Role       string    `json:"role"`
		Success    *bool     `json:"success"`
		FromTime   time.Time `json:"fromTime"`
		ToTime     time.Time `json:"toTime"`
		Limit      int       `json:"limit"`
		Offset     int       `json:"offset"`
		Order      string    `json:"order"`
	}
	if !util.ReadJSON(r, &body) {
		return
	}
	filter := domain.AuditFilter{
		EntityType: body.EntityType,
		EntityID:   body.EntityID,
		Action:     body.Action,
		ActorID:    body.ActorID,
		Role:       body.Role,
		Success:    body.Success,
		Query:      body.Query,
		Order:      body.Order,
		Limit:      body.Limit,
		Offset:     body.Offset,
	}
	entries, total, err := domain.SearchAudit(r.Context(), h.D.PG, filter)
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal", err.Error())
		return
	}
	if entries == nil {
		entries = []map[string]interface{}{}
	}
	ok(w, http.StatusOK, map[string]interface{}{
		"entries": entries,
		"total":   total,
		"limit":   body.Limit,
		"offset":  body.Offset,
	})
}

// ReadUser returns the user record.
func (h *CoreHandler) ReadUser(w http.ResponseWriter, r *http.Request) {
	id := r.PathValue("userId")
	u, err := h.Au.GetUserByID(r.Context(), id)
	if err != nil {
		writeErr(w, http.StatusNotFound, "not_found", "user not found")
		return
	}
	ok(w, http.StatusOK, h.Au.UserToMap(u))
}

