// lookupLocationMini returns a small location view by id.
func (h *CoreHandler) lookupLocationMini(id string) map[string]interface{} {
	if id == "" {
		return nil
	}
	row := h.D.PG.QueryRow(h.requestCtx(), `SELECT id::text, name, latitude, longitude, coverage_km, active FROM locations WHERE id = $1`, id)
	var lid, name string
	var lat, lng, coverage float64
	var active bool
