// CollectAndSealSample handles the collector's completion record.
func (h *CoreHandler) CollectAndSealSample(w http.ResponseWriter, r *http.Request) {
	p := auth.PrincipalOf(r)
	var body struct {
		SampleID            string    `json:"sampleId"`
		AssignmentID        string    `json:"assignmentId"`
		CollectedAt         time.Time `json:"collectedAt"`
		ContainerType       string    `json:"containerType"`
		ObservedTemperatureC float64   `json:"observedTemperatureC"`
		IdempotencyKey      string    `json:"idempotencyKey"`
	}
	if !util.ReadJSON(r, &body) {
		return
	}
	a, err := domain.LoadAssignmentByID(r.Context(), h.D.PG, body.AssignmentID)
	if err != nil {
		writeErr(w, http.StatusNotFound, "not_found", "assignment not found")
		return
	}
	if a.SampleID != body.SampleID {
		writeErr(w, http.StatusBadRequest, "mismatch", "sample/assignment mismatch")
		return
	}
	if a.WorkerID == nil || *a.WorkerID != p.User.ID {
		writeErr(w, http.StatusForbidden, "wrong_worker", "assignment not yours")
		return
	}
	if err := h.D.CollectAndSealSample(r.Context(), p, body.SampleID); err != nil {
		writeErr(w, http.StatusBadRequest, "invalid", err.Error())
		return
	}
	// record handling checkpoint
	compliant, _ := h.D.RecordHandlingCheckpoint(r.Context(), p, body.SampleID, body.ContainerType, body.ObservedTemperatureC, body.AssignmentID, "")
	ok(w, http.StatusOK, map[string]interface{}{
		"sampleId":   body.SampleID,
		"status":     "collected",
		"compliant":  compliant,
	})
}

