// UpdateAssignmentProgress records progress.
func (h *CoreHandler) UpdateAssignmentProgress(w http.ResponseWriter, r *http.Request) {
	p := auth.PrincipalOf(r)
	var body struct {
		AssignmentID   string    `json:"assignmentId"`
		Status         string    `json:"status"`
		OccurredAt     time.Time `json:"occurredAt"`
		IdempotencyKey string    `json:"idempotencyKey"`
	}
	if !util.ReadJSON(r, &body) {
		return
	}
	msg := body.Status
	a, err := domain.LoadAssignmentByID(r.Context(), h.D.PG, body.AssignmentID)
	if err == nil {
		// keep sample/holder consistent
		if body.Status == "picked_up" || body.Status == "at_pickup" {
			if a.SampleID != "" {
				if _, err := h.D.PG.Exec(r.Context(), `UPDATE samples SET status = 'in_transit' WHERE id = $1`, a.SampleID); err != nil {
					writeErr(w, http.StatusInternalServerError, "internal", err.Error())
					return
				}
			}
		}
		if body.Status == "completed" || body.Status == "delivered" {
			if a.SampleID != "" {
				if _, err := h.D.PG.Exec(r.Context(), `UPDATE samples SET status = 'in_transit' WHERE id = $1`, a.SampleID); err != nil {
					writeErr(w, http.StatusInternalServerError, "internal", err.Error())
					return
				}
			}
		}
	}
	if err := h.D.UpdateAssignmentProgress(r.Context(), p, body.AssignmentID, msg); err != nil {
		writeErr(w, http.StatusBadRequest, "invalid", err.Error())
		return
	}
	if _, err := h.D.PG.Exec(r.Context(), `UPDATE assignments SET leg_status = $2 WHERE id = $1`, body.AssignmentID, body.Status); err != nil {
		writeErr(w, http.StatusInternalServerError, "internal", err.Error())
		return
	}
	ok(w, http.StatusOK, map[string]interface{}{
		"assignmentId": body.AssignmentID,
		"status":       body.Status,
	})
}

// CancelJourney terminates the journey and releases capacity.
func (h *CoreHandler) CancelJourney(w http.ResponseWriter, r *http.Request) {
	p := auth.PrincipalOf(r)
	var body struct {
		JourneyID           string `json:"journeyId"`
		ExpectedPlanVersion int    `json:"expectedPlanVersion"`
		Reason              string `json:"reason"`
		IdempotencyKey      string `json:"idempotencyKey"`
	}
	if !util.ReadJSON(r, &body) {
		return
	}
	var cur int
	if err := h.D.PG.QueryRow(r.Context(), `SELECT plan_version FROM journeys WHERE id = $1`, body.JourneyID).Scan(&cur); err != nil {
		writeErr(w, http.StatusNotFound, "not_found", "journey not found")
		return
	}
	if cur != body.ExpectedPlanVersion {
		writeErr(w, http.StatusConflict, "stale_version", "plan version mismatch")
		return
	}
	if err := h.D.CancelJourney(r.Context(), p, body.JourneyID, body.Reason); err != nil {
		writeErr(w, http.StatusBadRequest, "invalid", err.Error())
		return
	}
	ok(w, http.StatusOK, map[string]interface{}{
		"journeyId":  body.JourneyID,
		"status":     "cancelled",
	})
}

