// EditActivePlan dispatches plan edits to the appropriate planner.
func (h *CoreHandler) EditActivePlan(w http.ResponseWriter, r *http.Request) {
	p := auth.PrincipalOf(r)
	var body struct {
		JourneyID           string                 `json:"journeyId"`
		ExpectedPlanVersion int                    `json:"expectedPlanVersion"`
		ChangeType          string                 `json:"changeType"`
		Changes             map[string]interface{} `json:"changes"`
		IdempotencyKey      string                 `json:"idempotencyKey"`
	}
	if !util.ReadJSON(r, &body) {
		return
	}
	var cur int
	if err := h.D.PG.QueryRow(r.Context(), `SELECT plan_version FROM journeys WHERE id = $1`, body.JourneyID).Scan(&cur); err != nil {
		writeErr(w, http.StatusNotFound, "not_found", "journey not found")
		return
	}
	if cur != body.ExpectedPlanVersion {
		writeErr(w, http.StatusConflict, "stale_version", "plan version mismatch")
		return
	}
	switch body.ChangeType {
	case "reroute", "replace_route":
		replacement, err := h.D.RerouteJourney(r.Context(), p, body.JourneyID)
		if err != nil {
			writeErr(w, http.StatusBadRequest, "invalid", err.Error())
			return
		}
		ok(w, http.StatusOK, map[string]interface{}{
			"journeyId":            body.JourneyID,
			"replacementJourneyId": replacement,
			"changeType":           body.ChangeType,
		})
		return
	case "cancel_work":
		if err := h.D.CancelJourney(r.Context(), p, body.JourneyID, "plan_edit"); err != nil {
			writeErr(w, http.StatusBadRequest, "invalid", err.Error())
			return
		}
		ok(w, http.StatusOK, map[string]interface{}{"journeyId": body.JourneyID, "status": "cancelled"})
		return
	default:
		// unknown change type: just record
		domain.AuditAction(r.Context(), h.D.PG, p, "edit_plan", "journey", body.JourneyID, true, map[string]interface{}{"changeType": body.ChangeType})
		ok(w, http.StatusOK, map[string]interface{}{"journeyId": body.JourneyID, "changeType": body.ChangeType, "applied": false})
	}
}

// MergeJourneys merges multiple source journeys into the target.
func (h *CoreHandler) MergeJourneys(w http.ResponseWriter, r *http.Request) {
	p := auth.PrincipalOf(r)
	var body struct {
		TargetJourneyID    string   `json:"targetJourneyId"`
		ExpectedPlanVersion int      `json:"expectedPlanVersion"`
		SourceJourneyIDs   []string `json:"sourceJourneyIds"`
		IdempotencyKey     string   `json:"idempotencyKey"`
	}
	if !util.ReadJSON(r, &body) {
		return
	}
	var cur int
	if err := h.D.PG.QueryRow(r.Context(), `SELECT plan_version FROM journeys WHERE id = $1`, body.TargetJourneyID).Scan(&cur); err != nil {
		writeErr(w, http.StatusNotFound, "not_found", "target journey not found")
		return
	}
	if cur != body.ExpectedPlanVersion {
		writeErr(w, http.StatusConflict, "stale_version", "plan version mismatch")
		return
	}
	tx, err := h.D.PG.Begin(r.Context())
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal", err.Error())
		return
	}
	defer tx.Rollback(r.Context())
	for _, sid := range body.SourceJourneyIDs {
		if _, err := tx.Exec(r.Context(), `
            UPDATE journey_samples SET journey_id = $1 WHERE journey_id = $2
        `, body.TargetJourneyID, sid); err != nil {
			writeErr(w, http.StatusInternalServerError, "internal", err.Error())
			return
		}
		if _, err := tx.Exec(r.Context(), `UPDATE journeys SET status = 'merged', active = FALSE WHERE id = $1`, sid); err != nil {
			writeErr(w, http.StatusInternalServerError, "internal", err.Error())
			return
		}
	}
	if _, err := tx.Exec(r.Context(), `UPDATE journeys SET plan_version = plan_version + 1 WHERE id = $1`, body.TargetJourneyID); err != nil {
		writeErr(w, http.StatusInternalServerError, "internal", err.Error())
		return
	}
	if err := tx.Commit(r.Context()); err != nil {
		writeErr(w, http.StatusInternalServerError, "internal", err.Error())
		return
	}
	domain.AuditAction(r.Context(), h.D.PG, p, "merge_journeys", "journey", body.TargetJourneyID, true, map[string]interface{}{"sourceJourneyIds": body.SourceJourneyIDs})
	ok(w, http.StatusOK, map[string]interface{}{
		"targetJourneyId":    body.TargetJourneyID,
		"sourceJourneyIds":   body.SourceJourneyIDs,
	})
}

// SplitJourney separates a sample out of an existing journey.
func (h *CoreHandler) SplitJourney(w http.ResponseWriter, r *http.Request) {
	p := auth.PrincipalOf(r)
	var body struct {
		JourneyID           string   `json:"journeyId"`
		ExpectedPlanVersion int      `json:"expectedPlanVersion"`
		SampleIDs           []string `json:"sampleIds"`
		IdempotencyKey      string   `json:"idempotencyKey"`
	}
	if !util.ReadJSON(r, &body) {
		return
	}
	var cur int
	if err := h.D.PG.QueryRow(r.Context(), `SELECT plan_version FROM journeys WHERE id = $1`, body.JourneyID).Scan(&cur); err != nil {
		writeErr(w, http.StatusNotFound, "not_found", "journey not found")
		return
	}
	if cur != body.ExpectedPlanVersion {
		writeErr(w, http.StatusConflict, "stale_version", "plan version mismatch")
		return
	}
	newJourneyID := domain.UUID()
	tx, err := h.D.PG.Begin(r.Context())
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal", err.Error())
		return
	}
	defer tx.Rollback(r.Context())
	if _, err := tx.Exec(r.Context(), `
        INSERT INTO journeys (id, plan_version, route_mode, status, active)
        VALUES ($1, 1, 'direct', 'planned', TRUE)
    `, newJourneyID); err != nil {
		writeErr(w, http.StatusInternalServerError, "internal", err.Error())
		return
	}
	for _, sid := range body.SampleIDs {
		if _, err := tx.Exec(r.Context(), `UPDATE journey_samples SET journey_id = $1 WHERE journey_id = $2 AND sample_id = $3`, newJourneyID, body.JourneyID, sid); err != nil {
			writeErr(w, http.StatusInternalServerError, "internal", err.Error())
			return
		}
		if _, err := tx.Exec(r.Context(), `UPDATE samples SET active_journey_id = $1 WHERE id = $2`, newJourneyID, sid); err != nil {
			writeErr(w, http.StatusInternalServerError, "internal", err.Error())
			return
		}
	}
	if err := tx.Commit(r.Context()); err != nil {
		writeErr(w, http.StatusInternalServerError, "internal", err.Error())
		return
	}
	domain.AuditAction(r.Context(), h.D.PG, p, "split_journey", "journey", body.JourneyID, true, map[string]interface{}{"newJourneyId": newJourneyID, "sampleIds": body.SampleIDs})
	ok(w, http.StatusOK, map[string]interface{}{
		"journeyId":         body.JourneyID,
		"newJourneyId":      newJourneyID,
		"splitSampleIds":    body.SampleIDs,
	})
}

// ReportDisruption notifies the system of a network/worker disruption.
func (h *CoreHandler) ReportDisruption(w http.ResponseWriter, r *http.Request) {
	p := auth.PrincipalOf(r)
	var body struct {
		ResourceType   string    `json:"resourceType"`
		ResourceID     string    `json:"resourceId"`
		Reason         string    `json:"reason"`
		OccurredAt     time.Time `json:"occurredAt"`
		IdempotencyKey string    `json:"idempotencyKey"`
	}
	if !util.ReadJSON(r, &body) {
		return
	}
	switch body.ResourceType {
	case "connection":
		if _, err := h.D.PG.Exec(r.Context(), `UPDATE connections SET active = FALSE WHERE id = $1`, body.ResourceID); err != nil {
			writeErr(w, http.StatusInternalServerError, "internal", err.Error())
			return
		}
	case "node", "location", "laboratory":
		if _, err := h.D.PG.Exec(r.Context(), `UPDATE locations SET active = FALSE WHERE id = $1`, body.ResourceID); err != nil {
			writeErr(w, http.StatusInternalServerError, "internal", err.Error())
			return
		}
	case "worker":
		if _, err := h.D.PG.Exec(r.Context(), `UPDATE users SET active = FALSE WHERE id = $1`, body.ResourceID); err != nil {
			writeErr(w, http.StatusInternalServerError, "internal", err.Error())
			return
		}
	}
	domain.AuditAction(r.Context(), h.D.PG, p, "report_disruption", body.ResourceType, body.ResourceID, true, map[string]interface{}{"reason": body.Reason})
	go h.D.Svc.Recompute(context.Background())
	ok(w, http.StatusOK, map[string]interface{}{
		"resourceType": body.ResourceType,
		"resourceId":   body.ResourceID,
		"applied":      true,
	})
}

