// CreateLocation creates a new network node.
func (h *CoreHandler) CreateLocation(w http.ResponseWriter, r *http.Request) {
	p := auth.PrincipalOf(r)
	if !p.HasRole("administrator") {
		writeErr(w, http.StatusForbidden, "forbidden", "admin required")
		return
	}
	var body struct {
		Name            string           `json:"name"`
		Coordinate      *util.Coordinate `json:"coordinate"`
		CoverageKm      float64          `json:"coverageKm"`
		HandlingMinutes int              `json:"handlingMinutes"`
		Active          bool             `json:"active"`
		Functions       []string         `json:"functions"`
	}
	if !util.ReadJSON(r, &body) {
		return
	}
	if body.CoverageKm <= 0 || body.CoverageKm > 5 {
		body.CoverageKm = 5
	}
	id := domain.UUID()
	functions := util.FunctionsArrayToJSON(body.Functions)
	if _, err := h.D.PG.Exec(r.Context(), `
        INSERT INTO locations (id, name, latitude, longitude, coverage_km, handling_minutes, active, functions)
        VALUES ($1,$2,$3,$4,$5,$6,$7,$8)
    `, id, body.Name, body.Coordinate.Latitude, body.Coordinate.Longitude, body.CoverageKm, body.HandlingMinutes, body.Active, functions); err != nil {
		writeErr(w, http.StatusInternalServerError, "internal", err.Error())
		return
	}
	if _, err := h.D.PG.Exec(r.Context(), `
        INSERT INTO capacity_pools (resource_kind, resource_id, capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units)
        VALUES ('location', $1, 0, 0, 0, 0)
    `, id); err != nil {
		writeErr(w, http.StatusInternalServerError, "internal", err.Error())
		return
	}
	// bump network revision + recompute
	_, _ = h.D.PG.Exec(r.Context(), `UPDATE network_state SET revision = revision + 1 WHERE id = 1`)
	go h.D.Svc.Recompute(r.Context())
	domain.AuditAction(r.Context(), h.D.PG, p, "create_location", "location", id, true, map[string]interface{}{"name": body.Name})
	ok(w, http.StatusOK, map[string]interface{}{
		"locationId":      id,
		"name":            body.Name,
		"coordinate":      body.Coordinate.ToMap(),
		"coverageKm":      body.CoverageKm,
		"handlingMinutes": body.HandlingMinutes,
		"active":          body.Active,
		"functions":       body.Functions,
	})
}

