// ConfigureCapacity sets a pool's configured capacity.
func (h *CoreHandler) ConfigureCapacity(w http.ResponseWriter, r *http.Request) {
	p := auth.PrincipalOf(r)
	if !p.HasRole("administrator") {
		writeErr(w, http.StatusForbidden, "forbidden", "admin required")
		return
	}
	var body struct {
		ResourceID         string `json:"resourceId"`
		CapacityUnits      int    `json:"capacityUnits"`
		CooledCapacityUnits int   `json:"cooledCapacityUnits"`
	}
	if !util.ReadJSON(r, &body) {
		return
	}
	// resource may be a location or a connection
	kind := "location"
	var exists bool
	_ = h.D.PG.QueryRow(r.Context(), `SELECT EXISTS(SELECT 1 FROM locations WHERE id = $1)`, body.ResourceID).Scan(&exists)
	if !exists {
		kind = "connection"
		_ = h.D.PG.QueryRow(r.Context(), `SELECT EXISTS(SELECT 1 FROM connections WHERE id = $1)`, body.ResourceID).Scan(&exists)
		if !exists {
			writeErr(w, http.StatusNotFound, "not_found", "resource not found")
			return
		}
	}
	if _, err := h.D.PG.Exec(r.Context(), `
        INSERT INTO capacity_pools (resource_kind, resource_id, capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units)
        VALUES ($1,$2,$3,0,$4,0)
        ON CONFLICT (resource_kind, resource_id)
        DO UPDATE SET capacity_units = $3, cooled_capacity_units = $4
    `, kind, body.ResourceID, body.CapacityUnits, body.CooledCapacityUnits); err != nil {
		writeErr(w, http.StatusInternalServerError, "internal", err.Error())
		return
	}
	_, _ = h.D.PG.Exec(r.Context(), `UPDATE network_state SET revision = revision + 1 WHERE id = 1`)
	go h.D.Svc.Recompute(r.Context())
	domain.AuditAction(r.Context(), h.D.PG, p, "configure_capacity", "capacity", body.ResourceID, true, map[string]interface{}{"regular": body.CapacityUnits, "cooled": body.CooledCapacityUnits})
	ok(w, http.StatusOK, map[string]interface{}{
		"resourceId":          body.ResourceID,
		"capacityUnits":       body.CapacityUnits,
		"cooledCapacityUnits": body.CooledCapacityUnits,
	})
}

