// CreateUser adds a new user.
func (h *CoreHandler) CreateUser(w http.ResponseWriter, r *http.Request) {
	p := auth.PrincipalOf(r)
	if !p.HasRole("administrator") {
		writeErr(w, http.StatusForbidden, "forbidden", "admin required")
		return
	}
	var body struct {
		Username          string   `json:"username"`
		InitialPassword   string   `json:"initialPassword"`
		Email             string   `json:"email"`
		FullName          string   `json:"fullName"`
		Phone             string   `json:"phone"`
		Roles             []string `json:"roles"`
		Qualifications    []string `json:"qualifications"`
		Certifications    []map[string]interface{} `json:"certifications"`
		Active            bool     `json:"active"`
		AssignedLocationID string  `json:"assignedLocationId"`
	}
	if !util.ReadJSON(r, &body) {
		return
	}
	u := &auth.User{
		Username:           body.Username,
		Email:              body.Email,
		FullName:           body.FullName,
		Phone:              body.Phone,
		Roles:              body.Roles,
		Qualifications:     body.Qualifications,
		Active:             body.Active,
		AssignedLocationID: body.AssignedLocationID,
	}
	if err := h.Au.CreateUser(r.Context(), u, body.InitialPassword); err != nil {
		writeErr(w, http.StatusBadRequest, "invalid", err.Error())
		return
	}
	// certifications
	for _, cert := range body.Certifications {
		code, _ := cert["code"].(string)
		desc, _ := cert["description"].(string)
		if code == "" {
			continue
		}
		_, _ = h.D.PG.Exec(r.Context(), `INSERT INTO certifications (user_id, code, description, active) VALUES ($1,$2,$3,TRUE) ON CONFLICT (user_id, code) DO NOTHING`, u.ID, code, desc)
	}
	domain.AuditAction(r.Context(), h.D.PG, p, "create_user", "user", u.ID, true, map[string]interface{}{"roles": u.Roles})
	ok(w, http.StatusOK, h.Au.UserToMap(u))
