// OperationsState returns dashboard tiles for dispatcher/administrator.
func (h *CoreHandler) OperationsState(w http.ResponseWriter, r *http.Request) {
	now := time.Now().UTC()
	out := map[string]interface{}{}
	// samples by status
	rows, _ := h.D.PG.Query(r.Context(), `SELECT status, COUNT(*) FROM samples GROUP BY status`)
	defer rows.Close()
	byStatus := map[string]int{}
	for rows.Next() {
		var s string
		var c int
		if err := rows.Scan(&s, &c); err == nil {
			byStatus[s] = c
		}
	}
	out["samplesByStatus"] = byStatus
	// assignments by status
	rows2, _ := h.D.PG.Query(r.Context(), `SELECT status, COUNT(*) FROM assignments GROUP BY status`)
	defer rows2.Close()
	asgByStatus := map[string]int{}
	for rows2.Next() {
		var s string
		var c int
		if err := rows2.Scan(&s, &c); err == nil {
			asgByStatus[s] = c
		}
	}
	out["assignmentsByStatus"] = asgByStatus
	// workers
	rows3, _ := h.D.PG.Query(r.Context(), `
        SELECT u.id::text, u.full_name, u.username,
               (SELECT COUNT(*) FROM assignments a WHERE a.worker_id = u.id AND a.status IN ('accepted','in_progress')) as active_load,
               (u.last_lat, u.last_lng, u.last_loc_at)
        FROM users u WHERE u.active
    `)
	defer rows3.Close()
	type worker struct {
		UserID, FullName, Username string
		ActiveLoad                 int
		LastLat, LastLng           *float64
		LastLocAt                  *time.Time
	}
	var workers []worker
	for rows3.Next() {
		var w worker
		var lat, lng *float64
		var locAt *time.Time
		if err := rows3.Scan(&w.UserID, &w.FullName, &w.Username, &w.ActiveLoad, &lat, &lng, &locAt); err == nil {
			w.LastLat = lat
			w.LastLng = lng
			w.LastLocAt = locAt
			workers = append(workers, w)
		}
	}
	workerOut := []map[string]interface{}{}
	for _, w := range workers {
		stale := false
		if w.LastLocAt == nil || now.Sub(*w.LastLocAt) > 10*time.Minute {
			stale = true
		}
		workerOut = append(workerOut, map[string]interface{}{
			"userId": w.UserID,
			"fullName": w.FullName,
			"username": w.Username,
			"activeLoad": w.ActiveLoad,
			"latestLocation": map[string]interface{}{
				"latitude": w.LastLat,
				"longitude": w.LastLng,
				"recordedAt": w.LastLocAt,
			},
			"locationStale": stale,
		})
	}
	out["workers"] = workerOut
	// active journeys
	rows4, _ := h.D.PG.Query(r.Context(), `SELECT id::text, plan_version, status, estimated_delivery_at FROM journeys WHERE active`)
	defer rows4.Close()
	var journeys []map[string]interface{}
	for rows4.Next() {
		var id, status string
		var planV int
		var eta *time.Time
		if err := rows4.Scan(&id, &planV, &status, &eta); err == nil {
			journeys = append(journeys, map[string]interface{}{
				"journeyId": id,
				"planVersion": planV,
				"status": status,
				"estimatedDeliveryAt": eta,
			})
		}
	}
	out["activeJourneys"] = journeys
	out["serverTime"] = now.Format(time.RFC3339Nano)
	out["nodeCount"], _ = func() (int, error) {
		var n int
		err := h.D.PG.QueryRow(r.Context(), `SELECT COUNT(*) FROM locations WHERE active`).Scan(&n)
		return n, err
	}()
	out["exceptionCount"], _ = func() (int, error) {
		var n int
		err := h.D.PG.QueryRow(r.Context(), `SELECT COUNT(*) FROM samples WHERE status = 'exception'`).Scan(&n)
		return n, err
	}()
	ok(w, http.StatusOK, out)
}

