{"security_risk":"LOW","summary":"Main entrypoint","command":"create","path":"/workspace/backend/cmd/server/main.go","file_text":"package main

import (
	"context"
	"log"
	"net/http"
	"os"
	"os/signal"
	"syscall"
	"time"

	"github.com/lablogistics/backend/internal/auth"
	"github.com/lablogistics/backend/internal/db"
	"github.com/lablogistics/backend/internal/domain"
	"github.com/lablogistics/backend/internal/events"
	"github.com/lablogistics/backend/internal/handlers"
	"github.com/lablogistics/backend/internal/server"
	"github.com/lablogistics/backend/internal/serviceability"
)

func main() {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	store, err := db.Open(ctx)
	if err != nil {
		log.Fatalf("db open: %v", err)
	}
	defer store.Close()

	au := auth.New(store.PG)
	mw := auth.NewMiddleware(store, au)
	bus := events.New(store)
	svc := serviceability.New(store.PG)
	if err := svc.EnsureLoaded(ctx); err != nil {
		log.Printf("serviceability initial: %v", err)
	}
	d := domain.NewDomain(store.PG, au, svc, bus, store)

	// seed default sample types
	if err := domain.EnsureDefaultSampleTypes(ctx, store.PG); err != nil {
		log.Printf("ensure default sample types: %v", err)
	}
	if err := domain.EnsureDefaultSampleTypeCertifications(ctx, store.PG); err != nil {
		log.Printf("ensure certifications: %v", err)
	}

	authh := handlers.NewAuthHandler(d, au)
	core := handlers.NewCoreHandler(d, au)

	if err := authh.EnsureAdminFromEnv(ctx); err != nil {
		log.Printf("ensure admin: %v", err)
	}

	router := server.Router(authh, core, mw, store.PG)

	addr := os.Getenv("BACKEND_ADDR")
	if addr == "" {
		addr = "127.0.0.1:18082"
	}
	srv := &http.Server{Addr: addr, Handler: router, ReadHeaderTimeout: 10 * time.Second}

	go func() {
		log.Printf("backend listening on %s", addr)
		if err := srv.ListenAndServe(); err != nil && err != http.ErrServerClosed {
			log.Fatalf("listen: %v", err)
		}
	}()

	stop := make(chan os.Signal, 1)
	signal.Notify(stop, syscall.SIGINT, syscall.SIGTERM)
	<-stop
	log.Printf("shutting down")
	shutCtx, c := context.WithTimeout(context.Background(), 10*time.Second)
	defer c()
	_ = srv.Shutdown(shutCtx)
}"}

