import (
	"context"
	"encoding/json"
	"net/http"
	"time"

	"github.com/jackc/pgx/v5/pgxpool"
	"github.com/lablogistics/backend/internal/auth"
	"github.com/lablogistics/backend/internal/domain"
	"github.com/lablogistics/backend/internal/util"
)

// CoreHandler bundles dependencies shared across non-auth endpoints.
type CoreHandler struct {
	D  *domain.Domain
	Au *auth.Auth
}

func NewCoreHandler(d *domain.Domain, au *auth.Auth) *CoreHandler {
	return &CoreHandler{D: d, Au: au}
}

// AuthHandler handles auth endpoints.
type AuthHandler struct {
	D  *domain.Domain
	Au *auth.Auth
}

func NewAuthHandler(d *domain.Domain, au *auth.Auth) *AuthHandler {
	return &AuthHandler{D: d, Au: au}
}

func writeErr(w http.ResponseWriter, status int, code, msg string) {
	util.WriteError(w, status, code, msg)
}

func ok(w http.ResponseWriter, status int, payload interface{}) {
	util.WriteJSON(w, status, payload)
}

// requestCtx returns a fresh background context used for helper DB lookups not tied to the request lifecycle.
func (h *CoreHandler) requestCtx() context.Context { return context.Background() }

// lookupLocationMini returns a {locationId, name, latitude, longitude} mini.
func (h *CoreHandler) lookupLocationMini(id string) map[string]interface{} {
	var name string
	var lat, lng float64
	if err := h.D.PG.QueryRow(context.Background(), `SELECT name, latitude, longitude FROM locations WHERE id = $1`, id).Scan(&name, &lat, &lng); err != nil {
		return nil
	}
	return map[string]interface{}{
		"locationId": id,
		"name":       name,
		"latitude":   lat,
		"longitude":  lng,
	}
}

// loadSample loads a Sample from Postgres.
func (h *CoreHandler) loadSample(ctx context.Context, id string) (*domain.Sample, error) {
	return domain.LoadSampleByID(ctx, h.D.PG, id)
}

// listAudit returns up to `limit` audit entries for an entity.
func (h *CoreHandler) listAudit(ctx context.Context, entityType, entityID string, limit int) ([]map[string]interface{}, error) {
	if limit <= 0 || limit > 200 {
		limit = 100
	}
	rows, err := h.D.PG.Query(ctx, `
        SELECT id::text, actor_id::text, COALESCE(active_role,''), action, entity_type, entity_id::text, success, occurred_at, COALESCE(changes,'{}'::jsonb)
        FROM audit_log
        WHERE entity_type = $1 AND entity_id = $2
        ORDER BY occurred_at DESC LIMIT $3
    `, entityType, entityID, limit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	out := []map[string]interface{}{}
	for rows.Next() {
		var id, actor, role, action, et, eid string
		var success bool
		var at time.Time
		var det []byte
		if err := rows.Scan(&id, &actor, &role, &action, &et, &eid, &success, &at, &det); err == nil {
			out = append(out, map[string]interface{}{
				"auditId":   id,
				"actorId":   actor,
				"role":      role,
				"action":    action,
				"entityType": et,
				"entityId":  eid,
				"success":   success,
				"occurredAt": at.UTC().Format(time.RFC3339Nano),
				"details":   json.RawMessage(det),
			})
		}
	}
	return out, nil
}

// pgPool re-exports pgx pool for downstream code that needs it.
func (h *CoreHandler) pgPool() *pgxpool.Pool { return h.D.PG }"}

