import (
	"net/http"
	"time"

	"github.com/lablogistics/backend/internal/auth"
)

// AuthHandler bundles authentication endpoints.
type AuthHandler struct {
	A *auth.Authenticator
}

func NewAuthHandler(a *auth.Authenticator) *AuthHandler { return &AuthHandler{A: a} }

// POST /api/authenticate-user
func (h *AuthHandler) AuthenticateUser(w http.ResponseWriter, r *http.Request) {
	var body struct {
		Username string `json:"username"`
		Password string `json:"password"`
	}
	if !parseJSON(w, r, &body) {
		return
	}
	if body.Username == "" || body.Password == "" {
		writeErr(w, http.StatusBadRequest, "invalid_json", "username and password required")
		return
	}
	u, err := h.A.GetUserByUsername(r.Context(), body.Username)
	if err != nil || !u.Active || !auth.CheckPassword(u.PasswordHash, body.Password) {
		writeErr(w, http.StatusUnauthorized, "invalid_credentials", "invalid credentials")
		return
	}
	role := "requester"
	if len(u.Roles) > 0 {
		role = u.Roles[0]
	}
	sess, err := h.A.IssueSession(r.Context(), u.ID, role, 7*24*time.Hour)
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	auditAction(r.Context(), h.A.PG, u.ID, role, "sign_in", "user", u.ID, true, map[string]interface{}{"username": u.Username})
	data(w, http.StatusOK, map[string]interface{}{
		"sessionToken": sess.Token,
		"userId":       u.ID,
		"roles":        u.Roles,
		"activeRole":   role,
	})
}

// DELETE /api/session
func (h *AuthHandler) SignOut(w http.ResponseWriter, r *http.Request) {
	p := auth.PrincipalOf(r)
	if p == nil || p.Session == nil {
		writeErr(w, http.StatusUnauthorized, "unauthorized", "not signed in")
		return
	}
	if err := h.A.DeleteSession(r.Context(), p.Session.Token); err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	auditAction(r.Context(), h.A.PG, p.User.ID, p.ActiveRole, "sign_out", "session", p.Session.Token, true, nil)
	data(w, http.StatusOK, map[string]interface{}{
		"userId":  p.User.ID,
		"status":  "signed_out",
	})
}"}

