// data writes a {"data": ...} envelope with the given status.
func data(w http.ResponseWriter, status int, payload interface{}) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(map[string]interface{}{"data": payload})
}

// writeErr writes a standard {"error": ..., "code": ...} envelope.
func writeErr(w http.ResponseWriter, status int, code, message string) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(map[string]interface{}{"error": message, "code": code})
}

// parseJSON decodes the body into v and writes a 400 on failure.
func parseJSON(w http.ResponseWriter, r *http.Request, v interface{}) bool {
	if err := json.NewDecoder(r.Body).Decode(v); err != nil {
		writeErr(w, http.StatusBadRequest, "invalid_json", "invalid JSON body")
		return false
	}
	return true
}

// auditAction inserts a row into audit_log. Optional.
func auditAction(ctx context.Context, pg *pgxpool.Pool, actorID, role, action, entityType, entityID string, success bool, details map[string]interface{}) {
	if pg == nil {
		return
	}
	if details == nil {
		details = map[string]interface{}{}
	}
	detailsJSON, _ := json.Marshal(details)
	var actor interface{}
	if actorID != "" {
		actor = actorID
	}
	_, _ = pg.Exec(ctx, `
        INSERT INTO audit_log (actor_id, role, action, entity_type, entity_id, success, details)
        VALUES ($1,$2,$3,$4,$5,$6,$7)
    `, actor, role, action, entityType, entityID, success, detailsJSON)
}

// coordMap is a JSON-friendly lat/lng pair.
func coordMap(lat, lng float64) map[string]float64 {
	return map[string]float64{"latitude": lat, "longitude": lng}
}

// stringP returns a pointer to s, or nil if s is empty.
func stringP(s string) *string {
	if s == "" {
		return nil
	}
	return &s
}

// notNilString returns v if non-nil, else "".
func notNilString(v *string) string {
	if v == nil {
		return ""
	}
	return *v
}

// parseTime parses a RFC3339 string into time.Time via util helper.
func parseTime(s string) (t util.Time, ok bool) {
	if s == "" {
		return
	}
	return util.ParseTime(s)
}"}

