// GET /api/ui/bootstrap
func (h *CoreHandler) Bootstrap(w http.ResponseWriter, r *http.Request) {
	p := auth.PrincipalOf(r)
	if p == nil {
		writeErr(w, http.StatusUnauthorized, "unauthorized", "not signed in")
		return
	}
	ctx := r.Context()

	// users
	rows, _ := h.PG.Query(ctx, `
        SELECT id::text, username, COALESCE(email,''), COALESCE(full_name,''), COALESCE(phone,''),
               roles, COALESCE(qualifications, '{}'::text[]),
               COALESCE(assigned_location_id::text,''), active
        FROM users ORDER BY created_at
    `)
