        SELECT id::text, code, name, COALESCE(description,''), requires_qualified_collector,
               container_type, COALESCE(temperature_min_c,0), COALESCE(temperature_max_c,0),
               requires_cooled, COALESCE(incompatible_sample_type_ids::text[],'{}'::text[]),
               pulse_critical, active
        FROM sample_types ORDER BY name
    `)
	var sampleTypes []map[string]interface{}
	for stRows != nil && stRows.Next() {
		var id, code, name, desc, container string
		var reqColl, reqCool, pulse, active bool
