	if stRows != nil {
		stRows.Close()
	}

	// locations
	locRows, _ := h.PG.Query(ctx, `
        SELECT l.id::text, l.name, l.latitude, l.longitude, l.coverage_km, l.handling_minutes, l.active,
               l.functions, COALESCE(l.address,''),
               (SELECT json_agg(json_build_object('capacityPoolId', cp.id::text, 'kind', cp.kind,
