// jsonUnmarshal decodes JSON bytes into v; swallows errors so callers can
// continue with a zero value.
func jsonUnmarshal(b []byte, v interface{}) error {
	if len(b) == 0 {
		return nil
	}
	return jsonDecodeBytes(b, v)
}

// jsonDecodeBytes is split out so the import is referenced exactly once.
func jsonDecodeBytes(b []byte, v interface{}) error {
	return jsonSTDDecode(b, v)
}

