// CoreHandler owns the bulk of the domain endpoints.
type CoreHandler struct {
	PG *pgxpool.Pool
	A  *auth.Authenticator
	S  *serviceability.Engine
	B  *events.Bus
}

func NewCoreHandler(pg *pgxpool.Pool, a *auth.Authenticator, s *serviceability.Engine, b *events.Bus) *CoreHandler {
	return &CoreHandler{PG: pg, A: a, S: s, B: b}
}

// ------------------------------------------------- shared small helpers --

func (h *CoreHandler) publish(ctx context.Context, evType, entityType, entityID string, payload map[string]interface{}) {
	if h.B == nil {
		return
	}
	h.B.Publish(ctx, evType, entityType, entityID, payload)
}

func (h *CoreHandler) invalidateServiceability(ctx context.Context) {
	if h.S != nil {
		h.S.Invalidate(ctx)
	}
}

func (h *CoreHandler) bumpPlanVersion(ctx context.Context, tx pgx.Tx, journeyID string) (int, error) {
	var v int
	row := tx.QueryRow(ctx, `UPDATE journeys SET plan_version = plan_version + 1 WHERE id = $1 RETURNING plan_version`, journeyID)
	if err := row.Scan(&v); err != nil {
		return 0, err
	}
	return v, nil
}

func requireRole(w http.ResponseWriter, r *http.Request, allowed ...string) *auth.Principal {
	p := auth.PrincipalOf(r)
	if p == nil {
		writeErr(w, http.StatusUnauthorized, "unauthorized", "not signed in")
		return nil
	}
	if !p.HasAnyRole(allowed...) {
		writeErr(w, http.StatusForbidden, "forbidden", "role not permitted")
		return nil
	}
	if !util.RolesContain(p.User.Roles, p.ActiveRole) {
		writeErr(w, http.StatusForbidden, "role_not_held", "active role not held")
		return nil
	}
	return p
}

func safeJSONUnmarshal(b []byte, v interface{}) error {
	if len(b) == 0 {
		return nil
	}
	return json.Unmarshal(b, v)
}

// ------------------------------------------------- authentication --

// POST /api/select-active-role
func (h *CoreHandler) SelectActiveRole(w http.ResponseWriter, r *http.Request) {
	p := requireRole(w, r, "administrator", "requester", "collection_professional", "delivery_partner", "node_handler", "laboratory_team", "dispatcher")
	if p == nil {
		return
	}
	var body struct {
		Role string `json:"role"`
	}
	if !parseJSON(w, r, &body) {
		return
	}
	body.Role = util.NormalizeRole(body.Role)
	if !util.RolesContain(p.User.Roles, body.Role) {
		writeErr(w, http.StatusBadRequest, "role_not_held", "role not assigned to user")
		return
	}
	if err := h.A.SetActiveRole(r.Context(), p.Session.Token, body.Role); err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	p.ActiveRole = body.Role
	auditAction(r.Context(), h.PG, p.User.ID, body.Role, "select_active_role", "user", p.User.ID, true, map[string]interface{}{"role": body.Role})
	data(w, http.StatusOK, map[string]interface{}{
		"userId":     p.User.ID,
		"activeRole": body.Role,
		"roles":      p.User.Roles,
	})
}

// POST /api/set-worker-availability
func (h *CoreHandler) SetWorkerAvailability(w http.ResponseWriter, r *http.Request) {
	p := requireRole(w, r, "administrator")
	if p == nil {
		return
	}
	var body struct {
		UserID string `json:"userId"`
		Active *bool  `json:"active"`
	}
	if !parseJSON(w, r, &body) {
		return
	}
	if body.Active == nil {
		writeErr(w, http.StatusBadRequest, "invalid_user", "active required")
		return
	}
	if _, err := h.PG.Exec(r.Context(), `UPDATE users SET active = $2 WHERE id = $1`, body.UserID, *body.Active); err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	auditAction(r.Context(), h.PG, p.User.ID, p.ActiveRole, "set_worker_availability", "user", body.UserID, true, map[string]interface{}{"active": *body.Active})
	data(w, http.StatusOK, map[string]interface{}{
		"userId": body.UserID,
		"active": *body.Active,
	})
}

