// POST /api/check-serviceability
func (h *CoreHandler) CheckServiceability(w http.ResponseWriter, r *http.Request) {
	p := auth.PrincipalOf(r)
	if p == nil {
		writeErr(w, http.StatusUnauthorized, "unauthorized", "not signed in")
		return
	}
	var body struct {
		Origin             map[string]float64 `json:"origin"`
		OriginType         string             `json:"originType"`
		OriginNodeID       string             `json:"originNodeId"`
		SampleTypeID       string             `json:"sampleTypeId"`
		RequestedAt        string             `json:"requestedAt"`
		DeliveryDeadline   string             `json:"deliveryDeadline"`
		EarliestCollection string             `json:"earliestCollectionAt"`
		LatestCollection   string             `json:"latestCollectionAt"`
	}
	if !parseJSON(w, r, &body) {
		return
	}
	if body.OriginType == "" {
		body.OriginType = "home"
	}
	lat, lng := body.Origin["latitude"], body.Origin["longitude"]

	snap := h.S.Snapshot()
	result := map[string]interface{}{
		"serviceable":      true,
		"snapshotVersion":  snap.Version,
		"reasons":          []string{},
		"sampleTypeId":     body.SampleTypeID,
		"originType":       body.OriginType,
		"earliestCollectionAt": body.EarliestCollection,
		"latestCollectionAt":   body.LatestCollection,
		"deliveryDeadline":     body.DeliveryDeadline,
	}
	reasons := []string{}

	// Check coverage if home
	if body.OriginType == "home" {
		_, ok := snap.HasCollectionCoverage(lat, lng)
		if !ok {
			reasons = append(reasons, "outside_collection_coverage")
		}
	}

	// Laboratory must accept the sample type
	lab, ok := snap.HasAcceptingLab(body.SampleTypeID)
	if !ok {
		reasons = append(reasons, "no_accepting_laboratory")
	} else {
		result["targetLaboratoryId"] = lab.LocationID
	}

	if len(reasons) > 0 {
		result["serviceable"] = false
	}
	result["reasons"] = reasons
	data(w, http.StatusOK, result)
}

// POST /api/read-serviceability-snapshot
func (h *CoreHandler) ReadServiceabilitySnapshot(w http.ResponseWriter, r *http.Request) {
	if auth.PrincipalOf(r) == nil {
		writeErr(w, http.StatusUnauthorized, "unauthorized", "not signed in")
		return
	}
	var body struct {
		SnapshotVersion *int `json:"snapshotVersion"`
	}
	_ = parseJSON(w, r, &body)
	snap := h.S.Snapshot()
	data(w, http.StatusOK, map[string]interface{}{
		"version":                snap.Version,
		"status":                 snap.Status,
		"computedAt":             snap.ComputedAt.UTC().Format(time.RFC3339Nano),
		"regions":                snap.Regions,
		"edges":                  snap.Edges,
		"laboratories":           snap.Laboratories,
		"activeCollectionPoints": snap.ActiveCollectionPoints,
	})
}

// GET /api/read-operations-state
func (h *CoreHandler) OperationsState(w http.ResponseWriter, r *http.Request) {
	if auth.PrincipalOf(r) == nil {
		writeErr(w, http.StatusUnauthorized, "unauthorized", "not signed in")
		return
	}
	ctx := r.Context()
	state := map[string]interface{}{}

	// open journeys
	rows, _ := h.PG.Query(ctx, `
        SELECT id::text, sample_id::text, status, plan_version, COALESCE(origin_node_id::text,''),
               COALESCE(target_node_id::text,''), COALESCE(target_laboratory_id::text,''),
               created_at, COALESCE(estimated_arrival, delivery_deadline)
        FROM journeys WHERE status NOT IN ('received','cancelled','expired')
        ORDER BY created_at DESC LIMIT 200
    `)
	journeys := []map[string]interface{}{}
	for rows != nil && rows.Next() {
		var id, sid, st, oN, tN, tl string
		var pv int
		var created, eta time.Time
		if err := rows.Scan(&id, &sid, &st, &pv, &oN, &tN, &tl, &created, &eta); err != nil {
			break
		}
		journeys = append(journeys, map[string]interface{}{
			"journeyId":          id,
			"sampleId":           sid,
			"status":             st,
			"planVersion":        pv,
			"originNodeId":       oN,
			"targetNodeId":       tN,
			"targetLaboratoryId": tl,
			"createdAt":          created.UTC().Format(time.RFC3339Nano),
			"estimatedArrival":   eta.UTC().Format(time.RFC3339Nano),
		})
	}
	if rows != nil {
		rows.Close()
	}
	state["journeys"] = journeys

	// assignments
	arows, _ := h.PG.Query(ctx, `
        SELECT a.id::text, a.sample_id::text, a.assignment_type, a.status, a.sequence,
               COALESCE(a.worker_id::text,''), COALESCE(a.node_id::text,''), COALESCE(a.laboratory_id::text,''),
               a.from_location_id::text, a.to_location_id::text,
               COALESCE(a.connection_id::text,''), a.planned_start, a.planned_end,
               COALESCE(a.actual_start, a.planned_start), COALESCE(a.actual_end, a.planned_end),
               a.cooled, a.batch_id::text
        FROM assignments a ORDER BY a.sequence LIMIT 500
    `)
	assignments := []map[string]interface{}{}
	for arows != nil && arows.Next() {
		var id, sid, atype, st, wID, nID, labID, from, to, conn, batchID string
		var seq int
		var plannedStart, plannedEnd, actualStart, actualEnd time.Time
		var cooled bool
		if err := arows.Scan(&id, &sid, &atype, &st, &seq, &wID, &nID, &labID, &from, &to, &conn, &plannedStart, &plannedEnd, &actualStart, &actualEnd, &cooled, &batchID); err != nil {
			break
		}
		assignments = append(assignments, map[string]interface{}{
			"assignmentId":   id,
			"sampleId":       sid,
			"assignmentType": atype,
			"status":         st,
			"sequence":       seq,
			"workerId":       wID,
			"nodeId":         nID,
			"laboratoryId":   labID,
			"fromLocationId": from,
			"toLocationId":   to,
			"connectionId":   conn,
			"plannedStart":   plannedStart.UTC().Format(time.RFC3339Nano),
			"plannedEnd":     plannedEnd.UTC().Format(time.RFC3339Nano),
			"actualStart":    actualStart.UTC().Format(time.RFC3339Nano),
			"actualEnd":      actualEnd.UTC().Format(time.RFC3339Nano),
			"cooled":         cooled,
			"batchId":        batchID,
		})
	}
	if arows != nil {
		arows.Close()
	}
	state["assignments"] = assignments

	// batches
	brows, _ := h.PG.Query(ctx, `
        SELECT b.id::text, b.connection_id::text, b.worker_id::text, b.status,
               b.planned_start, b.planned_end, b.cooled, b.handling_minutes,
               (SELECT array_agg(sample_id::text) FROM assignment_batches_samples WHERE batch_id = b.id) AS samples
        FROM assignment_batches b
    `)
	batches := []map[string]interface{}{}
	for brows != nil && brows.Next() {
		var id, conn, wID, st string
		var ps, pe time.Time
		var cooled bool
		var hand float64
		var samples interface{}
		if err := brows.Scan(&id, &conn, &wID, &st, &ps, &pe, &cooled, &hand, &samples); err != nil {
			break
		}
		batches = append(batches, map[string]interface{}{
			"batchId":         id,
			"connectionId":    conn,
			"workerId":        wID,
			"status":          st,
			"plannedStart":    ps.UTC().Format(time.RFC3339Nano),
			"plannedEnd":      pe.UTC().Format(time.RFC3339Nano),
			"cooled":          cooled,
			"handlingMinutes": hand,
			"samples":         samples,
		})
	}
	if brows != nil {
		brows.Close()
	}
	state["batches"] = batches

	// exceptions
	exRows, _ := h.PG.Query(ctx, `
        SELECT id::text, sample_id::text, reason, recorded_at, COALESCE(reported_by::text,''),
               COALESCE(notes,'')
        FROM sample_exceptions ORDER BY recorded_at DESC LIMIT 100
    `)
	excs := []map[string]interface{}{}
	for exRows != nil && exRows.Next() {
		var id, sid, reason, repID, notes string
		var recAt time.Time
		if err := exRows.Scan(&id, &sid, &reason, &recAt, &repID, &notes); err != nil {
			break
		}
		excs = append(excs, map[string]interface{}{
			"exceptionId": id,
			"sampleId":    sid,
			"reason":      reason,
			"recordedAt":  recAt.UTC().Format(time.RFC3339Nano),
			"reportedBy":  repID,
			"notes":       notes,
		})
	}
	if exRows != nil {
		exRows.Close()
	}
	state["exceptions"] = excs

	snap := h.S.Snapshot()
	state["serviceability"] = map[string]interface{}{
		"version":    snap.Version,
		"status":     snap.Status,
		"computedAt": snap.ComputedAt.UTC().Format(time.RFC3339Nano),
		"regions":    snap.Regions,
	}
	data(w, http.StatusOK, state)
}

var _ = pgx.ErrNoRows"}

