// POST /api/create-collection-request
func (h *CoreHandler) CreateCollectionRequest(w http.ResponseWriter, r *http.Request) {
	p := auth.PrincipalOf(r)
	if p == nil {
		writeErr(w, http.StatusUnauthorized, "unauthorized", "not signed in")
		return
	}
	if !p.HasRole("requester") && !p.HasRole("administrator") {
		writeErr(w, http.StatusForbidden, "forbidden", "role not permitted")
		return
	}
	var body struct {
		RequesterID            string             `json:"requesterId"`
		Origin                 map[string]float64 `json:"origin"`
		OriginType             string             `json:"originType"`
		OriginNodeID           string             `json:"originNodeId"`
		RequestedAt            string             `json:"requestedAt"`
		DeliveryDeadline       string             `json:"deliveryDeadline"`
		EarliestCollectionAt   string             `json:"earliestCollectionAt"`
		LatestCollectionAt     string             `json:"latestCollectionAt"`
		SampleTypeID           string             `json:"sampleTypeId"`
		ContainerType          string             `json:"containerType"`
		TemperatureMinC        *float64           `json:"temperatureMinC"`
		TemperatureMaxC        *float64           `json:"temperatureMaxC"`
		IncompatibleSampleType []string           `json:"incompatibleSampleTypes"`
		IdempotencyKey         string             `json:"idempotencyKey"`
	}
	if !parseJSON(w, r, &body) {
		return
	}
	if body.OriginType == "" {
		body.OriginType = "home"
	}
	requesterID := body.RequesterID
	if requesterID == "" {
		requesterID = p.User.ID
	}
	if !p.HasRole("administrator") && requesterID != p.User.ID {
		writeErr(w, http.StatusForbidden, "forbidden", "cannot create on behalf of another user")
		return
	}
	requestedAt, ok := util.ParseTime(body.RequestedAt)
	if !ok {
		writeErr(w, http.StatusBadRequest, "invalid_time", "requestedAt must be RFC3339")
		return
	}
	deadline, ok := util.ParseTime(body.DeliveryDeadline)
	if !ok {
		writeErr(w, http.StatusBadRequest, "invalid_deadline", "deliveryDeadline must be RFC3339")
		return
	}
	earliest := requestedAt
	if t, ok := util.ParseTime(body.EarliestCollectionAt); ok {
		earliest = t
	}
	latest := deadline.Add(-30 * time.Minute)
	if t, ok := util.ParseTime(body.LatestCollectionAt); ok {
		latest = t
	}

	tmin := 0.0
	tmax := 25.0
	if body.TemperatureMinC != nil {
		tmin = *body.TemperatureMinC
	}
	if body.TemperatureMaxC != nil {
		tmax = *body.TemperatureMaxC
	}

	// Validate serviceability against current snapshot
	snap := h.S.Snapshot()
	reasons := []string{}
	serviceable := true

	if body.OriginType == "home" {
		if _, ok := snap.HasCollectionCoverage(body.Origin["latitude"], body.Origin["longitude"]); !ok {
			reasons = append(reasons, "outside_collection_coverage")
			serviceable = false
		}
	}
	lab, ok := snap.HasAcceptingLab(body.SampleTypeID)
	if !ok {
		reasons = append(reasons, "no_accepting_laboratory")
		serviceable = false
	}

	if !serviceable {
		auditAction(r.Context(), h.PG, p.User.ID, p.ActiveRole, "create_collection_request", "collection_request", "", false, map[string]interface{}{"reasons": reasons})
		writeErr(w, http.StatusBadRequest, "invalid_node_coverage", "unserviceable: "+joinStrings(reasons, ","))
		return
	}

	ctx := r.Context()
	requestID := uuid.NewString()
	sampleID := uuid.NewString()
	journeyID := uuid.NewString()

	tx, err := h.PG.Begin(ctx)
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	defer tx.Rollback(ctx)

	if _, err := tx.Exec(ctx, `
        INSERT INTO collection_requests (id, requester_id, origin_latitude, origin_longitude, origin_type,
            origin_node_id, sample_type_id, container_type, temperature_min_c, temperature_max_c,
            incompatible_sample_types, earliest_collection_at, latest_collection_at,
            delivery_deadline, requested_at, status, idempotency_key)
        VALUES ($1,$2,$3,$4,$5,NULLIF($6,'')::uuid,$7,$8,$9,$10,$11,$12,$13,$14,$15,'open',$16)
    `, requestID, requesterID, body.Origin["latitude"], body.Origin["longitude"], body.OriginType,
		body.OriginNodeID, body.SampleTypeID, body.ContainerType, tmin, tmax,
		body.IncompatibleSampleType, earliest, latest, deadline, requestedAt, body.IdempotencyKey); err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	if _, err := tx.Exec(ctx, `
        INSERT INTO samples (id, request_id, requester_id, sample_type_id, origin_latitude, origin_longitude,
            origin_type, origin_node_id, container_type, temperature_min_c, temperature_max_c,
            incompatible_sample_type_ids, current_holder_id, status, requested_at, delivery_deadline,
            origin_state)
        VALUES ($1,$2,$3,$4,$5,$6,$7,NULLIF($8,'')::uuid,$9,$10,$11,$12,$13,'pending',$14,$15,$16)
    `, sampleID, requestID, requesterID, body.SampleTypeID, body.Origin["latitude"], body.Origin["longitude"],
		body.OriginType, body.OriginNodeID, body.ContainerType, tmin, tmax,
		body.IncompatibleSampleType, requesterID, requestedAt, deadline, "pre_seal"); err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	originNode := body.OriginNodeID
	if originNode == "" {
		originNode = pickNearestCollectionNode(h, ctx, tx, body.Origin["latitude"], body.Origin["longitude"])
	}
	if _, err := tx.Exec(ctx, `
        INSERT INTO journeys (id, sample_id, plan_version, status, origin_node_id, target_laboratory_id,
            target_node_id, delivery_deadline, estimated_arrival)
        VALUES ($1,$2,1,'active',NULLIF($3,'')::uuid,NULLIF($4,'')::uuid,$5,$6,$7)
    `, journeyID, sampleID, originNode, lab.LocationID, lab.LocationID, deadline, deadline); err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	if _, err := tx.Exec(ctx, `UPDATE samples SET active_journey_id = $2, target_laboratory_id = $3 WHERE id = $1`, sampleID, journeyID, lab.LocationID); err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	if err := tx.Commit(ctx); err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}

	h.publish(ctx, "request_created", "collection_request", requestID, map[string]interface{}{"sampleId": sampleID, "status": "open"})
	h.publish(ctx, "sample_created", "sample", sampleID, map[string]interface{}{"status": "pending", "journeyId": journeyID})
	auditAction(ctx, h.PG, p.User.ID, p.ActiveRole, "create_collection_request", "collection_request", requestID, true, map[string]interface{}{"sampleId": sampleID})

	data(w, http.StatusCreated, map[string]interface{}{
		"requestId":            requestID,
		"sampleId":             sampleID,
		"journeyId":            journeyID,
		"serviceability":       "serviceable",
		"targetLaboratoryId":   lab.LocationID,
		"originType":           body.OriginType,
		"earliestCollectionAt": earliest.UTC().Format(time.RFC3339Nano),
		"latestCollectionAt":   latest.UTC().Format(time.RFC3339Nano),
		"activeAssignmentIds":  []string{},
	})
}

// POST /api/ingest-presealed-sample
func (h *CoreHandler) IngestPresealedSample(w http.ResponseWriter, r *http.Request) {
	p := auth.PrincipalOf(r)
	if p == nil {
		writeErr(w, http.StatusUnauthorized, "unauthorized", "not signed in")
		return
	}
	if !p.HasAnyRole("administrator", "node_handler", "laboratory_team", "collection_professional", "delivery_partner") {
		writeErr(w, http.StatusForbidden, "forbidden", "role not permitted")
		return
	}
	var body struct {
		SampleTypeID           string             `json:"sampleTypeId"`
		OriginNodeID           string             `json:"originNodeId"`
		OriginType             string             `json:"originType"`
		ContainerType          string             `json:"containerType"`
		TemperatureMinC        *float64           `json:"temperatureMinC"`
		TemperatureMaxC        *float64           `json:"temperatureMaxC"`
		IncompatibleSampleType []string           `json:"incompatibleSampleTypes"`
		DeliveryDeadline       string             `json:"deliveryDeadline"`
		TargetLaboratoryID     string             `json:"targetLaboratoryId"`
		IdempotencyKey         string             `json:"idempotencyKey"`
	}
	if !parseJSON(w, r, &body) {
		return
	}
	if body.OriginType == "" {
		body.OriginType = "node"
	}
	if body.OriginType == "home" {
		writeErr(w, http.StatusBadRequest, "invalid_origin_type", "home origin not allowed for presealed ingestion")
		return
	}
	deadline, ok := util.ParseTime(body.DeliveryDeadline)
	if !ok {
		writeErr(w, http.StatusBadRequest, "invalid_deadline", "deliveryDeadline required")
		return
	}
	tmin := 0.0
	tmax := 25.0
	if body.TemperatureMinC != nil {
		tmin = *body.TemperatureMinC
	}
	if body.TemperatureMaxC != nil {
		tmax = *body.TemperatureMaxC
	}

	snap := h.S.Snapshot()
	lab, ok := snap.HasAcceptingLab(body.SampleTypeID)
	if !ok || (body.TargetLaboratoryID != "" && lab.LocationID != body.TargetLaboratoryID) {
		writeErr(w, http.StatusBadRequest, "no_accepting_laboratory", "no accepting laboratory")
		return
	}

	ctx := r.Context()
	sampleID := uuid.NewString()
	journeyID := uuid.NewString()
	tx, err := h.PG.Begin(ctx)
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	defer tx.Rollback(ctx)

	if _, err := tx.Exec(ctx, `
        INSERT INTO samples (id, request_id, requester_id, sample_type_id, origin_latitude, origin_longitude,
            origin_type, origin_node_id, container_type, temperature_min_c, temperature_max_c,
            incompatible_sample_type_ids, current_holder_id, status, requested_at, delivery_deadline,
            origin_state, sealed_at)
        VALUES ($1,NULL,$2,$3,0,0,$4,NULLIF($5,'')::uuid,$6,$7,$8,$9,$10,'sealed',$11,$12,'sealed',$11)
    `, sampleID, p.User.ID, body.SampleTypeID, body.OriginType, body.OriginNodeID, body.ContainerType, tmin, tmax,
		body.IncompatibleSampleType, p.User.ID, time.Now().UTC(), deadline); err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	if _, err := tx.Exec(ctx, `
        INSERT INTO journeys (id, sample_id, plan_version, status, origin_node_id, target_laboratory_id,
            target_node_id, delivery_deadline, estimated_arrival)
        VALUES ($1,$2,1,'active',NULLIF($3,'')::uuid,NULLIF($4,'')::uuid,$4,$5,$5)
    `, journeyID, sampleID, body.OriginNodeID, lab.LocationID, deadline); err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	if _, err := tx.Exec(ctx, `UPDATE samples SET active_journey_id = $2, target_laboratory_id = $3 WHERE id = $1`, sampleID, journeyID, lab.LocationID); err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	if err := tx.Commit(ctx); err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	h.publish(ctx, "sample_ingested", "sample", sampleID, map[string]interface{}{"status": "sealed", "journeyId": journeyID})
	auditAction(ctx, h.PG, p.User.ID, p.ActiveRole, "ingest_presealed_sample", "sample", sampleID, true, nil)
	data(w, http.StatusCreated, map[string]interface{}{
		"sampleId":           sampleID,
		"journeyId":          journeyID,
		"currentHolderId":    p.User.ID,
		"status":             "sealed",
		"targetLaboratoryId": lab.LocationID,
	})
}

// GET /api/read-sample-state/{sampleId}
func (h *CoreHandler) ReadSampleState(w http.ResponseWriter, r *http.Request) {
	p := auth.PrincipalOf(r)
	if p == nil {
		writeErr(w, http.StatusUnauthorized, "unauthorized", "not signed in")
		return
	}
	sampleID := r.PathValue("sampleId")
	if sampleID == "" {
		writeErr(w, http.StatusBadRequest, "invalid_sample", "sampleId required")
		return
	}
	row := h.PG.QueryRow(r.Context(), `
        SELECT s.id::text, s.request_id::text, s.requester_id::text, s.sample_type_id::text,
               s.origin_latitude, s.origin_longitude, s.origin_type,
               COALESCE(s.container_type,''), COALESCE(s.temperature_min_c,0), COALESCE(s.temperature_max_c,0),
               COALESCE(s.incompatible_sample_type_ids::text[],'{}'::text[]),
               COALESCE(s.active_journey_id::text,''), COALESCE(s.target_laboratory_id::text,''),
               s.status, COALESCE(s.current_holder_id::text,''),
               s.latest_latitude, s.latest_longitude, s.location_recorded_at,
               s.requested_at, s.delivery_deadline,
               COALESCE(se.id::text,''), COALESCE(se.reason,'')
        FROM samples s
        LEFT JOIN sample_exceptions se ON se.sample_id = s.id
        WHERE s.id = $1
    `, sampleID)
	var (
		id, reqID, requesterID, stID, oType, container, ajID, tlID, status, holder string
		olat, olng, tmin, tmax float64
		incompat []string
		llat, llng *float64
		locAt *time.Time
		reqAt, deadline time.Time
		exID, exReason string
	)
	if err := row.Scan(&id, &reqID, &requesterID, &stID, &olat, &olng, &oType, &container, &tmin, &tmax, &incompat, &ajID, &tlID, &status, &holder, &llat, &llng, &locAt, &reqAt, &deadline, &exID, &exReason); err != nil {
		if err == pgx.ErrNoRows {
			writeErr(w, http.StatusNotFound, "not_found", "sample not found")
			return
		}
		writeErr(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	state := map[string]interface{}{"status": status}
	if exID != "" {
		state["exception"] = map[string]interface{}{"id": exID, "reason": exReason}
	}
	var latestLoc interface{}
	if llat != nil && llng != nil {
		latestLoc = coordMap(*llat, *llng)
	}
	var locAtStr interface{}
	if locAt != nil {
		locAtStr = locAt.UTC().Format(time.RFC3339Nano)
	}
	stale := locAt == nil || time.Since(*locAt) > 10*time.Minute

	// permissions: requester can only see their own; admins/dispatchers see all.
	if p.HasRole("requester") && !p.HasRole("administrator") && requesterID != p.User.ID {
		writeErr(w, http.StatusForbidden, "forbidden", "sample not visible")
		return
	}

	// fetch assignments
	aRows, _ := h.PG.Query(r.Context(), `
        SELECT a.id::text, a.sequence, a.status, a.assignment_type, COALESCE(a.worker_id::text,''),
               a.from_location_id::text, a.to_location_id::text, a.planned_start, a.planned_end, a.cooled
        FROM assignments a WHERE a.sample_id = $1 ORDER BY a.sequence
    `, sampleID)
	assignments := []map[string]interface{}{}
	for aRows != nil && aRows.Next() {
		var aid, st, atype, wID, from, to string
		var seq int
		var ps, pe time.Time
		var cooled bool
		if err := aRows.Scan(&aid, &seq, &st, &atype, &wID, &from, &to, &ps, &pe, &cooled); err != nil {
			break
		}
		assignments = append(assignments, map[string]interface{}{
			"assignmentId":   aid,
			"sequence":       seq,
			"status":         st,
			"assignmentType": atype,
			"workerId":       wID,
			"fromLocationId": from,
			"toLocationId":   to,
			"plannedStart":   ps.UTC().Format(time.RFC3339Nano),
			"plannedEnd":     pe.UTC().Format(time.RFC3339Nano),
			"cooled":         cooled,
		})
	}
	if aRows != nil {
		aRows.Close()
	}

	// fetch timeline
	tRows, _ := h.PG.Query(r.Context(), `
        SELECT id::text, event_type, description, recorded_at, COALESCE(actor_id::text,'')
        FROM sample_timeline WHERE sample_id = $1 ORDER BY recorded_at
    `, sampleID)
	timeline := []map[string]interface{}{}
	for tRows != nil && tRows.Next() {
		var tid, et, desc, actor string
		var recAt time.Time
		if err := tRows.Scan(&tid, &et, &desc, &recAt, &actor); err != nil {
			break
		}
		timeline = append(timeline, map[string]interface{}{
			"id":          tid,
			"eventType":   et,
			"description": desc,
			"recordedAt":  recAt.UTC().Format(time.RFC3339Nano),
			"actorId":     actor,
		})
	}
	if tRows != nil {
		tRows.Close()
	}

	data(w, http.StatusOK, map[string]interface{}{
		"sampleId":           id,
		"requestId":          reqID,
		"requesterId":        requesterID,
		"sampleTypeId":       stID,
		"origin":             coordMap(olat, olng),
		"originType":         oType,
		"containerType":      container,
		"temperatureMinC":    tmin,
		"temperatureMaxC":    tmax,
		"incompatibleSampleTypeIds": incompat,
		"activeJourneyId":    ajID,
		"targetLaboratoryId": tlID,
		"currentHolderId":    holder,
		"latestLocation":     latestLoc,
		"locationRecordedAt": locAtStr,
		"locationStale":      stale,
		"requestedAt":        reqAt.UTC().Format(time.RFC3339Nano),
		"deliveryDeadline":   deadline.UTC().Format(time.RFC3339Nano),
		"state":              state,
		"assignments":        assignments,
		"timeline":           timeline,
	})
}

// POST /api/read-sample-lifecycle
func (h *CoreHandler) ReadSampleLifecycle(w http.ResponseWriter, r *http.Request) {
	p := auth.PrincipalOf(r)
	if p == nil {
		writeErr(w, http.StatusUnauthorized, "unauthorized", "not signed in")
		return
	}
	var body struct {
		SampleID string `json:"sampleId"`
	}
	if !parseJSON(w, r, &body) {
		return
	}
	tRows, _ := h.PG.Query(r.Context(), `
        SELECT id::text, event_type, description, recorded_at, COALESCE(actor_id::text,''),
               COALESCE(metadata::text,'{}')
        FROM sample_timeline WHERE sample_id = $1 ORDER BY recorded_at
    `, body.SampleID)
	out := []map[string]interface{}{}
	for tRows != nil && tRows.Next() {
		var tid, et, desc, actor, meta string
		var recAt time.Time
		if err := tRows.Scan(&tid, &et, &desc, &recAt, &actor, &meta); err != nil {
			break
		}
		md := map[string]interface{}{}
		_ = safeJSONUnmarshal([]byte(meta), &md)
		out = append(out, map[string]interface{}{
			"id":          tid,
			"eventType":   et,
			"description": desc,
			"recordedAt":  recAt.UTC().Format(time.RFC3339Nano),
			"actorId":     actor,
			"metadata":    md,
		})
	}
	if tRows != nil {
		tRows.Close()
	}
	data(w, http.StatusOK, map[string]interface{}{
		"sampleId": body.SampleID,
		"events":   out,
	})
}

// POST /api/read-journey-plan
func (h *CoreHandler) ReadJourneyPlan(w http.ResponseWriter, r *http.Request) {
	p := auth.PrincipalOf(r)
	if p == nil {
		writeErr(w, http.StatusUnauthorized, "unauthorized", "not signed in")
		return
	}
	var body struct {
		JourneyID string `json:"journeyId"`
	}
	if !parseJSON(w, r, &body) {
		return
	}
	row := h.PG.QueryRow(r.Context(), `
        SELECT id::text, sample_id::text, plan_version, status,
               COALESCE(origin_node_id::text,''), COALESCE(target_laboratory_id::text,''),
               COALESCE(target_node_id::text,''), delivery_deadline, COALESCE(estimated_arrival, delivery_deadline),
               created_at
        FROM journeys WHERE id = $1
    `, body.JourneyID)
	var id, sid, st, oN, tl, tN string
	var pv int
	var deadline, eta, created time.Time
	if err := row.Scan(&id, &sid, &pv, &st, &oN, &tl, &tN, &deadline, &eta, &created); err != nil {
		if err == pgx.ErrNoRows {
			writeErr(w, http.StatusNotFound, "not_found", "journey not found")
			return
		}
		writeErr(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	aRows, _ := h.PG.Query(r.Context(), `
        SELECT id::text, sequence, status, assignment_type, COALESCE(worker_id::text,''),
               COALESCE(node_id::text,''), COALESCE(laboratory_id::text,''),
               from_location_id::text, to_location_id::text, COALESCE(connection_id::text,''),
               planned_start, planned_end, cooled, COALESCE(batch_id::text,'')
        FROM assignments WHERE journey_id = $1 ORDER BY sequence
    `, body.JourneyID)
	assignments := []map[string]interface{}{}
	for aRows != nil && aRows.Next() {
		var aid, st, atype, wID, nID, labID, from, to, conn, batchID string
		var seq int
		var ps, pe time.Time
		var cooled bool
		if err := aRows.Scan(&aid, &seq, &st, &atype, &wID, &nID, &labID, &from, &to, &conn, &ps, &pe, &cooled, &batchID); err != nil {
			break
		}
		assignments = append(assignments, map[string]interface{}{
			"assignmentId":   aid,
			"sequence":       seq,
			"status":         st,
			"assignmentType": atype,
			"workerId":       wID,
			"nodeId":         nID,
			"laboratoryId":   labID,
			"fromLocationId": from,
			"toLocationId":   to,
			"connectionId":   conn,
			"plannedStart":   ps.UTC().Format(time.RFC3339Nano),
			"plannedEnd":     pe.UTC().Format(time.RFC3339Nano),
			"cooled":         cooled,
			"batchId":        batchID,
		})
	}
	if aRows != nil {
		aRows.Close()
	}
	sRows, _ := h.PG.Query(r.Context(), `
        SELECT id::text, sequence, stop_type, location_id::text, planned_arrival, planned_departure,
               COALESCE(actual_arrival, planned_arrival), COALESCE(actual_departure, planned_departure)
        FROM journey_stops WHERE journey_id = $1 ORDER BY sequence
    `, body.JourneyID)
	stops := []map[string]interface{}{}
	for sRows != nil && sRows.Next() {
		var sid, stype, loc string
		var seq int
		var pa, pd, aa, ad time.Time
		if err := sRows.Scan(&sid, &seq, &stype, &loc, &pa, &pd, &aa, &ad); err != nil {
			break
		}
		stops = append(stops, map[string]interface{}{
			"stopId":           sid,
			"sequence":         seq,
			"stopType":         stype,
			"locationId":       loc,
			"plannedArrival":   pa.UTC().Format(time.RFC3339Nano),
			"plannedDeparture": pd.UTC().Format(time.RFC3339Nano),
			"actualArrival":    aa.UTC().Format(time.RFC3339Nano),
			"actualDeparture":  ad.UTC().Format(time.RFC3339Nano),
		})
	}
	if sRows != nil {
		sRows.Close()
	}
	data(w, http.StatusOK, map[string]interface{}{
		"journeyId":          id,
		"sampleId":           sid,
		"planVersion":        pv,
		"status":             st,
		"originNodeId":       oN,
		"targetLaboratoryId": tl,
		"targetNodeId":       tN,
		"deliveryDeadline":   deadline.UTC().Format(time.RFC3339Nano),
		"estimatedArrival":   eta.UTC().Format(time.RFC3339Nano),
		"createdAt":          created.UTC().Format(time.RFC3339Nano),
		"assignments":        assignments,
		"stops":              stops,
	})
}

// POST /api/list-role-work
func (h *CoreHandler) ListRoleWork(w http.ResponseWriter, r *http.Request) {
	p := auth.PrincipalOf(r)
	if p == nil {
		writeErr(w, http.StatusUnauthorized, "unauthorized", "not signed in")
		return
	}
	var body struct {
		Role   string `json:"role"`
		Status string `json:"status"`
	}
	if !parseJSON(w, r, &body) {
		return
	}
	role := util.NormalizeRole(body.Role)
	if role == "" {
		role = p.ActiveRole
	}
	if !util.RolesContain(p.User.Roles, role) {
		writeErr(w, http.StatusForbidden, "role_not_held", "role not held")
		return
	}
	if body.Status == "" {
		body.Status = "active"
	}
	ctx := r.Context()
	result := map[string]interface{}{
		"role":              role,
		"status":            body.Status,
		"currentWork":       []map[string]interface{}{},
		"completedWork":     []map[string]interface{}{},
		"timelines":         map[string][]map[string]interface{}{},
		"collectionRequests": []map[string]interface{}{},
	}

	// collection requests if requester
	if role == "requester" {
		rrows, _ := h.PG.Query(ctx, `
            SELECT cr.id::text, cr.requester_id::text, cr.sample_type_id::text,
                   cr.origin_latitude, cr.origin_longitude, cr.origin_type,
                   COALESCE(cr.origin_node_id::text,''),
                   cr.earliest_collection_at, cr.latest_collection_at, cr.delivery_deadline,
                   cr.status, cr.requested_at
            FROM collection_requests cr WHERE cr.requester_id = $1 ORDER BY cr.requested_at DESC LIMIT 200
        `, p.User.ID)
		reqs := []map[string]interface{}{}
		for rrows != nil && rrows.Next() {
			var id, reqID, stID, oType, oNode, st string
			var olat, olng float64
			var earliest, latest, deadline, requested time.Time
			if err := rrows.Scan(&id, &reqID, &stID, &olat, &olng, &oType, &oNode, &earliest, &latest, &deadline, &st, &requested); err != nil {
				break
			}
			reqs = append(reqs, map[string]interface{}{
				"requestId":            id,
				"requesterId":          reqID,
				"sampleTypeId":         stID,
				"origin":               coordMap(olat, olng),
				"originType":           oType,
				"originNodeId":         oNode,
				"earliestCollectionAt": earliest.UTC().Format(time.RFC3339Nano),
				"latestCollectionAt":   latest.UTC().Format(time.RFC3339Nano),
				"deliveryDeadline":     deadline.UTC().Format(time.RFC3339Nano),
				"requestedAt":          requested.UTC().Format(time.RFC3339Nano),
				"status":               st,
			})
		}
		if rrows != nil {
			rrows.Close()
		}
		result["collectionRequests"] = reqs
	}

	// assignments
	var statusList []string
	if body.Status == "completed" {
		statusList = []string{"completed"}
	} else if body.Status == "all" {
		statusList = []string{"offered", "accepted", "in_progress", "completed", "declined", "cancelled"}
	} else {
		statusList = []string{"offered", "accepted", "in_progress"}
	}

	// build role filter
	var rows pgx.Rows
	switch role {
	case "collection_professional":
		rows, _ = h.PG.Query(ctx, `
            SELECT a.id::text, a.sequence, a.status, a.assignment_type, a.sample_id::text,
                   COALESCE(a.worker_id::text,''), a.from_location_id::text, a.to_location_id::text,
                   COALESCE(a.node_id::text,''), COALESCE(a.laboratory_id::text,''),
                   a.planned_start, a.planned_end, a.cooled, COALESCE(a.batch_id::text,''),
                   s.request_id::text, s.target_laboratory_id::text
            FROM assignments a
            JOIN samples s ON s.id = a.sample_id
            WHERE a.assignment_type = 'collection' AND a.status = ANY($2::text[])
            ORDER BY a.planned_start DESC LIMIT 200
        `, statusList)
	case "delivery_partner":
		rows, _ = h.PG.Query(ctx, `
            SELECT a.id::text, a.sequence, a.status, a.assignment_type, a.sample_id::text,
                   COALESCE(a.worker_id::text,''), a.from_location_id::text, a.to_location_id::text,
                   COALESCE(a.node_id::text,''), COALESCE(a.laboratory_id::text,''),
                   a.planned_start, a.planned_end, a.cooled, COALESCE(a.batch_id::text,''),
                   s.request_id::text, s.target_laboratory_id::text
            FROM assignments a
            JOIN samples s ON s.id = a.sample_id
            WHERE a.assignment_type = 'transport' AND a.status = ANY($2::text[])
            ORDER BY a.planned_start DESC LIMIT 200
        `, statusList)
	case "node_handler":
		rows, _ = h.PG.Query(ctx, `
            SELECT a.id::text, a.sequence, a.status, a.assignment_type, a.sample_id::text,
                   COALESCE(a.worker_id::text,''), a.from_location_id::text, a.to_location_id::text,
                   COALESCE(a.node_id::text,''), COALESCE(a.laboratory_id::text,''),
                   a.planned_start, a.planned_end, a.cooled, COALESCE(a.batch_id::text,''),
                   s.request_id::text, s.target_laboratory_id::text
            FROM assignments a
            JOIN samples s ON s.id = a.sample_id
            WHERE a.assignment_type IN ('node_arrival','node_departure') AND a.status = ANY($2::text[])
            ORDER BY a.planned_start DESC LIMIT 200
        `, statusList)
	case "laboratory_team":
		rows, _ = h.PG.Query(ctx, `
            SELECT a.id::text, a.sequence, a.status, a.assignment_type, a.sample_id::text,
                   COALESCE(a.worker_id::text,''), a.from_location_id::text, a.to_location_id::text,
                   COALESCE(a.node_id::text,''), COALESCE(a.laboratory_id::text,''),
                   a.planned_start, a.planned_end, a.cooled, COALESCE(a.batch_id::text,''),
                   s.request_id::text, s.target_laboratory_id::text
            FROM assignments a
            JOIN samples s ON s.id = a.sample_id
            WHERE a.assignment_type = 'laboratory_intake' AND a.status = ANY($2::text[])
            ORDER BY a.planned_start DESC LIMIT 200
        `, statusList)
	case "administrator", "dispatcher":
		rows, _ = h.PG.Query(ctx, `
            SELECT a.id::text, a.sequence, a.status, a.assignment_type, a.sample_id::text,
                   COALESCE(a.worker_id::text,''), a.from_location_id::text, a.to_location_id::text,
                   COALESCE(a.node_id::text,''), COALESCE(a.laboratory_id::text,''),
                   a.planned_start, a.planned_end, a.cooled, COALESCE(a.batch_id::text,''),
                   s.request_id::text, s.target_laboratory_id::text
            FROM assignments a
            JOIN samples s ON s.id = a.sample_id
            WHERE a.status = ANY($2::text[])
            ORDER BY a.planned_start DESC LIMIT 200
        `, statusList)
	default:
		writeErr(w, http.StatusBadRequest, "invalid_role", "unsupported role")
		return
	}

	// We can't pass statusList as $2 with $1 not referenced; rewrite:
	// (the SQL above references $2; but we never bind $1). pgx doesn't care
	// about that, so bind only what we used.
	_ = p.User.ID

	// Restate query with proper bindings (avoid pgx $N mismatch):
	rows.Close()
	var arRows pgx.Rows
	switch role {
	case "collection_professional":
		arRows, _ = h.PG.Query(ctx, `
            SELECT a.id::text, a.sequence, a.status, a.assignment_type, a.sample_id::text,
                   COALESCE(a.worker_id::text,''), a.from_location_id::text, a.to_location_id::text,
                   COALESCE(a.node_id::text,''), COALESCE(a.laboratory_id::text,''),
                   a.planned_start, a.planned_end, a.cooled, COALESCE(a.batch_id::text,''),
                   s.request_id::text, s.target_laboratory_id::text
            FROM assignments a
            JOIN samples s ON s.id = a.sample_id
            WHERE a.assignment_type = 'collection' AND a.status = ANY($1::text[])
            ORDER BY a.planned_start DESC LIMIT 200
        `, statusList)
	case "delivery_partner":
		arRows, _ = h.PG.Query(ctx, `
            SELECT a.id::text, a.sequence, a.status, a.assignment_type, a.sample_id::text,
                   COALESCE(a.worker_id::text,''), a.from_location_id::text, a.to_location_id::text,
                   COALESCE(a.node_id::text,''), COALESCE(a.laboratory_id::text,''),
                   a.planned_start, a.planned_end, a.cooled, COALESCE(a.batch_id::text,''),
                   s.request_id::text, s.target_laboratory_id::text
            FROM assignments a
            JOIN samples s ON s.id = a.sample_id
            WHERE a.assignment_type = 'transport' AND a.status = ANY($1::text[])
            ORDER BY a.planned_start DESC LIMIT 200
        `, statusList)
	case "node_handler":
		arRows, _ = h.PG.Query(ctx, `
            SELECT a.id::text, a.sequence, a.status, a.assignment_type, a.sample_id::text,
                   COALESCE(a.worker_id::text,''), a.from_location_id::text, a.to_location_id::text,
                   COALESCE(a.node_id::text,''), COALESCE(a.laboratory_id::text,''),
                   a.planned_start, a.planned_end, a.cooled, COALESCE(a.batch_id::text,''),
                   s.request_id::text, s.target_laboratory_id::text
            FROM assignments a
            JOIN samples s ON s.id = a.sample_id
            WHERE a.assignment_type IN ('node_arrival','node_departure') AND a.status = ANY($1::text[])
            ORDER BY a.planned_start DESC LIMIT 200
        `, statusList)
	case "laboratory_team":
		arRows, _ = h.PG.Query(ctx, `
            SELECT a.id::text, a.sequence, a.status, a.assignment_type, a.sample_id::text,
                   COALESCE(a.worker_id::text,''), a.from_location_id::text, a.to_location_id::text,
                   COALESCE(a.node_id::text,''), COALESCE(a.laboratory_id::text,''),
                   a.planned_start, a.planned_end, a.cooled, COALESCE(a.batch_id::text,''),
                   s.request_id::text, s.target_laboratory_id::text
            FROM assignments a
            JOIN samples s ON s.id = a.sample_id
            WHERE a.assignment_type = 'laboratory_intake' AND a.status = ANY($1::text[])
            ORDER BY a.planned_start DESC LIMIT 200
        `, statusList)
	default:
		arRows, _ = h.PG.Query(ctx, `
            SELECT a.id::text, a.sequence, a.status, a.assignment_type, a.sample_id::text,
                   COALESCE(a.worker_id::text,''), a.from_location_id::text, a.to_location_id::text,
                   COALESCE(a.node_id::text,''), COALESCE(a.laboratory_id::text,''),
                   a.planned_start, a.planned_end, a.cooled, COALESCE(a.batch_id::text,''),
                   s.request_id::text, s.target_laboratory_id::text
            FROM assignments a
            JOIN samples s ON s.id = a.sample_id
            WHERE a.status = ANY($1::text[])
            ORDER BY a.planned_start DESC LIMIT 200
        `, statusList)
	}

	current := []map[string]interface{}{}
	completed := []map[string]interface{}{}
	timelines := map[string][]map[string]interface{}{}
	for arRows != nil && arRows.Next() {
		var id, st, atype, sid, wID, from, to, nID, labID, batchID, reqID, tlab string
		var seq int
		var ps, pe time.Time
		var cooled bool
		if err := arRows.Scan(&id, &seq, &st, &atype, &sid, &wID, &from, &to, &nID, &labID, &ps, &pe, &cooled, &batchID, &reqID, &tlab); err != nil {
			break
		}
		rec := map[string]interface{}{
			"assignmentId":       id,
			"sequence":           seq,
			"status":             st,
			"assignmentType":     atype,
			"sampleId":           sid,
			"workerId":           wID,
			"fromLocationId":     from,
			"toLocationId":       to,
			"nodeId":             nID,
			"laboratoryId":       labID,
			"plannedStart":       ps.UTC().Format(time.RFC3339Nano),
			"plannedEnd":         pe.UTC().Format(time.RFC3339Nano),
			"cooled":             cooled,
			"batchId":            batchID,
			"requestId":          reqID,
			"targetLaboratoryId": tlab,
		}
		if st == "completed" {
			completed = append(completed, rec)
		} else {
			current = append(current, rec)
		}
		// timeline
		tRows, _ := h.PG.Query(ctx, `
            SELECT id::text, event_type, description, recorded_at, COALESCE(actor_id::text,'')
            FROM sample_timeline WHERE sample_id = $1 ORDER BY recorded_at
        `, sid)
		tl := []map[string]interface{}{}
		for tRows != nil && tRows.Next() {
			var tid, et, desc, actor string
			var recAt time.Time
			if err := tRows.Scan(&tid, &et, &desc, &recAt, &actor); err != nil {
				break
			}
			tl = append(tl, map[string]interface{}{
				"id":          tid,
				"eventType":   et,
				"description": desc,
				"recordedAt":  recAt.UTC().Format(time.RFC3339Nano),
				"actorId":     actor,
			})
		}
		if tRows != nil {
			tRows.Close()
		}
		timelines[sid] = tl
	}
	if arRows != nil {
		arRows.Close()
	}
	result["currentWork"] = current
	result["completedWork"] = completed
	result["timelines"] = timelines
	data(w, http.StatusOK, result)
}

// pickNearestCollectionNode finds the nearest active collection node to a point.
func pickNearestCollectionNode(h *CoreHandler, ctx context.Context, tx pgx.Tx, lat, lng float64) string {
	rows, err := tx.Query(ctx, `
        SELECT id::text, latitude, longitude
        FROM locations WHERE active AND (functions->>'collection_point')::boolean = TRUE
    `)
	if err != nil {
		return ""
	}
	defer rows.Close()
	var bestID string
	var bestDist float64 = -1
	for rows.Next() {
		var id string
		var nlat, nlng float64
		if err := rows.Scan(&id, &nlat, &nlng); err != nil {
			continue
		}
		d := util.HaversineKm(lat, lng, nlat, nlng)
		if bestDist < 0 || d < bestDist {
			bestDist = d
			bestID = id
		}
	}
	return bestID
}

// joinStrings joins strings with sep.
func joinStrings(parts []string, sep string) string {
	out := ""
	for i, s := range parts {
		if i > 0 {
			out += sep
		}
		out += s
	}
	return out
}"}

