// POST /api/collect-and-seal-sample
func (h *CoreHandler) CollectAndSealSample(w http.ResponseWriter, r *http.Request) {
	p := auth.PrincipalOf(r)
	if p == nil {
		writeErr(w, http.StatusUnauthorized, "unauthorized", "not signed in")
		return
	}
	if !p.HasRole("collection_professional") && !p.HasRole("administrator") {
		writeErr(w, http.StatusForbidden, "forbidden", "role not permitted")
		return
	}
	var body struct {
		RequestID     string `json:"requestId"`
		SampleTypeID  string `json:"sampleTypeId"`
		ContainerType string `json:"containerType"`
		TemperatureC  *float64 `json:"temperatureC"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if !parseJSON(w, r, &body) {
		return
	}
	// Find sample by request
	row := h.PG.QueryRow(r.Context(), `
        SELECT s.id::text, s.sample_type_id::text, s.status, COALESCE(s.active_journey_id::text,'')
        FROM samples s WHERE s.request_id = $1
    `, body.RequestID)
	var sid, stID, status, ajID string
	if err := row.Scan(&sid, &stID, &status, &ajID); err != nil {
		if err == pgx.ErrNoRows {
			writeErr(w, http.StatusNotFound, "not_found", "request not found")
			return
		}
		writeErr(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	// Certification check
	certMap := map[string]bool{}
	for _, c := range p.User.Certifications {
		certMap[c.Code] = c.Active
	}
	var required string
	_ = h.PG.QueryRow(r.Context(), `SELECT code FROM sample_types WHERE id = $1`, stID).Scan(&required)
	if !certMap[required] && !p.HasRole("administrator") {
		writeErr(w, http.StatusForbidden, "invalid_certification", "missing required certification "+required)
		return
	}
	now := time.Now().UTC()
	if _, err := h.PG.Exec(r.Context(), `
        UPDATE samples SET status = 'sealed', origin_state = 'sealed', sealed_at = $2, current_holder_id = $3 WHERE id = $1
    `, sid, now, p.User.ID); err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	if _, err := h.PG.Exec(r.Context(), `
        INSERT INTO sample_timeline (id, sample_id, event_type, description, recorded_at, actor_id, metadata)
        VALUES ($1,$2,'sample_sealed',$3,$4,$5,$6)
    `, uuid.NewString(), sid, "Sample collected and sealed", now, p.User.ID, `{"containerType":"`+body.ContainerType+`"}`); err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	h.publish(r.Context(), "sample_sealed", "sample", sid, map[string]interface{}{"holderId": p.User.ID, "sealedAt": now})
	auditAction(r.Context(), h.PG, p.User.ID, p.ActiveRole, "collect_and_seal", "sample", sid, true, nil)
	// Compliance check
	var tmin, tmax float64
	_ = h.PG.QueryRow(r.Context(), `SELECT COALESCE(temperature_min_c,0), COALESCE(temperature_max_c,0) FROM samples WHERE id = $1`, sid).Scan(&tmin, &tmax)
	compliant := true
	if body.TemperatureC != nil {
		if *body.TemperatureC < tmin || *body.TemperatureC > tmax {
			compliant = false
			if _, err := h.PG.Exec(r.Context(), `UPDATE samples SET status = 'exception' WHERE id = $1`, sid); err != nil {
				writeErr(w, http.StatusInternalServerError, "internal_error", err.Error())
				return
			}
		}
	}
	data(w, http.StatusOK, map[string]interface{}{
		"sampleId":          sid,
		"status":            "sealed",
		"currentHolderId":   p.User.ID,
		"sealedAt":          now.Format(time.RFC3339Nano),
		"handlingCompliant": compliant,
	})
}

// POST /api/initiate-handoff
func (h *CoreHandler) InitiateHandoff(w http.ResponseWriter, r *http.Request) {
	p := auth.PrincipalOf(r)
	if p == nil {
		writeErr(w, http.StatusUnauthorized, "unauthorized", "not signed in")
		return
	}
	var body struct {
		AssignmentID string `json:"assignmentId"`
		ReceiverID   string `json:"receiverId"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if !parseJSON(w, r, &body) {
		return
	}
	ctx := r.Context()
	row := h.PG.QueryRow(ctx, `
        SELECT a.id::text, a.sample_id::text, a.status, COALESCE(a.worker_id::text,''),
               a.from_location_id::text, a.to_location_id::text, s.current_holder_id::text, s.status
        FROM assignments a JOIN samples s ON s.id = a.sample_id WHERE a.id = $1
    `, body.AssignmentID)
	var id, sid, st, wID, from, to, holder, sst string
	if err := row.Scan(&id, &sid, &st, &wID, &from, &to, &holder, &sst); err != nil {
		if err == pgx.ErrNoRows {
			writeErr(w, http.StatusNotFound, "not_found", "assignment not found")
			return
		}
		writeErr(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	if holder != p.User.ID {
		writeErr(w, http.StatusConflict, "not_current_holder", "you do not currently hold the sample")
		return
	}
	if st != "accepted" && st != "in_progress" {
		writeErr(w, http.StatusConflict, "invalid_assignment_state", "assignment not active")
		return
	}
	// Look up if there's already a pending handoff
	var existing string
	_ = h.PG.QueryRow(ctx, `SELECT id::text FROM handoffs WHERE assignment_id = $1 AND status IN ('initiated','sender_confirmed','receiver_confirmed')`, body.AssignmentID).Scan(&existing)
	if existing != "" {
		writeErr(w, http.StatusConflict, "pending_handoff_exists", "handoff already initiated")
		return
	}
	hid := uuid.NewString()
	now := time.Now().UTC()
	if _, err := h.PG.Exec(ctx, `
        INSERT INTO handoffs (id, assignment_id, sample_id, sender_id, receiver_id, status, initiated_at)
        VALUES ($1,$2,$3,$4,$5,'initiated',$6)
    `, hid, body.AssignmentID, sid, p.User.ID, body.ReceiverID, now); err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	if _, err := h.PG.Exec(ctx, `UPDATE assignments SET status = 'in_progress', actual_start = $2 WHERE id = $1`, body.AssignmentID, now); err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	h.publish(ctx, "handoff_initiated", "handoff", hid, map[string]interface{}{"sampleId": sid})
	auditAction(ctx, h.PG, p.User.ID, p.ActiveRole, "initiate_handoff", "handoff", hid, true, map[string]interface{}{"assignmentId": body.AssignmentID})
	data(w, http.StatusCreated, map[string]interface{}{
		"handoffId":        hid,
		"senderId":         p.User.ID,
		"receiverId":       body.ReceiverID,
		"currentHolderId":  p.User.ID,
		"status":           "initiated",
	})
}

// POST /api/confirm-handoff
func (h *CoreHandler) ConfirmHandoff(w http.ResponseWriter, r *http.Request) {
	p := auth.PrincipalOf(r)
	if p == nil {
		writeErr(w, http.StatusUnauthorized, "unauthorized", "not signed in")
		return
	}
	var body struct {
		HandoffID    string `json:"handoffId"`
		Side         string `json:"side"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if !parseJSON(w, r, &body) {
		return
	}
	if body.Side != "sender" && body.Side != "receiver" {
		writeErr(w, http.StatusBadRequest, "invalid_confirmation_side", "side must be sender or receiver")
		return
	}
	ctx := r.Context()
	row := h.PG.QueryRow(ctx, `
        SELECT id::text, sender_id::text, COALESCE(receiver_id::text,''), status, sample_id::text,
               sender_confirmed_at IS NOT NULL, receiver_confirmed_at IS NOT NULL
        FROM handoffs WHERE id = $1
    `, body.HandoffID)
	var id, sender, receiver, st, sid string
	var sConfirmed, rConfirmed bool
	if err := row.Scan(&id, &sender, &receiver, &st, &sid, &sConfirmed, &rConfirmed); err != nil {
		if err == pgx.ErrNoRows {
			writeErr(w, http.StatusNotFound, "not_found", "handoff not found")
			return
		}
		writeErr(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	now := time.Now().UTC()
	if body.Side == "sender" {
		if p.User.ID != sender {
			writeErr(w, http.StatusForbidden, "invalid_sender", "not the sender")
			return
		}
		if sConfirmed {
			writeErr(w, http.StatusConflict, "idempotency_conflict", "sender already confirmed")
			return
		}
		if _, err := h.PG.Exec(ctx, `UPDATE handoffs SET sender_confirmed_at = $2, status = CASE WHEN receiver_confirmed_at IS NOT NULL THEN 'completed' ELSE 'sender_confirmed' END WHERE id = $1`, body.HandoffID, now); err != nil {
			writeErr(w, http.StatusInternalServerError, "internal_error", err.Error())
			return
		}
	} else {
		if p.User.ID != receiver {
			writeErr(w, http.StatusForbidden, "invalid_receiver", "not the receiver")
			return
		}
		if rConfirmed {
			writeErr(w, http.StatusConflict, "idempotency_conflict", "receiver already confirmed")
			return
		}
		if _, err := h.PG.Exec(ctx, `UPDATE handoffs SET receiver_confirmed_at = $2, status = CASE WHEN sender_confirmed_at IS NOT NULL THEN 'completed' ELSE 'receiver_confirmed' END WHERE id = $1`, body.HandoffID, now); err != nil {
			writeErr(w, http.StatusInternalServerError, "internal_error", err.Error())
			return
		}
	}
	// determine final
	row2 := h.PG.QueryRow(ctx, `
        SELECT sender_confirmed_at IS NOT NULL, receiver_confirmed_at IS NOT NULL,
               status, sample_id::text, assignment_id::text
        FROM handoffs WHERE id = $1
    `, body.HandoffID)
	var sc, rc, finalStatus, sampleID2, aID string
	_ = row2.Scan(&sc, &rc, &finalStatus, &sampleID2, &aID)
	sConf := sc
	rConf := rc
	finalStat := finalStatus
	if sConf && rConf {
		if _, err := h.PG.Exec(ctx, `UPDATE handoffs SET status = 'completed', completed_at = $2 WHERE id = $1`, body.HandoffID, now); err != nil {
			writeErr(w, http.StatusInternalServerError, "internal_error", err.Error())
			return
		}
		if _, err := h.PG.Exec(ctx, `UPDATE samples SET current_holder_id = $2 WHERE id = $1`, sampleID2, receiver); err != nil {
			writeErr(w, http.StatusInternalServerError, "internal_error", err.Error())
			return
		}
		if _, err := h.PG.Exec(ctx, `UPDATE assignments SET status = 'completed', actual_end = $2 WHERE id = $1`, aID, now); err != nil {
			writeErr(w, http.StatusInternalServerError, "internal_error", err.Error())
			return
		}
		if _, err := h.PG.Exec(ctx, `
            INSERT INTO sample_timeline (id, sample_id, event_type, description, recorded_at, actor_id)
            VALUES ($1,$2,'handoff_completed',$3,$4,$5)
        `, uuid.NewString(), sampleID2, "Handoff completed", now, p.User.ID); err != nil {
			writeErr(w, http.StatusInternalServerError, "internal_error", err.Error())
			return
		}
		h.publish(ctx, "handoff_completed", "handoff", body.HandoffID, map[string]interface{}{"sampleId": sampleID2, "newHolder": receiver})
		finalStat = "completed"
	} else {
		h.publish(ctx, "handoff_confirmed", "handoff", body.HandoffID, map[string]interface{}{"side": body.Side})
	}
	auditAction(ctx, h.PG, p.User.ID, p.ActiveRole, "confirm_handoff", "handoff", body.HandoffID, true, map[string]interface{}{"side": body.Side})
	data(w, http.StatusOK, map[string]interface{}{
		"handoffId":         body.HandoffID,
		"status":            finalStat,
		"senderConfirmed":   sConf,
		"receiverConfirmed": rConf,
		"currentHolderId":   ifThenElse(sConf && rConf, receiver, p.User.ID),
	})
}

func ifThenElse(cond bool, a, b string) string {
	if cond {
		return a
	}
	return b
}

