// POST /api/record-worker-location
func (h *CoreHandler) RecordWorkerLocation(w http.ResponseWriter, r *http.Request) {
	p := auth.PrincipalOf(r)
	if p == nil {
		writeErr(w, http.StatusUnauthorized, "unauthorized", "not signed in")
		return
	}
	var body struct {
		AssignmentID string             `json:"assignmentId"`
		Coordinate   map[string]float64 `json:"coordinate"`
		Sequence     int                `json:"sequence"`
		RecordedAt   string             `json:"recordedAt"`
	}
	if !parseJSON(w, r, &body) {
		return
	}
	if body.AssignmentID == "" {
		writeErr(w, http.StatusBadRequest, "invalid_assignment", "assignmentId required")
		return
	}
	recordedAt, ok := util.ParseTime(body.RecordedAt)
	if !ok {
		recordedAt = time.Now().UTC()
	}
	if body.Sequence <= 0 {
		body.Sequence = 1
	}
	ctx := r.Context()
	// Verify assignment belongs to user (or admin)
	row := h.PG.QueryRow(ctx, `SELECT COALESCE(worker_id::text,'') FROM assignments WHERE id = $1`, body.AssignmentID)
	var wID string
	if err := row.Scan(&wID); err != nil {
		if err == pgx.ErrNoRows {
			writeErr(w, http.StatusNotFound, "not_found", "assignment not found")
			return
		}
		writeErr(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	if wID != "" && wID != p.User.ID && !p.HasRole("administrator") {
		writeErr(w, http.StatusForbidden, "invalid_worker", "not your assignment")
		return
	}
	if _, err := h.PG.Exec(ctx, `
        INSERT INTO worker_locations (id, user_id, assignment_id, latitude, longitude, sequence, recorded_at)
        VALUES ($1,$2,$3,$4,$5,$6,$7)
    `, uuid.NewString(), p.User.ID, body.AssignmentID, body.Coordinate["latitude"], body.Coordinate["longitude"], body.Sequence, recordedAt); err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	// Update sample's latest location
	if _, err := h.PG.Exec(ctx, `
        UPDATE samples SET latest_latitude = $2, latest_longitude = $3, location_recorded_at = $4
        WHERE id = (SELECT sample_id FROM assignments WHERE id = $1)
    `, body.AssignmentID, body.Coordinate["latitude"], body.Coordinate["longitude"], recordedAt); err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	h.publish(ctx, "worker_location", "user", p.User.ID, map[string]interface{}{"assignmentId": body.AssignmentID, "sequence": body.Sequence})
	data(w, http.StatusCreated, map[string]interface{}{
		"assignmentId": body.AssignmentID,
		"coordinate":   body.Coordinate,
		"sequence":     body.Sequence,
		"recordedAt":   recordedAt.Format(time.RFC3339Nano),
	})
}

// POST /api/record-handling-checkpoint
func (h *CoreHandler) RecordHandlingCheckpoint(w http.ResponseWriter, r *http.Request) {
	p := auth.PrincipalOf(r)
	if p == nil {
		writeErr(w, http.StatusUnauthorized, "unauthorized", "not signed in")
		return
	}
	var body struct {
		SampleID      string  `json:"sampleId"`
		ContainerType string  `json:"containerType"`
		TemperatureC  float64 `json:"temperatureC"`
		ObservedAt    string  `json:"observedAt"`
	}
	if !parseJSON(w, r, &body) {
		return
	}
	observedAt, ok := util.ParseTime(body.ObservedAt)
	if !ok {
		observedAt = time.Now().UTC()
	}
	row := h.PG.QueryRow(r.Context(), `
        SELECT COALESCE(container_type,''), COALESCE(temperature_min_c,0), COALESCE(temperature_max_c,0), status, current_holder_id::text
        FROM samples WHERE id = $1
    `, body.SampleID)
	var cType string
	var tmin, tmax float64
	var status, holder string
	if err := row.Scan(&cType, &tmin, &tmax, &status, &holder); err != nil {
		if err == pgx.ErrNoRows {
			writeErr(w, http.StatusNotFound, "not_found", "sample not found")
			return
		}
		writeErr(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	if holder != p.User.ID && !p.HasRole("administrator") {
		writeErr(w, http.StatusForbidden, "not_current_holder", "not the holder")
		return
	}
	compliant := true
	if cType != "" && body.ContainerType != "" && cType != body.ContainerType {
		compliant = false
	}
	if body.TemperatureC < tmin || body.TemperatureC > tmax {
		compliant = false
	}
	finalStatus := status
	if !compliant {
		finalStatus = "exception"
		if _, err := h.PG.Exec(r.Context(), `UPDATE samples SET status = 'exception' WHERE id = $1`, body.SampleID); err != nil {
			writeErr(w, http.StatusInternalServerError, "internal_error", err.Error())
			return
		}
	}
	if _, err := h.PG.Exec(r.Context(), `
        INSERT INTO handling_checkpoints (id, sample_id, observer_id, container_type, temperature_c, observed_at, compliant)
        VALUES ($1,$2,$3,$4,$5,$6,$7)
    `, uuid.NewString(), body.SampleID, p.User.ID, body.ContainerType, body.TemperatureC, observedAt, compliant); err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	h.publish(r.Context(), "handling_checkpoint", "sample", body.SampleID, map[string]interface{}{"compliant": compliant})
	auditAction(r.Context(), h.PG, p.User.ID, p.ActiveRole, "record_handling_checkpoint", "sample", body.SampleID, true, map[string]interface{}{"compliant": compliant})
	data(w, http.StatusCreated, map[string]interface{}{
		"checkpointId": uuid.NewString(),
		"sampleId":     body.SampleID,
		"compliant":    compliant,
		"sampleStatus": finalStatus,
	})
}

