	}
	newStatus := body.Status
	if newStatus == "" {
		newStatus = "in_progress"
	}
	if _, err := h.PG.Exec(ctx, `UPDATE assignments SET status = $2 WHERE id = $1`, body.AssignmentID, newStatus); err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	if _, err := h.PG.Exec(ctx, `
        INSERT INTO sample_timeline (id, sample_id, event_type, description, recorded_at, actor_id)
        VALUES ($1,$2,'assignment_progress',$3,$4,$5)
    `, uuid.NewString(), sid, "Assignment status now "+newStatus, time.Now().UTC(), p.User.ID); err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	h.publish(ctx, "assignment_progress", "assignment", body.AssignmentID, map[string]interface{}{"status": newStatus})
	auditAction(ctx, h.PG, p.User.ID, p.ActiveRole, "update_assignment_progress", "assignment", body.AssignmentID, true, map[string]interface{}{"status": newStatus})
	data(w, http.StatusOK, map[string]interface{}{
		"assignmentId": body.AssignmentID,
		"sampleId":     sid,
		"status":       newStatus,
	})
}

// eligibleForRole returns true if the user holds the role for this assignment type.
func eligibleForRole(p *auth.Principal, assignmentType string) bool {
	if p.HasRole("administrator") || p.HasRole("dispatcher") {
		return true
	}
	switch assignmentType {
	case "collection":
		return p.HasRole("collection_professional")
	case "transport":
		return p.HasRole("delivery_partner")
	case "node_arrival", "node_departure":
		return p.HasRole("node_handler")
	case "laboratory_intake":
		return p.HasRole("laboratory_team")
	}
	return false
}"}

