// POST /api/cancel-journey
func (h *CoreHandler) CancelJourney(w http.ResponseWriter, r *http.Request) {
	p := auth.PrincipalOf(r)
	if p == nil {
		writeErr(w, http.StatusUnauthorized, "unauthorized", "not signed in")
		return
	}
	if !p.HasAnyRole("dispatcher", "administrator", "requester") {
		writeErr(w, http.StatusForbidden, "forbidden", "role not permitted")
		return
	}
	var body struct {
		JourneyID          string `json:"journeyId"`
		ExpectedPlanVersion *int  `json:"expectedPlanVersion"`
		Reason             string `json:"reason"`
		IdempotencyKey     string `json:"idempotencyKey"`
	}
	if !parseJSON(w, r, &body) {
		return
	}
	if body.JourneyID == "" {
		writeErr(w, http.StatusBadRequest, "invalid_journey", "journeyId required")
		return
	}
	ctx := r.Context()
	tx, err := h.PG.Begin(ctx)
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	defer tx.Rollback(ctx)
	row := tx.QueryRow(ctx, `SELECT id::text, plan_version, status, sample_id::text FROM journeys WHERE id = $1 FOR UPDATE`, body.JourneyID)
	var id string
	var pv int
	var st, sid string
	if err := row.Scan(&id, &pv, &st, &sid); err != nil {
		if err == pgx.ErrNoRows {
			writeErr(w, http.StatusNotFound, "not_found", "journey not found")
			return
		}
		writeErr(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	if body.ExpectedPlanVersion != nil && *body.ExpectedPlanVersion != pv {
		writeErr(w, http.StatusConflict, "stale_plan", "plan version mismatch")
		return
	}
	if st == "cancelled" || st == "received" {
		writeErr(w, http.StatusConflict, "journey_inactive", "journey already terminal")
		return
	}
	now := time.Now().UTC()
	if _, err := tx.Exec(ctx, `UPDATE journeys SET status = 'cancelled', plan_version = plan_version + 1 WHERE id = $1`, body.JourneyID); err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	if _, err := tx.Exec(ctx, `UPDATE samples SET status = 'cancelled' WHERE id = $1`, sid); err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	if _, err := tx.Exec(ctx, `UPDATE assignments SET status = 'cancelled' WHERE journey_id = $1 AND status IN ('offered','accepted','in_progress')`, body.JourneyID); err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	if _, err := tx.Exec(ctx, `
        INSERT INTO sample_timeline (id, sample_id, event_type, description, recorded_at, actor_id)
        VALUES ($1,$2,'journey_cancelled',$3,$4,$5)
    `, uuid.NewString(), sid, "Journey cancelled: "+body.Reason, now, p.User.ID); err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	if err := tx.Commit(ctx); err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	h.publish(ctx, "journey_cancelled", "journey", body.JourneyID, map[string]interface{}{"sampleId": sid, "reason": body.Reason})
	auditAction(ctx, h.PG, p.User.ID, p.ActiveRole, "cancel_journey", "journey", body.JourneyID, true, map[string]interface{}{"reason": body.Reason})
	data(w, http.StatusOK, map[string]interface{}{
