		"sampleIds": []string{sid},
	})
}

// POST /api/edit-active-plan
func (h *CoreHandler) EditActivePlan(w http.ResponseWriter, r *http.Request) {
	p := requireRole(w, r, "dispatcher", "administrator")
	if p == nil {
		return
	}
	var body struct {
		JourneyID            string                 `json:"journeyId"`
		ExpectedPlanVersion  *int                   `json:"expectedPlanVersion"`
		ChangeType           string                 `json:"changeType"`
		Changes              map[string]interface{} `json:"changes"`
		IdempotencyKey       string                 `json:"idempotencyKey"`
	}
	if !parseJSON(w, r, &body) {
		return
	}
	ctx := r.Context()
	tx, err := h.PG.Begin(ctx)
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	defer tx.Rollback(ctx)
	row := tx.QueryRow(ctx, `SELECT plan_version, status, sample_id::text FROM journeys WHERE id = $1 FOR UPDATE`, body.JourneyID)
	var pv int
	var st, sid string
	if err := row.Scan(&pv, &st, &sid); err != nil {
		if err == pgx.ErrNoRows {
			writeErr(w, http.StatusNotFound, "not_found", "journey not found")
			return
		}
		writeErr(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	if body.ExpectedPlanVersion != nil && *body.ExpectedPlanVersion != pv {
		writeErr(w, http.StatusConflict, "stale_plan", "plan version mismatch")
		return
	}
	if st == "cancelled" || st == "received" {
		writeErr(w, http.StatusConflict, "completed_work_immutable", "journey terminal")
		return
	}
	switch body.ChangeType {
	case "reassign_worker":
		newWorker, _ := body.Changes["newWorkerId"].(string)
		assignmentID, _ := body.Changes["assignmentId"].(string)
		if newWorker == "" || assignmentID == "" {
			writeErr(w, http.StatusBadRequest, "invalid_plan", "newWorkerId and assignmentId required")
			return
		}
		if _, err := tx.Exec(ctx, `UPDATE assignments SET worker_id = $2, status = 'offered' WHERE id = $1`, assignmentID, newWorker); err != nil {
			writeErr(w, http.StatusInternalServerError, "internal_error", err.Error())
			return
		}
		if _, err := tx.Exec(ctx, `
            INSERT INTO sample_timeline (id, sample_id, event_type, description, recorded_at, actor_id)
            VALUES ($1,$2,'plan_edit',$3,$4,$5)
        `, uuid.NewString(), sid, "Reassigned worker via plan edit", time.Now().UTC(), p.User.ID); err != nil {
			writeErr(w, http.StatusInternalServerError, "internal_error", err.Error())
			return
		}
	case "cancel_work":
		assignmentID, _ := body.Changes["assignmentId"].(string)
		if assignmentID == "" {
			writeErr(w, http.StatusBadRequest, "invalid_plan", "assignmentId required")
			return
		}
		var st2 string
		_ = tx.QueryRow(ctx, `SELECT status FROM assignments WHERE id = $1`, assignmentID).Scan(&st2)
		if st2 == "completed" {
			writeErr(w, http.StatusConflict, "completed_work_immutable", "assignment completed")
			return
		}
		if _, err := tx.Exec(ctx, `UPDATE assignments SET status = 'cancelled' WHERE id = $1`, assignmentID); err != nil {
			writeErr(w, http.StatusInternalServerError, "internal_error", err.Error())
			return
		}
		if _, err := tx.Exec(ctx, `
            INSERT INTO sample_timeline (id, sample_id, event_type, description, recorded_at, actor_id)
            VALUES ($1,$2,'plan_edit',$3,$4,$5)
        `, uuid.NewString(), sid, "Assignment cancelled via plan edit", time.Now().UTC(), p.User.ID); err != nil {
			writeErr(w, http.StatusInternalServerError, "internal_error", err.Error())
			return
		}
	default:
		// unknown changeType: still bump plan version to be safe
	}
	if _, err := tx.Exec(ctx, `UPDATE journeys SET plan_version = plan_version + 1 WHERE id = $1`, body.JourneyID); err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	if err := tx.Commit(ctx); err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	h.publish(ctx, "plan_edited", "journey", body.JourneyID, map[string]interface{}{"changeType": body.ChangeType})
	auditAction(ctx, h.PG, p.User.ID, p.ActiveRole, "edit_active_plan", "journey", body.JourneyID, true, map[string]interface{}{"changeType": body.ChangeType})
	data(w, http.StatusOK, []map[string]interface{}{{
		"journeyId":          body.JourneyID,
		"planVersion":        pv + 1,
		"sampleId":           sid,
		"changeType":         body.ChangeType,
	}})
}

// POST /api/merge-journeys
func (h *CoreHandler) MergeJourneys(w http.ResponseWriter, r *http.Request) {
	p := requireRole(w, r, "dispatcher", "administrator")
	if p == nil {
		return
	}
	var body struct {
		TargetJourneyID     string   `json:"targetJourneyId"`
		ExpectedPlanVersion *int     `json:"expectedPlanVersion"`
		SourceJourneyIDs    []string `json:"sourceJourneyIds"`
		IdempotencyKey      string   `json:"idempotencyKey"`
	}
	if !parseJSON(w, r, &body) {
		return
	}
	if body.TargetJourneyID == "" || len(body.SourceJourneyIDs) == 0 {
		writeErr(w, http.StatusBadRequest, "invalid_merge", "target and sources required")
		return
	}
	ctx := r.Context()
	tx, err := h.PG.Begin(ctx)
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	defer tx.Rollback(ctx)
	// validate target
	row := tx.QueryRow(ctx, `SELECT plan_version, status FROM journeys WHERE id = $1 FOR UPDATE`, body.TargetJourneyID)
	var pv int
	var st string
	if err := row.Scan(&pv, &st); err != nil {
		if err == pgx.ErrNoRows {
			writeErr(w, http.StatusNotFound, "not_found", "target journey not found")
			return
		}
		writeErr(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	if body.ExpectedPlanVersion != nil && *body.ExpectedPlanVersion != pv {
		writeErr(w, http.StatusConflict, "stale_plan", "plan version mismatch")
		return
	}
	if st == "cancelled" || st == "received" {
		writeErr(w, http.StatusConflict, "completed_work_immutable", "target terminal")
		return
	}
	// mark sources as merged
	for _, sid := range body.SourceJourneyIDs {
		if _, err := tx.Exec(ctx, `UPDATE journeys SET status = 'merged', plan_version = plan_version + 1 WHERE id = $1`, sid); err != nil {
			writeErr(w, http.StatusInternalServerError, "internal_error", err.Error())
			return
		}
		// reassign source samples' active_journey_id
		if _, err := tx.Exec(ctx, `UPDATE samples SET active_journey_id = $2 WHERE active_journey_id = $1`, sid, body.TargetJourneyID); err != nil {
			writeErr(w, http.StatusInternalServerError, "internal_error", err.Error())
			return
		}
		if _, err := tx.Exec(ctx, `UPDATE assignments SET journey_id = $2 WHERE journey_id = $1 AND status IN ('offered','accepted')`, sid, body.TargetJourneyID); err != nil {
			writeErr(w, http.StatusInternalServerError, "internal_error", err.Error())
			return
		}
	}
	if _, err := tx.Exec(ctx, `UPDATE journeys SET plan_version = plan_version + 1 WHERE id = $1`, body.TargetJourneyID); err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	if err := tx.Commit(ctx); err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	h.publish(ctx, "journeys_merged", "journey", body.TargetJourneyID, map[string]interface{}{"merged": body.SourceJourneyIDs})
	auditAction(ctx, h.PG, p.User.ID, p.ActiveRole, "merge_journeys", "journey", body.TargetJourneyID, true, map[string]interface{}{"sources": body.SourceJourneyIDs})
	out := []map[string]interface{}{}
	for _, sid := range body.SourceJourneyIDs {
		out = append(out, map[string]interface{}{
			"journeyId":    sid,
			"mergedInto":   body.TargetJourneyID,
			"planVersion":  pv + 1,
		})
	}
	data(w, http.StatusOK, out)
}

// POST /api/split-journey
func (h *CoreHandler) SplitJourney(w http.ResponseWriter, r *http.Request) {
	p := requireRole(w, r, "dispatcher", "administrator")
	if p == nil {
		return
	}
	var body struct {
		JourneyID            string   `json:"journeyId"`
		ExpectedPlanVersion  *int     `json:"expectedPlanVersion"`
		SampleIDs            []string `json:"sampleIds"`
		IdempotencyKey       string   `json:"idempotencyKey"`
	}
	if !parseJSON(w, r, &body) {
		return
	}
	if body.JourneyID == "" || len(body.SampleIDs) == 0 {
		writeErr(w, http.StatusBadRequest, "invalid_split", "journeyId and sampleIds required")
		return
	}
	ctx := r.Context()
	tx, err := h.PG.Begin(ctx)
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	defer tx.Rollback(ctx)
	row := tx.QueryRow(ctx, `SELECT plan_version, status, sample_id::text, target_laboratory_id::text, delivery_deadline FROM journeys WHERE id = $1 FOR UPDATE`, body.JourneyID)
	var pv int
	var st, sid, tlab string
	var deadline time.Time
	if err := row.Scan(&pv, &st, &sid, &tlab, &deadline); err != nil {
		if err == pgx.ErrNoRows {
