// POST /api/reroute-journey
func (h *CoreHandler) RerouteJourney(w http.ResponseWriter, r *http.Request) {
	p := requireRole(w, r, "dispatcher", "administrator")
	if p == nil {
		return
	}
	var body struct {
		JourneyID            string `json:"journeyId"`
		ExpectedPlanVersion  *int   `json:"expectedPlanVersion"`
		Reason               string `json:"reason"`
		IdempotencyKey       string `json:"idempotencyKey"`
	}
	if !parseJSON(w, r, &body) {
		return
	}
	if body.JourneyID == "" {
		writeErr(w, http.StatusBadRequest, "invalid_route", "journeyId required")
		return
	}
	ctx := r.Context()
	tx, err := h.PG.Begin(ctx)
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	defer tx.Rollback(ctx)
	row := tx.QueryRow(ctx, `SELECT plan_version, status, sample_id::text, delivery_deadline FROM journeys WHERE id = $1 FOR UPDATE`, body.JourneyID)
	var pv int
	var st, sid string
	var deadline time.Time
	if err := row.Scan(&pv, &st, &sid, &deadline); err != nil {
		if err == pgx.ErrNoRows {
			writeErr(w, http.StatusNotFound, "not_found", "journey not found")
			return
		}
		writeErr(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	if body.ExpectedPlanVersion != nil && *body.ExpectedPlanVersion != pv {
		writeErr(w, http.StatusConflict, "stale_plan", "plan version mismatch")
		return
	}
	now := time.Now().UTC()
	if deadline.Before(now) {
		if _, err := tx.Exec(ctx, `UPDATE journeys SET status = 'expired', plan_version = plan_version + 1 WHERE id = $1`, body.JourneyID); err != nil {
			writeErr(w, http.StatusInternalServerError, "internal_error", err.Error())
			return
		}
		if _, err := tx.Exec(ctx, `UPDATE samples SET status = 'expired' WHERE id = $1`, sid); err != nil {
			writeErr(w, http.StatusInternalServerError, "internal_error", err.Error())
			return
		}
		if err := tx.Commit(ctx); err != nil {
			writeErr(w, http.StatusInternalServerError, "internal_error", err.Error())
			return
		}
		data(w, http.StatusOK, map[string]interface{}{
			"journeyId":     body.JourneyID,
			"replanStatus":  "expired",
			"replacementPlanId": "",
			"replacementJourney": map[string]interface{}{"journeyId": body.JourneyID, "status": "expired"},
		})
		return
	}
	if _, err := tx.Exec(ctx, `UPDATE assignments SET status = 'cancelled' WHERE journey_id = $1 AND status IN ('offered','accepted')`, body.JourneyID); err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	if _, err := tx.Exec(ctx, `UPDATE journeys SET plan_version = plan_version + 1, status = 'active' WHERE id = $1`, body.JourneyID); err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	if _, err := tx.Exec(ctx, `
        INSERT INTO sample_timeline (id, sample_id, event_type, description, recorded_at, actor_id)
        VALUES ($1,$2,'journey_rerouted',$3,$4,$5)
    `, uuid.NewString(), sid, "Journey rerouted: "+body.Reason, now, p.User.ID); err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	if err := tx.Commit(ctx); err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	h.publish(ctx, "journey_rerouted", "journey", body.JourneyID, map[string]interface{}{"reason": body.Reason})
	auditAction(ctx, h.PG, p.User.ID, p.ActiveRole, "reroute_journey", "journey", body.JourneyID, true, map[string]interface{}{"reason": body.Reason})
	data(w, http.StatusOK, map[string]interface{}{
		"journeyId":          body.JourneyID,
		"replanStatus":       "replaced",
		"replacementPlanId":  body.JourneyID,
		"replacementJourney": map[string]interface{}{
			"journeyId":   body.JourneyID,
			"planVersion": pv + 1,
			"status":      "active",
			"sampleId":    sid,
		},
	})
}

// POST /api/report-disruption
func (h *CoreHandler) ReportDisruption(w http.ResponseWriter, r *http.Request) {
	p := requireRole(w, r, "dispatcher", "administrator")
	if p == nil {
		return
	}
	var body struct {
		ResourceType   string `json:"resourceType"`
		ResourceID     string `json:"resourceId"`
		Reason         string `json:"reason"`
		OccurredAt     string `json:"occurredAt"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if !parseJSON(w, r, &body) {
		return
	}
	ctx := r.Context()
	eid := uuid.NewString()
	occurredAt, ok := util.ParseTime(body.OccurredAt)
	if !ok {
		occurredAt = time.Now().UTC()
	}
	if _, err := h.PG.Exec(ctx, `
        INSERT INTO disruptions (id, resource_type, resource_id, reason, occurred_at, reported_by)
        VALUES ($1,$2,$3,$4,$5,$6)
    `, eid, body.ResourceType, body.ResourceID, body.Reason, occurredAt, p.User.ID); err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	// find affected samples
	rows, _ := h.PG.Query(ctx, `
        SELECT DISTINCT s.id::text FROM samples s
        JOIN assignments a ON a.sample_id = s.id
        LEFT JOIN locations l ON l.id::text = $1 OR a.from_location_id = $1 OR a.to_location_id = $1
        LEFT JOIN connections c ON c.id::text = $1 OR c.from_location_id::text = $1 OR c.to_location_id::text = $1
        WHERE a.status IN ('accepted','in_progress','offered')
    `, body.ResourceID)
	affected := []string{}
	for rows != nil && rows.Next() {
		var s string
		if err := rows.Scan(&s); err == nil {
			affected = append(affected, s)
		}
	}
	if rows != nil {
		rows.Close()
	}
	h.invalidateServiceability(ctx)
	h.publish(ctx, "disruption_reported", "disruption", eid, map[string]interface{}{"resourceType": body.ResourceType, "affected": len(affected)})
	auditAction(ctx, h.PG, p.User.ID, p.ActiveRole, "report_disruption", "disruption", eid, true, map[string]interface{}{"resource": body.ResourceID})
	data(w, http.StatusCreated, map[string]interface{}{
		"disruptionId":        eid,
		"affectedSampleIds":   affected,
		"replacementPlanIds":  []string{},
		"replanStatus":        "not_required",
	})
}

// POST /api/search-audit-trail
func (h *CoreHandler) SearchAudit(w http.ResponseWriter, r *http.Request) {
	p := requireRole(w, r, "administrator", "dispatcher")
	if p == nil {
		return
	}
	var body struct {
		Query      string `json:"query"`
		ActorID    string `json:"actorId"`
		EntityType string `json:"entityType"`
		EntityID   string `json:"entityId"`
		Action     string `json:"action"`
		Role       string `json:"role"`
		Success    *bool  `json:"success"`
		FromTime   string `json:"fromTime"`
		ToTime     string `json:"toTime"`
		Limit      int    `json:"limit"`
		Offset     int    `json:"offset"`
		Order      string `json:"order"`
	}
	if !parseJSON(w, r, &body) {
		return
	}
	if body.Limit <= 0 {
		body.Limit = 500
	}
	if body.Limit > 5000 {
		body.Limit = 5000
	}
	if body.Offset < 0 {
		body.Offset = 0
	}
	q := `SELECT id::text, COALESCE(actor_id::text,''), COALESCE(role,''), action, entity_type, COALESCE(entity_id,''), success, details::text, created_at FROM audit_log WHERE 1=1`
	args := []interface{}{}
	i := 1
	if body.ActorID != "" {
		q += " AND actor_id::text = $" + itoa(i)
		args = append(args, body.ActorID)
		i++
	}
	if body.EntityType != "" {
		q += " AND entity_type = $" + itoa(i)
		args = append(args, body.EntityType)
		i++
	}
	if body.EntityID != "" {
		q += " AND entity_id = $" + itoa(i)
		args = append(args, body.EntityID)
		i++
	}
	if body.Action != "" {
		q += " AND action = $" + itoa(i)
		args = append(args, body.Action)
		i++
	}
	if body.Role != "" {
		q += " AND role = $" + itoa(i)
		args = append(args, body.Role)
		i++
	}
	if body.Success != nil {
		q += " AND success = $" + itoa(i)
		args = append(args, *body.Success)
		i++
	}
	if body.FromTime != "" {
		t, ok := util.ParseTime(body.FromTime)
		if ok {
			q += " AND created_at >= $" + itoa(i)
			args = append(args, t)
			i++
		}
	}
	if body.ToTime != "" {
		t, ok := util.ParseTime(body.ToTime)
		if ok {
			q += " AND created_at <= $" + itoa(i)
			args = append(args, t)
			i++
		}
	}
	if body.Query != "" {
		pat := "%" + body.Query + "%"
		q += " AND (action ILIKE $" + itoa(i) + " OR entity_type ILIKE $" + itoa(i) + " OR details::text ILIKE $" + itoa(i) + ")"
		args = append(args, pat)
		i++
	}
	order := "DESC"
	if body.Order == "oldest_first" {
		order = "ASC"
	}
	q += " ORDER BY created_at " + order + " LIMIT $" + itoa(i) + " OFFSET $" + itoa(i+1)
	args = append(args, body.Limit, body.Offset)
	rows, err := h.PG.Query(r.Context(), q, args...)
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	defer rows.Close()
	out := []map[string]interface{}{}
	for rows.Next() {
		var id, actor, role, action, etype, eid string
		var success bool
		var details string
		var created time.Time
		if err := rows.Scan(&id, &actor, &role, &action, &etype, &eid, &success, &details, &created); err != nil {
			break
		}
		det := map[string]interface{}{}
		_ = safeJSONUnmarshal([]byte(details), &det)
		out = append(out, map[string]interface{}{
			"id":          id,
			"actorId":     actor,
			"role":        role,
			"action":      action,
			"entityType":  etype,
			"entityId":    eid,
			"success":     success,
			"details":     det,
			"createdAt":   created.UTC().Format(time.RFC3339Nano),
		})
	}
	data(w, http.StatusOK, out)
}

func itoa(i int) string {
	// minimal local converter to avoid extra import
	if i == 0 {
		return "0"
	}
	neg := false
	if i < 0 {
		neg = true
		i = -i
	}
	digits := []byte{}
	for i > 0 {
		digits = append([]byte{byte('0' + i%10)}, digits...)
		i /= 10
	}
	if neg {
		digits = append([]byte{'-'}, digits...)
	}
	return string(digits)
}"}

