func (b *Bus) Latest(ctx context.Context, n int64) ([]*Event, error) {
	coll := b.store.Mongo.Database(b.store.DB).Collection("events")
	opts := options.Find().SetSort(bson.M{"id": -1}).SetLimit(n)
	cur, err := coll.Find(ctx, bson.M{}, opts)
	if err != nil {
		return nil, err
	}
	defer cur.Close(ctx)
	var out []*Event
	for cur.Next(ctx) {
		ev := &Event{}
		if err := cur.Decode(ev); err != nil {
			return nil, err
		}
		out = append(out, ev)
	}
	// reverse to ascending
	for i, j := 0, len(out)-1; i < j; i, j = i+1, j-1 {
		out[i], out[j] = out[j], out[i]
	}
	return out, nil
}

// SnapshotSince returns events since the given id and the new cursor.
// Cursor is the max id returned.
func (b *Bus) SnapshotSince(since int64) ([]map[string]interface{}, int64) {
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()
	events, err := b.Since(ctx, since)
	if err != nil {
		return nil, since
	}
	out := make([]map[string]interface{}, 0, len(events))
	var maxID int64 = since
	for _, ev := range events {
		out = append(out, map[string]interface{}{
			"id":         ev.ID,
			"type":       ev.Type,
			"entityType": ev.EntityType,
			"entityId":   ev.EntityID,
			"payload":    ev.Payload,
			"createdAt":  ev.CreatedAt.Format("2006-01-02T15:04:05.999999Z07:00"),
		})
		if ev.ID > maxID {
			maxID = ev.ID
		}
	}
	return out, maxID
}"}

