func main() {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	store, err := db.Open(ctx)
	if err != nil {
		log.Fatalf("db open: %v", err)
	}
	defer store.Close()

	au := auth.New(store.PG)
	mw := auth.NewMiddleware(store, au)
	bus := events.New(store)
	svc := serviceability.New(store.PG)
	if err := svc.EnsureLoaded(ctx); err != nil {
		log.Printf("serviceability initial: %v", err)
	}
	go svc.Loop(ctx)

	authh := handlers.NewAuthHandler(au)
	core := handlers.NewCoreHandler(store.PG, au, svc, bus)

	// ensure first admin from env
	if err := authh.EnsureAdminFromEnv(ctx); err != nil {
		log.Printf("ensure admin: %v", err)
	}
	// ensure default sample types + certifications
	if err := ensureDefaults(ctx, store); err != nil {
		log.Printf("defaults: %v", err)
	}

	router := server.Router(authh, core, mw, store.PG)

	addr := os.Getenv("BACKEND_ADDR")
	if addr == "" {
		addr = "127.0.0.1:18082"
	}
	srv := &http.Server{Addr: addr, Handler: router, ReadHeaderTimeout: 10 * time.Second}

	go func() {
		log.Printf("backend listening on %s", addr)
		if err := srv.ListenAndServe(); err != nil && err != http.ErrServerClosed {
			log.Fatalf("listen: %v", err)
		}
	}()

	stop := make(chan os.Signal, 1)
	signal.Notify(stop, syscall.SIGINT, syscall.SIGTERM)
	<-stop
	log.Printf("shutting down")
	shutCtx, c := context.WithTimeout(context.Background(), 10*time.Second)
	defer c()
	_ = srv.Shutdown(shutCtx)
}

// ensureDefaults inserts default sample types and certifications if missing.
func ensureDefaults(ctx context.Context, s *db.Store) error {
	types := []struct {
		Code, Name, Container, Desc string
		ReqColl, ReqCooled, Pulse   bool
		Tmin, Tmax                  float64
		Incompat                    []string
	}{
		{"amber", "Amber", "tube", "Standard handling", true, false, false, 0, 25, nil},
		{"indigo", "Indigo", "tube", "Must not share container with Amber", true, false, false, 0, 25, nil},
		{"frost", "Frost", "cooler", "Requires cooled storage throughout journey", true, true, false, 2, 8, nil},
		{"pulse", "Pulse", "vial", "Time-critical, never batched", true, false, true, 0, 25, nil},
	}
	for _, t := range types {
		var exists bool
		_ = s.PG.QueryRow(ctx, `SELECT EXISTS(SELECT 1 FROM sample_types WHERE code = $1)`, t.Code).Scan(&exists)
		if exists {
			continue
		}
		_, err := s.PG.Exec(ctx, `
            INSERT INTO sample_types (id, code, name, description, requires_qualified_collector, container_type,
                temperature_min_c, temperature_max_c, requires_cooled, incompatible_sample_type_ids, pulse_critical, active)
            VALUES (gen_random_uuid()::text, $1, $2, $3, $4, $5, $6, $7, $8, $9::uuid[], $10, TRUE)
        `, t.Code, t.Name, t.Desc, t.ReqColl, t.Container, t.Tmin, t.Tmax, t.ReqCooled, t.Incompat, t.Pulse)
		if err != nil {
			return err
		}
	}
	return nil
}"}

