{"security_risk":"LOW","summary":"api client","command":"create","path":"/workspace/frontend/src/api.ts","file_text":"// Minimal typed API client. Returns the `data` field of `{data:...}` envelopes;
// throws on flat `{error,code}` errors.
const BASE = '';

export type ApiErr = { error: string; code: string; status?: number };

function getToken(): string | null {
  return localStorage.getItem('auth_token');
}

export function setToken(t: string | null) {
  if (t) localStorage.setItem('auth_token', t);
  else localStorage.removeItem('auth_token');
}

export function getActiveRole(): string | null {
  return localStorage.getItem('active_role');
}

export function setActiveRole(r: string | null) {
  if (r) localStorage.setItem('active_role', r);
  else localStorage.removeItem('active_role');
}

async function call<T = any>(
  method: string,
  path: string,
  body?: any,
  opts: { auth?: boolean } = { auth: true }
): Promise<T> {
  const headers: Record<string, string> = { 'Content-Type': 'application/json' };
  if (opts.auth !== false) {
    const t = getToken();
    if (t) headers['Authorization'] = `Bearer ${t}`;
  }
  const r = await fetch(BASE + path, {
    method,
    headers,
    body: body ? JSON.stringify(body) : undefined,
  });
  const text = await r.text();
  let parsed: any;
  try {
    parsed = text ? JSON.parse(text) : {};
  } catch {
    throw { error: 'invalid_json', code: 'invalid_json', status: r.status } as ApiErr;
  }
  if (!r.ok) {
    const err = parsed && (parsed.error || parsed.code) ? parsed : { error: 'http_error', code: 'http_error' };
    (err as ApiErr).status = r.status;
    throw err;
  }
  return parsed.data !== undefined ? parsed.data : parsed;
}

export const api = {
  authenticateUser: (username: string, password: string) =>
    call<{ token: string; userId: string; roles: string[] }>(
      'POST', '/api/authenticate-user', { username, password }, { auth: false }
    ),
  signOut: () => call('DELETE', '/api/session'),

  bootstrap: () => call('GET', '/api/ui/bootstrap'),
  readUser: (userId: string) => call('GET', `/api/read-user/${userId}`),
  readSampleState: (sampleId: string) => call('GET', `/api/read-sample-state/${sampleId}`),
  readSampleLifecycle: (sampleId: string) => call('POST', '/api/read-sample-lifecycle', { sampleId }),
  readJourneyPlan: (journeyId: string) => call('POST', '/api/read-journey-plan', { journeyId }),
  readOperationsState: () => call('POST', '/api/read-operations-state', {}),
  readServiceabilitySnapshot: () => call('POST', '/api/read-serviceability-snapshot', {}),
  checkServiceability: (payload: any) => call('POST', '/api/check-serviceability', payload),

