  }
  useEffect(() => { load(); }, [sampleId]);

  const events: any[] = life?.events || life?.timeline || life?.statusHistory || (Array.isArray(life) ? life : []);
  const last = state?.lastLocationUpdateAt || state?.lastUpdateAt;
  const isStale = state?.locationStale ?? (last && (Date.now() - new Date(last).getTime() > 1000 * 60 * 60));
  const exception = state?.exception || state?.hasException || state?.flagged;

  return (
    <div className="card">
      <div style={{ display: 'flex', justifyContent: 'space-between' }}>
