            <dt>Current custodian</dt><dd>{state.currentHolderId || state.custodianId || '—'}</dd>
            <dt>Current location</dt><dd>{state.currentLocationId || state.location || '—'}</dd>
            <dt>Last update</dt><dd>
              {fmtTime(last)}{' '}
              {isStale
                ? <span className="badge warn"><span className="dot warn"></span>stale</span>
                : <span className="badge ok"><span className="dot ok"></span>fresh</span>}
            </dd>
            {exception && <><dt>Exception</dt><dd><span className="badge err">{String(exception)}</span></dd></>}
          </dl>
        </>
      )}
      <h3 style={{ fontSize: 13, color: '#58a6ff', marginTop: 12 }}>Status timeline</h3>
      <div className="timeline" role="list" aria-label="Status timeline">
        {events.length === 0 && <div className="muted">No events.</div>}
        {events.map((ev: any, i: number) => (
          <div className="ev" key={i} role="listitem">
            <div><strong>{ev.status || ev.type || ev.event || 'event'}</strong>{ev.note ? ` — ${ev.note}` : ''}</div>
            <div className="t">{fmtTime(ev.at || ev.occurredAt || ev.time)}</div>
          </div>
        ))}
      </div>
    </div>
  );
}

