            layers: [{ id: 'tiles', type: 'vector', source: 'local' }],
          } as any,
          center: [77.5946, 12.9716],
          zoom: 10,
        });
        map.on('error', () => { /* swallow tile errors */ });
        mapObj.current = map;
      } catch {
        // MapLibre unavailable — render fallback
      }
    })();
    return () => { cancelled = true; mapObj.current?.remove?.(); };
  }, [data]);

  const categories = {
    samples: data?.samples || [],
