              <div className="muted" style={{ textTransform: 'capitalize' }}>{k} <span className="badge">{categories[k].length}</span></div>
              <ul style={{ margin: '4px 0 0', paddingLeft: 16, fontSize: 12, maxHeight: 100, overflow: 'auto' }}>
                {categories[k].slice(0, 5).map((it: any, i: number) => (
                  <li key={i}>
                    {k === 'samples'
                      ? <button className="secondary" style={{ padding: '2px 6px', fontSize: 11 }}
                                 onClick={() => setSelected({ kind: 'sample', id: it.sampleId || it.id })}>
