// ------- location capture (worker_records_location_writes_through) -------
function LocationCapture() {
  const [lat, setLat] = useState('');
  const [lng, setLng] = useState('');
  const [result, setResult] = useState<string | null>(null);
  const [err, setErr] = useState<string | null>(null);
  async function submit(e: React.FormEvent) {
    e.preventDefault(); setErr(null); setResult(null);
    try {
      const r = await api.recordWorkerLocation({ latitude: parseFloat(lat), longitude: parseFloat(lng) });
      setResult(`Recorded at ${fmtTime(r.recordedAt || new Date().toISOString())}`);
    } catch (e: any) { setErr(errText(e)); }
  }
  return (
    <div className="card">
      <h2>Record my location</h2>
      <form onSubmit={submit}>
        <div className="row">
          <div><label htmlFor="loc-lat">Latitude</label>
            <input id="loc-lat" value={lat} onChange={e => setLat(e.target.value)} required /></div>
          <div><label htmlFor="loc-lng">Longitude</label>
            <input id="loc-lng" value={lng} onChange={e => setLng(e.target.value)} required /></div>
        </div>
        <button className="primary" style={{ marginTop: 10 }} aria-label="Record location">Record</button>
        {result && <div className="success">{result}</div>}
        {err && <div className="error">{err}</div>}
      </form>
    </div>
  );
}

// ------- capacity (lab_worker_views_own_capacity) -------
function CapacityView() {
  const [data, setData] = useState<any>(null);
  const [err, setErr] = useState<string | null>(null);
  async function load() {
    try { setData(await api.readOperationsState()); }
    catch (e: any) { setErr(errText(e)); }
  }
  useEffect(() => { load(); }, []);
  const pools: any[] = data?.capacity || data?.pools || [];
  return (
    <div className="card">
      <h2>Capacity pools</h2>
      {err && <div className="error" role="alert">{err}</div>}
      <table role="table">
        <thead><tr><th>Pool</th><th>Type</th><th>Configured</th><th>Reserved</th><th>Available</th></tr></thead>
        <tbody>
          {pools.length === 0 && <tr><td colSpan={5} className="muted">No pools visible.</td></tr>}
          {pools.map((p: any, i: number) => (
            <tr key={i}>
              <td>{p.poolId || p.id || p.locationId}</td>
              <td><span className="badge">{p.kind || p.type || (p.cooled ? 'cooled' : 'regular')}</span></td>
              <td>{p.configured ?? p.capacity ?? '—'}</td>
              <td>{p.reserved ?? '—'}</td>
              <td>{p.available ?? '—'}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

