// ------- assignment inbox used inside WorkView for accept/decline -------
function InboxSection() {
  const [items, setItems] = useState<any[]>([]);
  async function load() {
    try { const d: any = await api.listRoleWork('current');
      setItems(d?.items || d?.assignments || d?.requests || (Array.isArray(d) ? d : []));
    } catch { /* ignore */ }
  }
  useEffect(() => { load(); }, []);
  const offers = items.filter((it: any) => (it.status === 'offered' || it.state === 'offered') && (it.assignmentId || it.id));
  return (
    <div className="card">
      <h2>Pending assignments</h2>
      {offers.length === 0 && <div className="muted">No open offers.</div>}
      {offers.map((it: any, i: number) => (
        <div key={i} style={{ marginBottom: 6 }}>
          <strong>{it.kind || 'assignment'}</strong> {shortId(it.assignmentId || it.id)} —{' '}
          <AssignmentActions assignmentId={it.assignmentId || it.id} />
        </div>
      ))}
    </div>
  );
}

// ------- root App -------
export default function App() {
  const [user, setUser] = useState<any>(null);
  const [tab, setTab] = useState('work');
  const [bootstrap, setBootstrap] = useState<any>(null);

  useEffect(() => {
    if (!user) return;
    (async () => {
      try { setBootstrap(await api.bootstrap()); }
      catch { /* bootstrap is informational */ }
    })();
  }, [user]);

  if (!user) return <Login onAuth={setUser} />;

  const role = getActiveRole() || (user.roles && user.roles[0]);
  const tabs = TABS_BY_ROLE[role] || [{ id: 'work', label: 'My work' }];

  async function signOut() {
    // Scenario: sign_out_ends_authenticated_session
    try { await api.signOut(); } catch { /* ignore */ }
    setToken(null); setActiveRole(null);
    setUser(null);
  }
  function changeRole(r: string) {
    api.selectActiveRole(r).catch(() => { /* best effort */ });
    setUser({ ...user, _activeRole: r });
  }

  return (
    <>
      <Header user={user} onSignOut={signOut} onRole={changeRole} />
      <nav className="tabs" aria-label="Primary navigation">
        {tabs.map(t => (
          <button key={t.id} aria-current={tab === t.id ? 'page' : undefined}
            onClick={() => setTab(t.id)}>{t.label}</button>
        ))}
      </nav>
      <main>
        {tab === 'work' && (<><WorkView /><InboxSection /></>)}
        {tab === 'check' && <Serviceability />}
        {tab === 'request' && <CreateRequest />}
        {tab === 'locate' && <LocationCapture />}
        {tab === 'capacity' && <CapacityView />}
        {tab === 'monitor' && <Monitor />}
        {tab === 'audit' && <AuditView />}
        {tab === 'admin' && <AdminView />}
        {bootstrap && (
          <div className="card">
            <h2>Session</h2>
            <dl className="kv">
              <dt>User id</dt><dd>{shortId(user.userId)}</dd>
              <dt>Roles</dt><dd>{(user.roles || []).map((r: string) => (
                <span key={r} className="badge" style={{ marginRight: 4 }}>{ROLE_LABEL[r] || r}</span>
              ))}</dd>
              <dt>Active role</dt><dd>{ROLE_LABEL[role] || role}</dd>
            </dl>
          </div>
        )}
      </main>
    </>
  );
}"}

